// Акафісти з AlexandrKozlovskiy/OrthodoxCalendar (Apache-2.0), Київський ізвод: транслітерація правилами віра.укр.
// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст преподобному Никодиму Святогорцю","e":"Akathist to our Venerable Father Nicodemus the Athonite","secs":[{"h":"Кондак 1","ps":["Я́ко боже́ственнаго жи́тельства таї́нника ізря́днаго і благоче́стія богоно́снаго учи́теля Правосла́вная Це́рков тя почита́єть: с небесе́ бо дарова́ніє приє́м, озаря́єши боже́ственними твої́ми писа́нії вопію́щия ті:","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Ікос 1","ps":["А́нгел нра́ви і мно́гий ра́зумом, Никоди́ме, на Афо́ні яви́лся єси́; а́нгельськоє бо іми́й житіє́, ангелоле́пним гла́сом із'ясни́л єси́ оте́чеськая писа́нія, і́миже просвіща́єши вопію́щия:","Ра́дуйся, Наксі́йськоє благоукраше́ніє;","ра́дуйся, Афонськоє озаре́ніє.","Ра́дуйся, оте́чеських догма́тов ізложе́ніє;","ра́дуйся, святи́х глаго́л із'ясне́ніє.","Ра́дуйся, висото́ мудрова́нія і прему́дрости ріко́;","ра́дуйся, глубино́ боже́ственнаго ві́дінія і сокро́вище любве́.","Ра́дуйся, я́ко показа́лся єси́ кни́жник богоно́сний;","ра́дуйся, я́ко толковни́к єси́ богоглаго́ливий.","Ра́дуйся, світи́льниче нра́вов че́стности;","ра́дуйся, пла́менниче го́рнія сві́тлости.","Ра́дуйся, і́мже ві́рнії утвержда́ються;","ра́дуйся, і́мже вразі́ устраша́ються.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 2","ps":["Житія́ освяще́нна ізді́тська іски́й, я́ко о́трасль боже́ственних роди́телей, мирськи́й оста́вил єси́ мрак, і ко Спа́су Христу́ устреми́лся єси́, Єму́же неукло́нні слі́дуя, Никоди́ме, вдохнове́н взива́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом богоприя́тним, я́ко уя́звлен боже́ственним жела́нієм, прише́л єси́ в Го́ру Афо́нськую, і доброді́тельним жи́тельством ко гора́м возви́сился єси́ ві́чним, по Дави́ду, Никоди́ме, сли́ша от нас сицева́я:","Ра́дуйся, житія́ преподо́бнаго сокро́вище;","ра́дуйся, сві́та невеще́ственнаго прия́телище.","Ра́дуйся, і́ноком Афо́нським о́бразе;","ра́дуйся, благоче́ствующих всіх утвержде́ніє.","Ра́дуйся, у́ме богонауче́нний, небе́сних ми́слей іспо́лненний;","ра́дуйся, уста́ богодви́жная богодохнове́нних уче́ній.","Ра́дуйся, я́ко от ми́ра всеці́ло удали́лся єси́;","ра́дуйся, я́ко во Афо́ні ко го́рнім напра́вился єси́.","Ра́дуйся, ли́ка преподо́бних прича́стниче;","ра́дуйся, ві́рним ве́лій учи́телю.","Ра́дуйся, враго́в поража́яй помишле́нія;","ра́дуйся, ду́ші утвержда́яй неради́вия.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 3","ps":["На сла́ву Госпо́дню у́мні взира́яй, очи́стив себе́ от веще́ственних, небе́сним наставля́яй показа́лся єси́, богоглаго́ливий Никоди́ме, ді́лом і сло́вом вся к Бо́гу управля́я вопію́щия: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй се́рдце твоє́ огне́м пали́мо стра́ха Бо́жия, неколеби́мо а́нгельськоє проше́л єси́ житіє́, і я́же в нем благода́ті, я́ко Ду́хом просвіще́н, Никоди́ме, із'ясня́єши зову́щим:","Ра́дуйся, сто́лпе воздержа́нія;","ра́дуйся, таї́нниче безстра́стія.","Ра́дуйся, воспери́вий ум к небе́сним;","ра́дуйся, стяжа́вий отту́ду неізглаго́ланная.","Ра́дуйся, благода́ті Духо́вния до́ме світови́дний;","ра́дуйся, селе́ніє многоці́нноє жи́тельства доброді́тельнаго.","Ра́дуйся, я́ко рі́ки уче́ній істоча́єши;","ра́дуйся, я́ко пото́ки страсте́й ізсуша́єши.","Ра́дуйся, Христо́вим обогати́вийся осія́нієм;","ра́дуйся, вра́жиє умертви́вий возноше́ніє.","Ра́дуйся, глаго́лов душепита́тельних гу́сли;","ра́дуйся, пі́сней богому́дрих цівни́це.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 4","ps":["Ревни́тель богодохнове́нний яви́лся єси́ отце́в преподо́бних, умертви́в себі́ су́щим в ми́рі, і учи́телей свяще́нних отпечатле́ніє і уста́ богодви́жная: бога́тая бо ті даде́ся благода́ть, Никоди́ме, вопію́щу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сконча́л єси́ богому́дре преподо́бную жизнь твою́, разли́чним іскуше́нієм противоста́в, і я́коже зла́то во огні́, іскуше́н скорбми́, Никоди́ме, учи́тель богому́дрий в дія́нії яви́лся єси́ взива́ющим:","Ра́дуйся, но́вий в преподо́бних;","ра́дуйся, богодохнове́нний во учи́теліх.","Ра́дуйся, наставля́яй на́ше помишле́ніє;","ра́дуйся, разруша́яй Велія́рово безу́міє.","Ра́дуйся, сло́вом благода́тним управля́яй ду́ші;","ра́дуйся, мечу́, при́сно посіця́яй страсте́й вини́.","Ра́дуйся, я́ко очища́єши серде́чния скве́рни;","ра́дуйся, я́ко явля́єши боже́ственная дая́нія.","Ра́дуйся, пла́менниче Прему́дрости лу́чшія;","ра́дуйся, мо́лніє на беснова́ніє ху́ждшеє.","Ра́дуйся, світи́льниче к живо́тним преспе́янієм;","ра́дуйся, світи́ло к боже́ственним возвише́нієм.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 5","ps":["Богоглаго́ливий язи́к приє́м, богогла́сне, сви́шнім дохнове́нієм дви́жим, глаго́ли жи́зні ві́чния і я́же в боже́ственних отці́х неудобопости́жная всему́дре із'ясни́л єси́, вся сподвиза́я Бо́гові пі́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Да воспери́ши к Бо́гу, богоно́сне, ума́ твоєго́ движе́нія вся, хране́ніє чувств тве́рдо проше́л єси́, єму́же науча́єши хотя́щия улучи́ти боже́ственнаго єдине́нія, во є́же пі́ти ті, о́тче, си́це:","Ра́дуйся, боже́ственних возвісти́телю;","ра́дуйся, от ху́ждшаго неві́дінія ізба́вителю.","Ра́дуйся, боже́ственному науча́яй по́двигу;","ра́дуйся, небе́снаго яви́телю мудрова́нія.","Ра́дуйся, широто́ боже́ственнаго ра́зума і прему́дрий наста́вниче;","ра́дуйся, скрижа́ле богопечатле́нная Духо́внаго віща́нія.","Ра́дуйся, Уті́шителя пречестни́й сосу́де;","ра́дуйся, правосла́вних богода́нная крі́посте.","Ра́дуйся, ча́ше душепита́тельнаго не́ктара;","ра́дуйся, сві́та трисо́лнечнаго іспо́лненний.","Ра́дуйся, пра́вило отше́льником в ді́ліх;","ра́дуйся, о́бразе учи́телем в словесі́х.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 6","ps":["Вертогра́д боже́ственних благода́тей се́рдце соверши́в, Никоди́ме, жи́тельством твої́м, \"Вертогра́д благода́тей\", я́ко воі́стину іспо́лнь благоуха́нія благода́тнаго, твою́ кни́гу наре́кл єси́, є́юже наслажда́ющеся, вопіє́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в на Горі́ Афо́нстій, я́ко новоявле́нная звізда́, просвіща́єши Христо́ву Це́рков доброді́телей твої́х заря́ми, неботаї́нниче Никоди́ме преподо́бне; отню́дуже возжиза́ємі сві́том твої́м зове́м:","Ра́дуйся, звіздо́ церко́вная;","ра́дуйся, све́точу благоче́стія.","Ра́дуйся, богосло́вов дре́вніх із'ясне́ніє;","ра́дуйся, чужди́х уче́ній низверже́ніє.","Ра́дуйся, боже́ственних преда́ній храни́телю і тайноводи́телю;","ра́дуйся, доброді́тельних дія́ній світоно́сче свяще́нний.","Ра́дуйся, я́ко облича́єши уче́нія нововво́дная;","ра́дуйся, я́ко явля́єши доброді́телі богода́нния.","Ра́дуйся, Бо́жий служи́телю теплі́йший;","ра́дуйся, ві́рних защи́тниче неколеби́мий.","Ра́дуйся, раю́ многоразли́чния прему́дрости;","ра́дуйся, світи́ло є́же во Христі́ науче́нія.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 7","ps":["Пребива́яй в Горі́ Афо́нстій, я́коже в го́рниці, усе́рдною моли́твою і посто́м Духо́вную благода́ть, прему́дре, прия́л єси́, та́їнственно в тя все́льшуюся, я́коже апо́столи, ї́хже подража́тель яви́лся єси́, взива́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Побі́ду благочести́вим уче́ніє твоє́ подає́ть, ві́рно поуча́ющимся, Никоди́ме, о́тче свяще́нний, проти́ву страсте́й і вся́кия є́ресі: во Святі́м бо Ду́сі ді́йствуєть при́сно вопію́щим:","Ра́дуйся, побі́до правосла́вних;","ра́дуйся, паде́ніє злосла́вних.","Ра́дуйся, Це́ркве ве́лій учи́телю;","ра́дуйся, святи́м дре́внім ра́вне.","Ра́дуйся, я́ко бога́тство оста́вил єси́ нам книг свяще́нних;","ра́дуйся, я́ко прекраща́єши вся́коє убо́жество страсте́й.","Ра́дуйся, до небесе́ досяза́яй сто́лпе богопросвіще́нний;","ра́дуйся, Уті́шителя світи́льниче невече́рній.","Ра́дуйся, о́блаче, осіня́яй ві́рния;","ра́дуйся, свіще́, возсіява́ющая лу́чшая.","Ра́дуйся, боже́ственних догма́тов пропові́дниче;","ра́дуйся, струй невеще́ственних істо́чниче.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 8","ps":["Диви́ть помишле́нія ві́рних, богоглаго́ливе, мно́жество прему́дрих писа́ній твої́х: ти бо прему́дростію боже́ственною і си́лою небе́сною, Никоди́ме, пи́шеши і віща́єши, преподо́бне, і вся побужда́єши пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Всю Це́рков, я́коже богоде́тельнії сві́ти, твоя́ богопреда́нная словеса́ просвіща́ють, о́тче, та́їнственні, і к соверше́ннійших разумі́нію веду́ть я́же в сія́ приниця́ющия і вопію́щия ті єдиногла́сне:","Ра́дуйся, трубо́ неізрече́нних;","ра́дуйся, таї́нниче небе́сних.","Ра́дуйся, Ду́ха кни́жниче богоглаго́ливий;","ра́дуйся, от сви́шняго вдохнове́нія науче́нний.","Ра́дуйся, я́ко боже́ственная вла́га ті даде́ся с небесе́;","ра́дуйся, я́ко облагодати́лся єси́ от руки́ Бо́жия.","Ра́дуйся, богосло́вія та́їнственнаго гу́сли;","ра́дуйся, богоглаго́ланія небе́снаго цівни́це.","Ра́дуйся, страсте́й отсіця́яй те́рніє; ра́дуйся, душ очища́яй ни́ву.","Ра́дуйся, Бо́жия благоутро́бія язи́че; ра́дуйся, ві́рних правосла́вних сла́во.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 9","ps":["К подвиго́м наставля́я проти́ву враго́в ми́сленних, Никоди́ме, преподо́бних ісполне́ніє, \"Неви́димую брань\" нариця́єши ю́же прему́дре списа́л єси́ кни́гу, свя́те: от сея́ бо науча́ємся к Бо́гу возводи́тися, пою́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Спа́сових пра́здников рече́нія богодохнове́нная і пі́сні всему́дрия в широту́ распространя́я і глубину́, ю́же в них благода́ть всім по́дал єси́, є́юже ду́ші веселя́ться, Никоди́ме, тебі́ вопію́щих:","Ра́дуйся, пі́сней толкова́телю боже́ственних;","ра́дуйся, дщи́ці слове́с святи́х.","Ра́дуйся, ві́янія боже́ственнаго сокро́вищнице;","ра́дуйся, Це́ркве Христо́ви украше́ніє.","Ра́дуйся, Ду́ха сокро́вище і храни́лище доброді́телей;","ра́дуйся, орга́не богодохнове́нний пі́сней духо́вних.","Ра́дуйся, я́ко очища́єши ві́рних сердця́;","ра́дуйся, я́ко проізлива́єши живоно́сная ороше́нія.","Ра́дуйся, душ наста́вниче богому́дрий;","ра́дуйся, честни́м отце́м равноче́стний.","Ра́дуйся, ума́ хране́нію науча́яй;","ра́дуйся, ра́дость та́їнственную возсіява́яй.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 10","ps":["Усти́ боговіща́нними і руко́ю, двиза́ємою Ду́ха благода́тію, о́тче, духо́вних степе́ней із'ясня́я в широті́ сми́сли, лі́ствицю і́ну поста́вил єси́ жела́ющим Го́сподеві пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Прему́дрости боже́ственния вла́га, я́коже Соломо́ну, даде́ся ті, Никоди́ме, отню́дуже Це́ркве учи́тель прему́дрий яви́лся єси́ і пресла́вний, на вся лу́чшая наставля́я, о́тче, зову́щия:","Ра́дуйся, у́ме богосло́вія;","ра́дуйся, струє́ боговіща́нія.","Ра́дуйся, пото́че наслажде́нія духо́внаго;","ра́дуйся, во словесі́х і ді́ліх пресві́тлий.","Ра́дуйся, віті́є многому́дрий глаго́л живо́тних;","ра́дуйся, уста́ блаже́нная гла́са Духо́внаго.","Ра́дуйся, насади́телю доброді́телей небе́сних;","ра́дуйся, іскорени́телю нра́вов злі́йших.","Ра́дуйся, те́плия моли́тви водворе́ніє;","ра́дуйся, ві́рних богода́нноє хвале́ніє.","Ра́дуйся, Бо́жий песнопе́вче богоглаго́ливий;","ра́дуйся, вождю́ наш богоно́сний.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 11","ps":["Возви́сив ума́ твоєго́ к Бо́гу стремле́нія, умертви́л єси́ плотська́я движе́нія, і, боже́ственним сві́том озаре́н, явле́нне во Афо́ні просія́л єси́, сло́вом і ді́лом, преподо́бне, к Бо́гу направля́я вопію́щия: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том Уті́шителевим прему́дрих писа́ній твої́х благода́ть, Никоди́ме, везді́ сія́єть і вдиха́єть в ду́ші та́їнственноє благоуха́ніє, і́мже страсте́й ізбавля́ємся злово́нія, взива́юще:","Ра́дуйся, цві́те ра́йський;","ра́дуйся, тро́сте Уті́шителева.","Ра́дуйся, мирополо́жнице боже́ственния бла́гости;","ра́дуйся, благоуха́ніє житія́ чи́стаго.","Ра́дуйся, ми́ро всеблагово́нноє подви́жничеськия жи́зні;","ра́дуйся, арома́те небе́сний жи́тельства духо́внаго.","Ра́дуйся, тайнописа́телю святи́х догма́тов;","ра́дуйся, краснопи́сче свяще́нних сми́слов.","Ра́дуйся, свире́ле пі́сней благода́тних;","ра́дуйся, ли́ку святи́х сопричте́нний.","Ра́дуйся, душ утвержде́ніє коле́блющихся;","ра́дуйся, прему́дрий мона́хов наста́вниче.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть і води́тельство к путе́м спаси́тельним і вся́цій по́льзі боже́ственній во Святі́м Ду́сі при́сно книг твої́х мно́жество, о Никоди́мі, подає́ть і веде́ть к боже́ственній сла́ві вопію́щия: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще тебі́ піснь, я́ко учи́теля вели́каго і боже́ственнаго і прему́драго наста́вника Це́ркве Христо́ви, о боговеща́нні, тя почита́єм, Никоди́ме: но не преста́й, свя́те, вся просвіща́ти зову́щия:","Ра́дуйся, Афо́на ве́лія сла́во;","ра́дуйся, На́ксоса боже́ственная похвало́.","Ра́дуйся, мона́шествующих світи́ло присносві́тлоє;","ра́дуйся, правосла́вних пла́менниче неусипа́ємий.","Ра́дуйся, о́бразе і пра́вило і́ноков богоприя́тних;","ра́дуйся, да́ре і ві́нче безмо́лвников благогові́йних.","Ра́дуйся, Це́ркве стіно́ неколеби́мейшая;","ра́дуйся, благоче́стія світи́льниче світоза́рнійший.","Ра́дуйся, і́мже восприє́млем лу́чшая;","ра́дуйся, і́мже отвраща́єм ху́ждшая.","Ра́дуйся, Богоро́диці таї́нниче;","ра́дуйся, соіме́нних тебі́ предста́телю.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 13","ps":["О Никоди́мі о́тче, Гори́ Афо́нськия чу́до і всея́ Це́ркве сла́во, настоя́щеє на́ше приноше́ніє ми́лостивно прийми́ і подава́й всім світ боже́ственний моли́твами твої́ми, я́ко да при́сно Бо́гові вопіє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел нра́ви і мно́гий ра́зумом, Никоди́ме, на Афо́ні яви́лся єси́; а́нгельськоє бо іми́й житіє́, ангелоле́пним гла́сом із'ясни́л єси́ оте́чеськая писа́нія, і́миже просвіща́єши вопію́щия:","Ра́дуйся, Наксі́йськоє благоукраше́ніє;","ра́дуйся, Афонськоє озаре́ніє.","Ра́дуйся, оте́чеських догма́тов ізложе́ніє;","ра́дуйся, святи́х глаго́л із'ясне́ніє.","Ра́дуйся, висото́ мудрова́нія і прему́дрости ріко́;","ра́дуйся, глубино́ боже́ственнаго ві́дінія і сокро́вище любве́.","Ра́дуйся, я́ко показа́лся єси́ кни́жник богоно́сний;","ра́дуйся, я́ко толковни́к єси́ богоглаго́ливий.","Ра́дуйся, світи́льниче нра́вов че́стности;","ра́дуйся, пла́менниче го́рнія сві́тлости.","Ра́дуйся, і́мже ві́рнії утвержда́ються;","ра́дуйся, і́мже вразі́ устраша́ються.","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Кондак 1","ps":["Я́ко боже́ственнаго жи́тельства таї́нника ізря́днаго і благоче́стія богоно́снаго учи́теля Правосла́вная Це́рков тя почита́єть: с небесе́ бо дарова́ніє приє́м, озаря́єши боже́ственними твої́ми писа́нії вопію́щия ті:","Ра́дуйся, о́тче Никоди́ме, Гори́ Святи́я сла́вноє украше́ніє."]},{"h":"Молитва","ps":["О богодохнове́нний і вселе́нський і́стини учи́телю, ізря́дная Святоімени́тия Гори́ похвало́, світлі́йшая звіздо́ Правосла́вния Це́ркве Собо́рния, всепреподо́бний і святи́й о́тче Никоди́ме! Даждь нам просвіще́ніє моли́твами твої́ми во ісполне́ніє боже́ственния во́лі, напра́ви стопи́ на́ша ко стезя́м доброді́тельнаго житія́, осіни́ нас да́нною тебі́ благода́тію і вразуми́ ум наш, во є́же разумі́ти богому́драя поуче́нія твоя́, да обря́щем в них покая́ніє, ісціле́ніє, ра́дость, мир, кро́тость, поко́й, любо́в, і а́ще что добро́ і бла́го і спаси́тельно, і в конці́ живо́т ві́чний, і моли́ся всегда́ ко Го́споду о всіх нас, і́скренні лю́б'ящих тя і на всяк день і час призива́ющих оте́чеськую твою́ бла́гость і по́мощ. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Му́дрости благода́тію, о́тче, украше́нний, / труба́ богогла́сная показа́лся єси́ Ду́ха / і доброді́телей наста́вник, Никоди́ме Богоглаго́ливий, / всім бо подає́ши спаси́тельная уче́нія, / житія́ чи́стаго показу́я сія́ніє / бога́тством Бо­же́ственних твої́х слове́с, // і́миже, я́ко світ, ми́рові возсія́л єси́."]},{"h":"Інший тропар, глас 1","ps":["Світи́ло Афо́нськоє, і На́ксії о́трасль, / і Це́ркве всея́ богодухнове́ннаго учи́теля, / Никоди́ма, ві́рнії, да почти́м, / і́же, ісполня́яся му́дрости Боже́ственния, / уче́нія бо небе́сная і оби́льная ізлива́єть вопію́щим: / сла́ва просла́вльшему тя Христу́, / сла́ва вінча́вшему тя, // сла́ва подаю́щему тобо́ю нам по́мощ."]},{"h":"Кондак, глас 8","ps":["Я́ко таї́нника ізря́днійшаго доброді́тельнаго житія́ і благоче́стія, / богоно́снаго учи́теля Правосла́вія, пра́зднуєть тя Це́рков, / с Небе́с бо дарова́нія приє́мий, / озаря́єши Боже́ственними твої́ми писа́нії вопію́щих ті: // ра́дуйся, о́тче Никоди́ме."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Никоди́ме, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Симеону, Новому Богослову","e":"Akathist to our Venerable Father Symeon the New Theologian","secs":[{"h":"Кондак 1","ps":["Я́ко та́їнственнаго богосло́вія боже́ственний орга́н і Сві́та Трисо́лнечнаго жили́ще, Богосло́ве Симео́не, тя восхваля́єм. Но я́ко іспо́лнь Ду́ха осія́ньми, освіти́ луча́ми благода́тей твої́х вопію́щия ті:","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Ікос 1","ps":["Ангелоподо́бен яви́лся єси́ доброді́телей преуспея́ньми, богому́дре Симео́не Богосло́ве, і а́нгельським твої́м гла́сом богосло́виши я́же па́че ума́ та́їнства. Ті́мже твоє́й сві́тлости див'я́щеся всі вопіє́м:","Ра́дуйся, і́мже Тро́йця воспіва́ється;","ра́дуйся, і́мже тлі́ніє попира́ється.","Ра́дуйся, Трисо́лнечнаго Сві́та обита́лище;","ра́дуйся, небе́сния жи́зні созерца́ніє.","Ра́дуйся, висото́ боже́ственнаго ра́зума, неудо́б ісправи́мая мно́гими;","ра́дуйся, глубино́ житія́ лу́чшаго, вся́чеськия доброді́телі ра́ди.","Ра́дуйся, я́ко показа́лся єси́ Це́ркве сія́ніє;","ра́дуйся, я́ко яви́лся єси́ богосло́вов весе́ліє.","Ра́дуйся, луче́ невеще́ственних осія́ній;","ра́дуйся, мо́лніє проти́ву веще́ственних воображе́ній.","Ра́дуйся, і́мже богосло́ві тайново́дствуються;","ра́дуйся, і́мже новосло́вці зауща́ються.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 2","ps":["О́ко душі́ твоєя́ житіє́м ізря́дним очи́стив ди́вно, узрі́л єси́ невеще́ственнаго сві́та явле́нія, под'є́м і́го Христо́во, преподо́бне, і, впери́вся Ду́хом, Симео́не Боговдохнове́нне, взива́л єси́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний іми́й, разу́мні отре́клся єси́ досто́їнств мирськи́х вседу́шні і, роди́телей любо́в презрі́в, ко оби́телі Студи́йстій ра́дуяся прите́кл єси́: Христу́ бо послі́довал єси́, сли́ша от всіх сицева́я:","Ра́дуйся, Христо́ви любве́ сокро́вище;","ра́дуйся, сві́та невеще́ственнаго прия́телище.","Ра́дуйся, а́нгельському житію́ подража́яй;","ра́дуйся, бісо́вськия де́рзости отвраща́яй.","Ра́дуйся, сосу́де многоці́нний дохнове́нія боже́ственнаго;","ра́дуйся, мечу́ богокова́нний на пристра́стіє веще́ственноє.","Ра́дуйся, я́ко прия́л єси́ в душі́ огнь небе́сний;","ра́дуйся, я́ко всему́дре ізбра́л єси́ лу́чшеє.","Ра́дуйся, страсте́й те́рніє історга́яй;","ра́дуйся, душі́ ни́ву обновля́яй.","Ра́дуйся, плодо́в ді́лателю безсме́ртних;","ра́дуйся, благ іспо́лнивийся нетлі́нних.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 3","ps":["Си́лу в по́двизі і во мно́зім разумі́нії приє́м, Симео́не, с небесе́ і в послуша́нії ста́рчестем соверши́вся, плотсько́є подчини́л єси́ мудрова́ніє, прему́дрости же лу́чшія іспо́лнился єси́ і Тро́йце воспіва́єши: Аллилу́я."]},{"h":"Ікос 3","ps":["Ізлія́ся бога́тая благода́ть устна́ма твої́ма, і вла́га ті даде́ся прему́дрости; отню́дуже богосло́вія струї́ Це́ркві істочи́л єси́, преподо́бне, і напоя́єши словеси́ твої́ми помишле́нія вопію́щих:","Ра́дуйся, істо́чниче богосло́вія;","ра́дуйся, пла́меню богому́дрія.","Ра́дуйся, ріко́ вод благода́тних;","ра́дуйся, сокро́вище наставле́ній духо́вних.","Ра́дуйся, таї́нниче богопросвіще́нний висо́ких виді́ній;","ра́дуйся, устні́ богодви́жимеї небе́сних помишле́ній.","Ра́дуйся, я́ко вещества́ преше́л єси́ преді́ли;","ра́дуйся, я́ко догма́тов раскри́л єси́ сми́сли.","Ра́дуйся, жи́зні святи́я учи́телю;","ра́дуйся, честни́м а́нгелом ра́вне.","Ра́дуйся, хра́мі Тро́йці та́їнственний;","ра́дуйся, заре́ світи́льника небе́снаго.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 4","ps":["Живота́ боже́ственнаго ма́нна, і не́ктар безсме́ртний, і мед, із ка́мене істочи́вийся, боготво́рних твої́х уче́ній кни́га бива́єть, ду́ші очища́ющая і к боже́ственному соверше́нію наставля́ющая вопію́щих: Аллилу́я."]},{"h":"Ікос 4","ps":["Взя́лся єси́ к виді́нієм висо́ким, по Па́влу, і Ду́хом неізрече́нная узрі́л єси́, отню́дуже богосло́в прему́дрий, богосло́вствуя всім преми́рная язи́ком богоречи́вим, Симео́не, яви́лся єси́ вопію́щим:","Ра́дуйся, боже́ственний богосло́ве;","ра́дуйся, всему́дрий богоглаго́льниче.","Ра́дуйся, Іоа́нна вели́каго отпечатле́ніє;","ра́дуйся, Григо́рія боже́ственнаго подо́біє.","Ра́дуйся, орга́не многозву́чний висо́ких виді́ній;","ра́дуйся, псалти́рю одушевле́нний светоза́рних наставле́ній.","Ра́дуйся, я́ко вшел єси́ к незаходи́мому мра́ку;","ра́дуйся, я́ко узрі́л єси́ мир небе́сний.","Ра́дуйся, ві́рния ізумля́яй словеси́ твої́ми;","ра́дуйся, ду́ші устроя́яй нра́ви твої́ми.","Ра́дуйся, живота́ небе́снаго із'яви́телю;","ра́дуйся, Бо́га нам чу́дний яви́телю.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 5","ps":["Боже́ственним раче́нієм, о́тче, сла́дці уя́звлен, под'я́л єси́ небому́дренним ра́зумом іскуше́нія, ско́рби же і гоне́нія, і я́ко зла́то во огні́ іскуси́лся єси́, я́ко а́нгел же, свя́те, всім яви́лся єси́, Христу́ воспіва́я: Аллилу́я."]},{"h":"Ікос 5","ps":["Іспра́вил єси́ ума́ твоєго́ движе́нія, богому́дре, к сла́ві Спа́сові і іспо́лнь прему́дрости боже́ственния показа́лся єси́, Симео́не, Ду́хом Святи́м, возбужда́я к покая́нію с любо́вію ті вопію́щих:","Ра́дуйся, сто́лпе воздержа́нія;","ра́дуйся, о́бразе терпі́нія.","Ра́дуйся, тайнописа́телю му́дрий обоже́нія;","ра́дуйся, разруши́телю жесточа́йшаго окамене́нія.","Ра́дуйся, уста́ медоточи́вая, ка́плющая боже́ственную сла́дость;","ра́дуйся, о́блаче богонапоє́нний, ро́су жи́зні істоча́яй.","Ра́дуйся, я́ко апо́стольськую благода́ть із'явля́єши;","ра́дуйся, я́ко спаси́тельноє блиста́ніє возсіява́єши.","Ра́дуйся, світи́ло благода́ті всесві́тлоє;","ра́дуйся, звіздо́ Лу́чшаго незаходи́мая.","Ра́дуйся, істо́чниче вод живоно́сних;","ра́дуйся, све́точу глаго́лов богодохнове́нних.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 6","ps":["Очи́стився се́рдцем, по́двига ра́ди духо́внаго, іспо́лнился єси́ осія́ній боже́ственних, і всесві́тел священноді́йствуя явля́лся єси́ ученико́м твої́м, блаже́нне. Обоже́н бо прича́стієм, всехва́льне Симео́не, вопія́л єси́: Аллилу́я."]},{"h":"Ікос 6","ps":["Сія́я виді́нії, а́ки живи́й вні ми́ра і єди́ному Бо́гу соєдини́вийся, огнеобра́зен і богови́ден, і ра́достен лице́м, і кро́ток явля́лся єси́ всім, благогові́йно ті вопію́щим:","Ра́дуйся, цівни́це Уті́шителева;","ра́дуйся, дре́во ра́йськоє.","Ра́дуйся, і́же во веществі́ і тілесі́ безпло́тен;","ра́дуйся, і́же зра́ком і нра́ви равноа́нгелен.","Ра́дуйся, звіздо́ многосві́тлая Восто́ка та́їнственнаго;","ра́дуйся, колесни́це златоіспещре́нная ді́йствія боже́ственнаго.","Ра́дуйся, трубо́, возглаша́ющая піснь спасе́нія;","ра́дуйся, язи́че, подава́яй крі́пость богодарова́нную.","Ра́дуйся, сві́та боже́ственнаго сокро́вище;","ра́дуйся, стремле́нія о́гненнаго угаше́ніє.","Ра́дуйся, честни́х та́їнств зри́телю;","ра́дуйся, Бо́га трисо́лнечнаго служи́телю.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 7","ps":["Ве́лій во виді́ніїх і честни́х богозре́ніїх показа́лся єси́, Симео́не Богосло́ве, моли́твою бо у́мною є́же в Бо́зі восхище́нія та́їнство позна́л єси́, блаже́нне, я́ко і́ний Мойсе́й, взива́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Не́ктар живи́й нетлі́нія кни́га слове́с твої́х подає́ть ві́рним, Богосло́ве, Уті́шитель бо тобо́ю Це́ркві глаго́леть і провіщава́єть, і пробужда́єть вся вопія́ти ті, Симео́не, сицева́я:","Ра́дуйся, сла́во Це́ркве;","ра́дуйся, віті́є Богонача́лія.","Ра́дуйся, очища́яй душе́вная оскверне́нія;","ра́дуйся, просвіща́яй на́ша помишле́нія.","Ра́дуйся, пла́меню, пояда́яй те́рнія страсте́й;","ра́дуйся, у́ме, открива́яй у́мная і зряй.","Ра́дуйся, я́ко разріши́лся єси́ вещества́ плени́ць;","ра́дуйся, я́ко іспо́лнился єси́ богото́чних вод.","Ра́дуйся, зряй Бо́жия сія́нія;","ра́дуйся, ненави́дяй вра́жия зло́би.","Ра́дуйся, прему́дрих уче́ній наводне́ніє;","ра́дуйся, честни́х дарова́ній гу́сли.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 8","ps":["Стра́нноє чу́до явля́шеся, о́тче Симео́не, в тебі́, ізумля́юще і веселя́ще вся: боже́ственним бо богатя́ся просвіще́нієм, прему́дрих і разу́мних яви́лся єси́ прему́дрійший, неві́жда пре́жде, і ни́ні всему́дре Бо́гові поя́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь ізмени́вийся і к Бо́гові весь отше́д ізступле́нієм боже́ственнійшим, богому́дре, і по прича́стію обоже́н, к вожделі́нному возбужда́єши обоже́нію, Симео́не богосла́вне, с любо́вію ті вопію́щия:","Ра́дуйся, у́глю огня́ невеще́ственнаго;","ра́дуйся, сія́ніє сві́та боже́ственнаго.","Ра́дуйся, краснопи́сче обоже́нія всему́дрий;","ра́дуйся, потреби́телю лі́ності держа́внійший.","Ра́дуйся, добро́ту обоже́нія явля́яй ді́ятельні;","ра́дуйся, трезве́нію спаси́тельному науча́яй разу́мні.","Ра́дуйся, я́ко наставля́єши і́ночествующих ли́ки;","ра́дуйся, я́ко отвраща́єши враго́в полки́.","Ра́дуйся, на́ше просвіща́яй мудрова́ніє;","ра́дуйся, страсте́й прекраща́яй стремле́нія.","Ра́дуйся, ві́рним боже́ственную благода́ть подава́яй;","ра́дуйся, Бо́га за всіх умоля́яй.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 9","ps":["Стра́сті душе́вния очища́я уче́нії твої́ми святи́ми, ко обрі́тенію нас пробужда́єши, трезве́нієм і моли́твою, о́тче, многоці́ннаго ка́мене живо́тнаго, єго́же дре́вле погуби́хом; ті́мже ни́ні ко Христу́ возопії́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я богосло́вія та́їнственнаго показа́лся єси́, стяжа́в сви́шняго ра́зума: всего́ бо тя Уті́шитель привлече́, о́тче, я́коже благоволи́, і стра́нная і пресла́вная провіща́л єси́ вопію́щим:","Ра́дуйся, гла́се Бо́жий святи́й;","ра́дуйся, молча́ніє враго́в соверше́нноє.","Ра́дуйся, іспо́лнь небе́снаго тайнонауче́нія;","ра́дуйся, проро́че лу́чшаго раче́нія.","Ра́дуйся, віті́є богонауче́нний прему́дрости Бо́жия;","ра́дуйся, мечу́ обоюдуо́стрий проти́ву пре́лести вра́жия.","Ра́дуйся, я́ко учи́ши восхожде́нієм боже́ственним;","ра́дуйся, я́ко направля́єши к путі́ спасе́нія.","Ра́дуйся, Христо́ву ме́ртвость нося́й;","ра́дуйся, боже́ственноє осія́ніє нам подава́яй.","Ра́дуйся, да́ром сло́ва обогати́вийся;","ра́дуйся, всім боже́ственная глаго́лавий.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 10","ps":["Уста́ боже́ственная показа́лся єси́ і Но́вий Богосло́в Христо́вой Це́ркві, богому́дре, в не́йже но́вая і ве́тхая от сокро́вища отри́гну се́рдця твоєго́, я́ко кни́жник богоприя́тен, я́коже глаго́леть Спаси́тель, Єму́же поє́ши: Аллилу́я."]},{"h":"Ікос 10","ps":["Сві́та невеще́ственнаго боже́ственноє зерца́ло яви́лся єси́, прише́д ко открове́нієм боже́ственним, Богосло́ве о́тче Симео́не, і вся ві́рния зове́ши ко причаще́нію благи́м, ї́хже обрі́л єси́. Ті́мже ті жела́нієм вопіє́м:","Ра́дуйся, уста́ неізрече́нних;","ра́дуйся, о́ко небе́сних.","Ра́дуйся, светоза́рности боже́ственния сокро́вище;","ра́дуйся, дарова́ній святи́х водворе́ніє.","Ра́дуйся, розго́ многоплодоно́сная Лози́ живо́тния;","ра́дуйся, гро́зде всеспе́лий равноа́нгельнаго жи́тельства.","Ра́дуйся, я́ко к небе́сному жела́нію воспламеня́єши;","ра́дуйся, я́ко зако́н благода́тний явля́єши.","Ра́дуйся, Христа́ просла́вивий житіє́м твої́м;","ра́дуйся, ві́рния устроя́яй сло́вом твої́м.","Ра́дуйся, о́бразе свята́го стремле́нія;","ра́дуйся, раю́ ди́внаго безстра́стія.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 11","ps":["Вшед, Богосло́ве, в пресві́тлий мрак, прия́л єси́ во скрижа́ліх серде́чних богосло́вія та́їнственнаго богозапечатле́нния скрижа́ли в Ду́сі, і́миже тайново́дствуємся к боже́ственному раче́нію, вопію́ще: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ, Сві́ту трисо́лнечному прибли́жився, яви́лся єси́ ми́ру, я́коже глаго́леть Влади́ка, і просвіща́єши ду́ші на́ша і светотвори́ши твої́ми уче́нії, свя́те, і́миже мра́ка ізбавля́ємся страсте́й, любо́вію ті вопію́ще:","Ра́дуйся, я́ко світ в ми́рі возсія́вий;","ра́дуйся, крі́пость словесі́ прида́вий.","Ра́дуйся, ді́йства боже́ственнаго учи́телю;","ра́дуйся, в по́двизі небе́сний челові́че.","Ра́дуйся, трисо́лнечния благода́ті оби́теле явле́нная;","ра́дуйся, даро́в духо́вних орга́не боголе́пний.","Ра́дуйся, я́ко под'я́л єси́ іскуше́нія му́жественні;","ра́дуйся, я́ко подає́ши просвіще́ніє богода́нне.","Ра́дуйся, пра́вило преподо́бнаго житія́;","ра́дуйся, світи́льниче неізрече́ннаго обоже́нія.","Ра́дуйся, у́мная движе́нія облиста́яй;","ра́дуйся, на́ша сердця́ просвіща́яй.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 12","ps":["Ліє́ть во́ду боже́ственную, теку́щую, о́тче, в жизнь ві́чную, непреста́нні і благоуха́ніє істоча́єть живо́тноє і весели́ть мисль на́шу кни́га уче́ній твої́х, в не́йже поуча́ющеся вопіє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Песнососта́вний віне́ць честно́му ве́рху твоєму́ прино́сим, ча́да твоя́, о́тче, єго́же приє́м оте́чеськи, лучу́ боже́ственнаго сві́та нам да́руй: ві́рно бо к тебі́ притека́єм і не престає́м вопія́ти:","Ра́дуйся, отце́в добро́то;","ра́дуйся, преподо́бних украше́ніє.","Ра́дуйся, ієре́єв пра́вило свяще́ннійшеє;","ра́дуйся, і́ночествующих о́тче боже́ственнійший.","Ра́дуйся, богосло́вов похвало́, Богосло́ве чу́дний;","ра́дуйся, благоче́ствующих утвержде́ніє і тайноводи́телю сла́вний.","Ра́дуйся, Це́ркве богоза́рнійший сто́лпе;","ра́дуйся, правосла́вних небесносве́тлий світи́льниче.","Ра́дуйся, і́мже сві́та ісполня́ємся;","ра́дуйся, і́мже страсте́й ізбавля́ємся.","Ра́дуйся, му́дрий вождю́ твої́м ча́дом;","ра́дуйся, і нам при́сно предста́тельствуяй.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 13","ps":["О боже́ственний о́тче, Симео́не Богосло́ве, світи́ло Христо́ви Це́ркве, приє́м на́ша гла́си, сві́том благода́ті, в тебі́ су́щия, облиста́й благоче́стне пою́щия тя і Тро́йце вопію́щия: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["Ангелоподо́бен яви́лся єси́ доброді́телей преуспея́ньми, богому́дре Симео́не Богосло́ве, і а́нгельським твої́м гла́сом богосло́виши я́же па́че ума́ та́їнства. Ті́мже твоє́й сві́тлости див'я́щеся всі вопіє́м:","Ра́дуйся, і́мже Тро́йця воспіва́ється;","ра́дуйся, і́мже тлі́ніє попира́ється.","Ра́дуйся, Трисо́лнечнаго Сві́та обита́лище;","ра́дуйся, небе́сния жи́зні созерца́ніє.","Ра́дуйся, висото́ боже́ственнаго ра́зума, неудо́б ісправи́мая мно́гими;","ра́дуйся, глубино́ житія́ лу́чшаго, вся́чеськия доброді́телі ра́ди.","Ра́дуйся, я́ко показа́лся єси́ Це́ркве сія́ніє;","ра́дуйся, я́ко яви́лся єси́ богосло́вов весе́ліє.","Ра́дуйся, луче́ невеще́ственних осія́ній;","ра́дуйся, мо́лніє проти́ву веще́ственних воображе́ній.","Ра́дуйся, і́мже богосло́ві тайново́дствуються;","ра́дуйся, і́мже новосло́вці зауща́ються.","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Кондак 1","ps":["Я́ко та́їнственнаго богосло́вія боже́ственний орга́н і Сві́та Трисо́лнечнаго жили́ще, Богосло́ве Симео́не, тя восхваля́єм. Но я́ко іспо́лнь Ду́ха осія́ньми, освіти́ луча́ми благода́тей твої́х вопію́щия ті:","Ра́дуйся, преподо́бне Симео́не, сві́та боже́ственнаго таї́нниче."]},{"h":"Молитва","ps":["О богоно́сний і христоно́сний і духоно́сний о́тче Симео́не, Но́вий Богосло́ве, преподо́бних похвало́, ієреє́в сла́во, богосло́вов услажде́ніє, моли́тви у́мния учи́телю, Бо́га просла́вльшій і от Бо́га просла́вленний в житії́ твоє́м, па́че же по сме́рті, земни́й а́нгеле і небе́сний челові́че, ра́досте духо́вная і душе́вноє весе́ліє нам, смире́нним твої́м рабо́м і недосто́йним твої́м сино́м, со благогові́нієм і любо́вію пра́зднующим свяще́нную і світоно́сную па́м'ять твою́! Прийми́ піснь сію́, ю́же прино́сим ті я́ко дар нічто́жний і малі́йший, за вели́кия благода́тния да́ри, ї́хже всі наслади́хомся, приє́мше я от тебе́, із кни́ги свяще́нних слове́с твої́х, і не отве́ржи сію́, я́ко твоєго́ великолі́пія недосто́йну: отню́д бо не́мощни єсьми́, є́же досто́йно восхвали́ти тя, толи́каго богосло́ва ве́лія. І в житії́ сем сохраня́й нас моли́твами твої́ми от вся́каго вре́да душе́внаго і тіле́снаго, ви́димих же і неви́димих враг, моля́ непреста́нно І́же в Тро́йці Бо́га, да сподо́бит і нас, смире́нних, та́їнственно ощути́ти посреді́ се́рдця на́шего у́мная ді́йства боже́ственния благода́ті Свята́го Ду́ха, ю́же погуби́хом, уви́! Нераді́нієм на́шим і страстьми́; в бу́дущем же ві́ці ізба́ви ни твої́ми си́льними хода́тайстви от стра́шнаго осужде́нія і му́ки ві́чния, і сподо́би нас ві́чнаго блаже́нства во Христі́ Ісу́се, Го́споді на́шем, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со безнача́льним Єго́ Отце́м і Пресвяти́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Боже́ственноє озаре́ніє, Симео́не о́тче, / восприя́во в душі́ твоє́й, / світи́ло в ми́рі показа́лся єси́ світлі́йшеє, / разгоня́я того́ мракобе́сіє / і всіх увіря́я іска́ти, ю́же погуби́ша, благода́ть Ду́ха, / Єго́же прилі́жно моли́ // дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 3","ps":["Сві́том просвіще́н Трисо́лнечним, Богому́дре, / Богосло́в яви́лся єси́ Пребоже́ственния Тро́йці. / Сви́ше прему́дростію слове́с обогати́вся, / істочи́л єси́ Богому́дрія Боже́ственния струї́, / от ни́хже пію́ще, вопіє́м: // ра́дуйся, треблаже́нне Симео́не Богонауче́нне."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Симео́не, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Інокентію, єпископу Пензенському і Саратовському","e":"Akathist to St Innocent, Bishop of Penza and Saratov","secs":[{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і ди́вний благоче́стія подви́жниче, святи́телю о́тче Інноке́нтіє, восхваля́єм тя я́ко Правосла́вія побо́рника і па́губних оби́чаєв іскорени́теля. Ти же, імі́яй дерзнове́ніє ко Го́споду, дарова́вшему нам тя вели́каго моли́твенника і ско́раго в біда́х помо́щника, моли́ о па́стві твоє́й, зову́щей:","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Ікос 1","ps":["А́нгельським смире́нієм украси́в житіє́ твоє́, святи́телю о́тче Інноке́нтіє, от ю́ности Боже́ственную прему́дрость возлюби́л єси́, Ду́хом Святи́м освяще́н, луча́ми Христо́ва уче́нія всіх просвіща́я; сего́ ра́ди тебе́, на Небесі́ і на землі́ просла́вленному, во умиле́нії вопіє́м си́це:","Ра́дуйся, смире́нієм на го́ру доброді́телей возведе́нний;","ра́дуйся, ко А́нгельським лико́м на Небесі́ причте́нний.","Ра́дуйся, Це́ркве Правосла́вния па́стирю предо́брий;","ра́дуйся, па́стві своє́й от волко́в губи́тельних защи́тниче неустраши́мий.","Ра́дуйся, цілому́дрія ревни́телю ізя́щний;","ра́дуйся, о́бразе кро́тости драгоці́нний.","Ра́дуйся, Правосла́вія пропові́дниче неуста́нний;","ра́дуйся, архієре́ю Бо́жий сви́ше просла́вленний.","Ра́дуйся, я́ко зрі́нієм ра́ки моще́й твої́х нас утіша́єши;","ра́дуйся, я́ко істо́чник ісціле́ній оби́льно нам ізлива́єши.","Ра́дуйся, па́ству пе́нзенськую доброді́ланію науча́яй;","ра́дуйся, зе́млю Сара́товськую во ві́рі утвержда́яй.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 2","ps":["Ви́дів, святи́телю о́тче Інноке́нтіє, я́ко ві́ра правосла́вная во Оте́честві на́шем попира́ється от лжеучи́телей іносла́вних, потща́лся єси́ вседу́шно Христу́ послужи́ти і ві́ру і́стинную от єресе́й огради́ти, па́ству же от волко́в, расхища́ющих ю, защити́ти. Ми же, див'я́щеся таково́му твоєму́ дерзнове́нію, вопіє́м укрі́пльшему тя Го́споду: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний імі́я, ізмла́да Христу́ послужи́л єси́, вре́менния сла́сти во уме́ти вміня́я, того́ ра́ди благода́тію архієре́йства увінча́ тя Госпо́дь. Ми же подви́жничеськоє ізволе́ніє твоє́ воспіва́юще, вопіє́м ті си́це:","Ра́дуйся, путь пра́вий ізбра́вий;","ра́дуйся, сим неотсту́пно ше́дий.","Ра́дуйся, вся кра́сная ми́ра презрі́вий;","ра́дуйся, ду́шу свою́ доброді́тельми украси́вий.","Ра́дуйся, се́рдце своє́ Христу́ отве́рсто імі́вий;","ра́дуйся, страсте́м вхо́ди єго́ затвори́вий.","Ра́дуйся, послуша́нія вся і́ночеськая нелі́ностно проше́дий;","ра́дуйся, со стра́хом Бо́жиїм Же́ртву Безкро́вную приноси́вий.","Ра́дуйся, мона́хом пра́вило ізя́щнійшеє;","ра́дуйся, свяще́нником о́бразе благогові́йнійший.","Ра́дуйся, всім подвиза́ющимся до́брий наста́вниче;","ра́дуйся, тружда́ющимся спасе́нія ра́ди ско́рий помо́щниче.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 3","ps":["Си́лою сви́ше облече́ тя Госпо́дь, ти же, святи́телю о́тче Інноке́нтіє, взем крест свой, невозвра́тно Єму́ послі́довал єси́ і, уві́дів, я́ко і́го Христо́во бла́го і бре́м'я Єго́ легко́ єсть, воспі́л єси́ милосе́рдному Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я на скрижа́ліх се́рдця твоєго́ словеса́ боже́ственнаго Па́вла, і́стинний о́браз ві́рним яви́лся єси́, і нас вослі́д Христа́ ше́ствовати научи́, вопію́щих ті такова́я:","Ра́дуйся, Христо́в учениче́ і́стинний.","Ра́дуйся, во благові́стії апо́столом подо́бний;","Ра́дуйся, я́ко чистото́ю а́нгельською обле́клся єси́;","ра́дуйся, я́ко отце́м дре́внім во уче́нії подража́л єси́.","Ра́дуйся, да́ром прозрі́нія почте́нний;","ра́дуйся, іспові́дниче неустраши́мий.","Ра́дуйся, я́ко в по́двизіх свої́х вели́ким преподо́бним ра́вен бил єси́;","ра́дуйся, я́ко непреста́нно ко Го́споду моли́тви возноси́л єси́.","Ра́дуйся, ми́лостиню твори́ти ніколи́же оста́вивий;","ра́дуйся, па́м'ять сме́ртную на вся́кий час житія́ своєго́ імі́вий.","Ра́дуйся, благолі́пія хра́мов Бо́жиїх ревни́телю;","ра́дуйся, я́ко сам храм Го́споду яви́лся єси́.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 4","ps":["Вели́кому святи́телю Росто́вському Дими́трію не то́кмо ли́ком подо́бен бил єси́, но житіє́м і ді́ли свої́ми сему́ уподо́бился єси́, просвіща́я малове́рних, ві́рних же укріпля́я, нас же всіх науча́я вопи́ти Милосе́рдному Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Се Жени́х гряде́ть в полу́нощі, — та́ко воспі́л єси́, блаже́нне, благода́ть архієре́йства приє́м, не ра́бе, но дру́же Христо́в Інноке́нтіє, і Го́спода срі́тил єси́ душе́ю, любо́вію горя́щею, і нас в любві́ Боже́ственній укріпи́, зову́щих ті такова́я:","Ра́дуйся, я́ко си́ла Бо́жия соверши́ся в немощні́м тілесі́ твоє́м;","ра́дуйся, я́ко вся неду́ги со смире́нієм претерпі́л єси́.","Ра́дуйся, клевети́ і осужде́нія я́ко младе́нець незло́бивий прия́л єси́;","ра́дуйся, я́ко во обличе́нії нече́стія на ли́ця не взира́л єси́.","Ра́дуйся, ни́щих і си́рих пита́телю ізоби́льний;","ра́дуйся, оби́женних защи́тниче дерзнове́нний.","Ра́дуйся, оби́дящих многому́дренноє обличе́ніє;","ра́дуйся, учи́телю, па́ству, ті вві́ренную, ко спасе́нію наставля́яй.","Ра́дуйся, уни́ніє си́лою упова́нія на милосе́рдіє Бо́жиє побіди́вий;","ра́дуйся, с кро́тостію і смире́нієм і от прости́х поуче́нія прийма́вий.","Ра́дуйся, вся ко́зні вра́жия си́лою Бо́жиєю попра́вий; ра́дуйся, Бо́гу сла́вно угоди́вий.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 5","ps":["Возвели́чіте Го́спода со мно́ю, і вознесе́м і́м'я Єго́ вку́пі, — та́ко па́ству Сара́товськую в про́повіді призива́л єси́, ни́ні же ми с тобо́ю вку́пі вопіє́м Жизнода́вцю Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Непреста́нно в ке́лії колі́на преклоня́я, — Бо́же, ми́лостив бу́ди мні грі́шному, — взива́л єси́, і нам ми́лостива сотвори́ Влади́ку Небесе́ і землі́, тебі́ вопію́щим такова́я:","Ра́дуйся, і́м'я Госпо́днє я́ко ору́жіє проти́ву ко́зней дия́вольських імі́вий;","ра́дуйся, си́лу Бо́жию в немощні́м тілесі́ стяжа́вий.","Ра́дуйся, си́лою моли́тв твої́х вся наві́ти вра́жия разруши́вий;","ра́дуйся, благоче́стія сто́лпе, на ка́мені спаси́тельния ві́ри возведе́нний.","Ра́дуйся, по́двигом до́брим чад свої́х терпіли́вно научи́вий;","ра́дуйся, всего́ себе́ в ру́ці Бо́жії преда́вий.","Ра́дуйся, все жела́ніє ко Христу́ імі́вий;","ра́дуйся, в Бо́зі на́шем намі́реніє своє́ полага́вий.","Ра́дуйся, я́ко Христу́ сорасп'я́лся єси́;","ра́дуйся, я́ко сла́дость лице́м к лицю́ зрі́нія Єго́ ни́ні вкуша́єши.","Ра́дуйся, хода́таю наш неуси́пний;","ра́дуйся, світи́льниче ві́ри неугаси́мий.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 6","ps":["Ди́вним виді́нієм укріпи́ тя Госпо́дь при кончи́ні земна́го житія́ твоєго́: А́нгели Бо́жії прия́ша тя с собо́ю і в Небе́сния оби́телі вознесо́ша, іді́же ти поє́ши ни́ні Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Во сві́тлия о́ния оби́телі Бо́жия пресели́лся єси́, пречу́дне о́тче, словесе́м псалмопе́вця что́мим: Аз же, Го́споди, упова́ю на Тя. І нас во упова́нії сем сві́тлім укріпи́, пою́щих ті такова́я:","Ра́дуйся, А́нгелами на Не́бо вознесе́нний;","ра́дуйся, Небе́сния ра́дости єще́ на землі́ вкуси́вий.","Ра́дуйся, я́ко тебі́ Небеса́ отверзо́шася;","ра́дуйся, я́ко Госпо́дь в Небе́сния оби́телі всели́ тя.","Ра́дуйся, до кончи́ни житія́ твоєго́ о па́стві твоє́й попече́ніє імі́вий;","ра́дуйся, я́ко не́мощі тіле́сния чадолю́біє твоє́ не ума́лиша.","Ра́дуйся, я́ко Ду́хом Святи́м восходя́ от си́ли в си́лу, Небе́снаго Ца́рствія дости́гл єси́;","ра́дуйся, я́ко та́мо ни́ні со святи́ми ликовству́єши.","Ра́дуйся, я́ко і нас грі́шних на землі́ не оставля́єши;","ра́дуйся, я́ко ду́хом нам спребива́єши.","Ра́дуйся, моли́твами свої́ми нам помога́яй;","ра́дуйся, я́ко люби́ твоя́ ніка́коже оскуді́ на нас.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 7","ps":["Хотя́ просвіти́ти всіх ві́дінієм неізрече́нних суде́б Бо́жиїх, ди́вний списа́тель діл мину́вших бил єси́, в ни́хже прему́дрий Про́мисл Созда́теля, вся племена́ і язи́ки ко спасе́нію веду́щий, всім указа́л єси́. Ті́мже і ми Ще́дрому Бо́гу покланя́ємся і вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя чудотво́рця і моли́твенника дарова́ нам Человіколю́бець Госпо́дь, єгда́ за умноже́ніє беззако́нія оскуді́ во мно́гих люби́. Сего́ ра́ди твоєго́ є́же о нас предста́тельства про́сим, на всепокрива́ющую любо́в твою́ наді́ющеся: не оста́ви нас в годи́ну лю́тих іспита́ній, укріпля́я моли́твами твої́ми вопію́щих ті такова́я:","Ра́дуйся, я́ко моли́твами твої́ми зе́млю на́шу облагоуха́л єси́;","ра́дуйся, я́ко по́двиги твої́ми край наш освяти́л єси́.","Ра́дуйся, о па́стві твоє́й предста́телю неуси́пний;","ра́дуйся, помо́щниче наш во вся́ких біда́х і напа́стіх.","Ра́дуйся, списа́телю суде́б Бо́жиїх пречу́дний;","ра́дуйся, ті́ми вся ни наста́вивий.","Ра́дуйся, пропові́дниче велегла́сний;","ра́дуйся, ді́лателю вертогра́да Христо́ва прему́дрий.","Ра́дуйся, ві́рний і благи́й во́їне Царя́ Небе́снаго;","ра́дуйся, цівни́це духо́вная, Ду́ха Свята́го іспо́лненная.","Ра́дуйся, архієре́єв богодохнове́нноє украше́ніє;","ра́дуйся, благоче́стія тве́рдоє огражде́ніє.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє чу́до яви́ся всім, єгда́ честни́я і многоціле́бния мо́щі твоя́, а́ще і от безбо́жних пору́гани би́ша, обріто́шася па́ки. К сим у́бо припа́дающе, Бо́гу вопіє́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ во ви́шніх, но і нас, до́лу пове́рженних, не оставля́єши, святи́телю о́тче Інноке́нтіє, моле́нія на́ша сли́шиши і ско́ро ісполня́єши. Неотсту́пен у́бо пребу́ди от нас, вопію́щих ті такова́я:","Ра́дуйся, я́ко всіх прибіга́ющих к тебі́ заступа́єши;","ра́дуйся, я́ко врачева́нія нам істоча́єши.","Ра́дуйся, я́ко моле́нієм на́шим внима́єши;","ра́дуйся, я́ко во бла́го їх ісполня́єши.","Ра́дуйся, я́ко чудеси́ твої́ми ві́рния возвеселя́єши;","ра́дуйся, я́ко моще́й твої́х бі́си трепе́щуть.","Ра́дуйся, я́ко нас, гріхми́ омраче́нних, просвіща́єши;","ра́дуйся, я́ко смрад страсте́й на́ших отгоня́єши.","Ра́дуйся, я́ко тала́нт, Бо́гом да́нний тебі́, умно́жил єси́;","ра́дуйся, я́ко в ра́дость Го́спода твоєго́ вшел єси́.","Ра́дуйся, я́ко нас пред Престо́лом Бо́жиїм непреста́нно помина́єши;","ра́дуйся, я́ко в житії́ сем нас не оставля́єши.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 9","ps":["Всі правосла́внії лю́діє возра́довашася, єгда́ на Собо́рі святи́тельстім в ли́ці святи́х Це́рков Правосла́вная просла́ви тя. Ми же, іму́ще такова́го моли́твенника, вопіє́м возвели́чившему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї суєму́дреннії, тобо́ю посра́мленнії, недоумі́ють, что глаго́лати, си́лою бо Бо́жиєю укріпля́єм, сих дерзнове́нно обличи́л єси́. Ми же, взира́юще на пра́ведноє житіє́ твоє́ і на тве́рдоє ві́ри правосла́вния іспові́даніє, вопіє́м ті такова́я:","Ра́дуйся, Христо́м Бо́гом возлю́бленний;","ра́дуйся, си́лою сви́ше облече́нний.","Ра́дуйся, науче́ніє кни́жноє возлюби́вий;","ра́дуйся, к тому́ усе́рдіє імі́вий.","Ра́дуйся, ра́зум Боже́ственний стяжа́вий;","ра́дуйся, я́ко сло́во Бо́жиє умудри́ тя.","Ра́дуйся, преда́ній апо́стольських ві́рний блюсти́телю;","ра́дуйся, пра́вди Бо́жия ре́вностний храни́телю.","Ра́дуйся, просвіще́нний благода́тію;","ра́дуйся, учи́телю златослове́сний.","Ра́дуйся, ізгна́нний пра́вди ра́ди Христо́ви;","ра́дуйся, такови́х бо єсть Ца́рствіє Небе́сноє.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ па́ству твою́ от єресе́й і собла́знов, скве́рная уче́нія беззако́нних обличи́л єси́, пресла́вне о́тче Інноке́нтіє, Правосла́віє же кро́тостію прему́дрих слове́с твої́х утверди́л єси́ і научи́л єси́ ста́до твоє́ воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рдая і огра́да необори́мая бисть си́ла моли́тв твої́х, богоно́се о́тче Інноке́нтіє, сего́ ра́ди і ми, па́ства твоя́, к тебі́ с ві́рою прибіга́єм і усе́рдно мо́лим: бу́ди нам огражде́ніє крі́пкоє і ору́жіє, враги́ прогоня́ющеє, да не возра́дуються хотя́щії нам зла́я. Такова́го у́бо богодарова́ннаго помо́щника і засту́пника іму́ще, во весе́лії вопіє́м ті такова́я:","Ра́дуйся, па́стви твоєя́ до́брий первостоя́телю;","ра́дуйся, сумня́щихся крі́пкоє во ві́рі утвержде́ніє.","Ра́дуйся, зло́бу власте́й предержа́щих кро́тко претерпі́вий;","ра́дуйся, і́стину небоя́зненно їм віща́вий.","Ра́дуйся, гоне́нія і притісне́нія пра́вди ра́ди смире́нно приє́мий;","ра́дуйся, в домі́х благочести́вих чад твої́х приста́нище імі́вий.","Ра́дуйся, я́ко тобо́ю от всіх зол ізбавля́ємся;","ра́дуйся, я́ко твої́ми моли́твами ре́вности в правосла́вній ві́рі ісполня́ємся.","Ра́дуйся, я́ко тобо́ю і́стина утвержда́ється;","ра́дуйся, я́ко тобо́ю лицеприя́тіє і человікоуго́діє посрамля́ється.","Ра́дуйся, я́ко пресі́кл єси́ злочести́вих волне́ніє;","ра́дуйся, лю́дем пе́нзенським і сара́товським похвале́ніє.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє прино́сим тебі́, святи́телю о́тче Інноке́нтіє, і смире́нно про́сим тя: моли́ о нас Человіколю́бця Бо́га, да не отврати́ть лиця́ Своєго́ от нас, при́сно согріша́ющих і бла́гость Єго́ на всяк час преогорчева́ющих, но да ізба́вить нас от гріхо́в і прегріше́ній на́ших, найпа́че же сподо́бит в час кончи́ни на́шея покая́нія і Боже́ственних Та́їн прича́стія, да с тобо́ю в Небе́сних оби́теліх воспоє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник, во тьмі неві́рія сідя́щих просвіща́яй, бил єси́ в земні́м житії́ твоє́м, о́тче наш Інноке́нтіє. Просвіти́ у́бо моли́твами твої́ми і нас, в пучи́ні гріха́ погиба́ющих, да благода́рні вопіє́м тебі́ си́це:","Ра́дуйся, смире́нія і терпі́нія наста́вниче наш прему́дрий;","ра́дуйся, в моли́твах і бді́ніях учи́телю наш предо́брий.","Ра́дуйся, я́ко от суєсло́вія і суєму́дрія нас отвраща́єши;","ра́дуйся, я́ко в доброді́телі нас наставля́єши.","Ра́дуйся, я́ко в суєті́ мирсте́й і попече́ніїх жите́йських погря́зшим путь в Го́рняя указу́єши;","ра́дуйся, я́ко обремене́нних гріха́ми і скорбми́ мно́гими нікогда́же оставля́єши.","Ра́дуйся, і́стинний учениче́ Христо́в, всіх си́рих возлюби́вий;","ра́дуйся, го́рдих і жестокови́йних смири́вий.","Ра́дуйся, я́ко всіх, почита́ющих тя, от напа́стей і зол сохраня́єши;","ра́дуйся, я́ко всіх скорб'я́щих і болі́знующих, к заступле́нію твоєму́ притека́ющих, утіша́єши.","Ра́дуйся, світи́льниче, нас, потемне́нних гріхми́, любо́вію освеща́яй;","ра́дуйся, ми́ро, нас, беззако́нії смра́дними оскверне́нних, облагоуха́яй.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 12","ps":["Благода́ті сосу́д ізбра́нний бил єси́, святи́телю о́тче Інноке́нтіє; ті́мже восхваля́юще тя усе́рдно, мо́лим: проле́й те́плую моли́тву ко Го́споду за Оте́чество на́ше, да ізба́вимся от наше́ствія іноплеме́нних і междоусо́бних бра́ней, да в ми́рі і тишині́ воспоє́м Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще сла́вноє твоє́ к Небе́сним оби́телем восхожде́ніє, святи́телю о́тче Інноке́нтіє, прославля́єм равноа́нгельноє житіє́ твоє́ і во умиле́нії се́рдця сла́вим, хва́лим і велича́єм возвели́чившаго тя Го́спода, дарова́вшаго нам но́ваго моли́твенника і предста́теля, Єго́же умоли́ спасти́ся всім, пою́щим ті такова́я:","Ра́дуйся, житіє́м чи́стим А́нгелов удиви́вий;","ра́дуйся, по́двиги твої́ми челові́ков наста́вивий.","Ра́дуйся, нището́ю духо́вною сокро́вище Ца́рствія Бо́жия обріти́й;","ра́дуйся, пла́чем і скорбми́ вре́менними утіше́нія ві́чнаго сподо́бивийся.","Ра́дуйся, кро́тостію зе́млю пра́ведних наслі́дивий;","ра́дуйся, пра́вди на землі́ взиска́вий, на Небесі́х же пра́вдою Бо́жиєю насище́нний.","Ра́дуйся, ми́лостію і нищелю́бієм ми́лость ве́лію от Го́спода стяжа́вий;","ра́дуйся, о́чі серде́чния от скве́рни гріха́ очи́стивий і Бо́га узрі́вий.","Ра́дуйся, поноше́нія і непра́ведная гоне́нія Христа́ ра́ди претерпі́вий;","ра́дуйся, ізгна́нний пра́вди ра́ди і в Небе́сния оби́телі со сла́вою вше́дий.","Ра́дуйся, миротво́рче, си́ном Бо́жиїм нарече́нний;","ра́дуйся, мзду мно́гу на Небесі́х приє́мий.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 13","ps":["О пресла́вний святи́телю Христо́в Інноке́нтіє! Прийми́ от нас сіє́ ма́лоє моле́ніє, в похвалу́ тебі́ приноси́моє, і ізба́ви нас предста́тельством твої́м от бід і скорбе́й, да в житії́ сем вре́меннім сіте́й вра́жиїх і пре́лести бісо́вськия ізба́вльшеся, возду́шная мита́рства непреткнове́нно про́йдем і в Небе́сний Ієрусали́м всели́тися сподо́бимся, іді́же с тобо́ю Всеблаго́му Бо́гу на́шему воспоє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельським смире́нієм украси́в житіє́ твоє́, святи́телю о́тче Інноке́нтіє, от ю́ности Боже́ственную прему́дрость возлюби́л єси́, Ду́хом Святи́м освяще́н, луча́ми Христо́ва уче́нія всіх просвіща́я; сего́ ра́ди тебе́, на Небесі́ і на землі́ просла́вленному, во умиле́нії вопіє́м си́це:","Ра́дуйся, смире́нієм на го́ру доброді́телей возведе́нний;","ра́дуйся, ко А́нгельським лико́м на Небесі́ причте́нний.","Ра́дуйся, Це́ркве Правосла́вния па́стирю предо́брий;","ра́дуйся, па́стві своє́й от волко́в губи́тельних защи́тниче неустраши́мий.","Ра́дуйся, цілому́дрія ревни́телю ізя́щний;","ра́дуйся, о́бразе кро́тости драгоці́нний.","Ра́дуйся, Правосла́вія пропові́дниче неуста́нний;","ра́дуйся, архієре́ю Бо́жий сви́ше просла́вленний.","Ра́дуйся, я́ко зрі́нієм ра́ки моще́й твої́х нас утіша́єши;","ра́дуйся, я́ко істо́чник ісціле́ній оби́льно нам ізлива́єши.","Ра́дуйся, па́ству пе́нзенськую доброді́ланію науча́яй;","ра́дуйся, зе́млю Сара́товськую во ві́рі утвержда́яй.","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Кондак 1","ps":["Ізбра́нний уго́дниче Христо́в і ди́вний благоче́стія подви́жниче, святи́телю о́тче Інноке́нтіє, восхваля́єм тя я́ко Правосла́вія побо́рника і па́губних оби́чаєв іскорени́теля. Ти же, імі́яй дерзнове́ніє ко Го́споду, дарова́вшему нам тя вели́каго моли́твенника і ско́раго в біда́х помо́щника, моли́ о па́стві твоє́й, зову́щей:","Ра́дуйся, святи́телю о́тче Інноке́нтіє, те́плий моли́твенниче о душа́х на́ших."]},{"h":"Молитва","ps":["О свя́тче Бо́жий, святи́телю Христо́в Інноке́нтіє, при́зри от сла́ви твоєя́ го́рнія і прийми́ моли́тви нас, грі́шних і недосто́йних рабо́в твої́х, зді пред о́бразом твої́м честни́м (іли́: святи́ми моща́ми твої́ми) припа́дающих і те́плі умоля́ющих тя, і принеси́ їх ко Престо́лу вся содержа́щаго в руці́ Своє́й Бо́га, Єму́же ти до́брі послужи́л єси́ во дні земна́го житія́ твоєго́. Умоли́, уго́дниче Бо́жий, Всеми́лостиваго Спа́са Христа́ за богода́нную твою́ па́ству, тя возлюби́вшую, да отжене́ть от земна́го оте́чества твоєго́ вся собла́зни, раздо́ри, нестроє́нія. Це́рков Христо́ву і град наш огради́ святи́ми твої́ми моли́твами от раско́лов, прельще́нія інове́рієм і наві́тов злих челові́к. Всіх же нас в єдиноми́слії і любві́ друг ко дру́гу соблюди́, да єди́німи усти́ і єди́нім се́рдцем воспоє́м всесвято́є і єдинодержа́вноє і́м'я Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 5","ps":["От ю́ности смире́нним нарече́нний, в мона́шестві же чистоті́ тезоіме́нний, духо́вной му́дрости люби́тель ти яви́лся єси́, златовещанний благоче́стія учи́тель і лжи́вих па́губних уче́ній обличи́тель, за І́стину безу́мними гони́мий, незло́біє і кро́тость пропові́давий, і па́ству Пензенськую ре́вностне паси́й, святи́телю всече́стне Інноке́нтіє, моли́ Христа́ нас умудри́ти во спасе́ніє."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Інноке́нтіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст рівноапостольному Миколаю, архієпископу Японському","e":"Akathist to the Equal-to-the-Apostles Nicholas, Archbishop of Japan","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от родо́в ру́ських на благові́стіє Христо́во в страні́ Япо́нськой, ду́шу твою́ полага́л єси́ за о́вці твоя́, утвержда́я їх во ві́рі і́стинній. Ті́мже по́двиги твоя́ почита́юще, хва́лим тя:","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Ікос 1","ps":["А́нгел, я́коже Тові́ї іногда́, спутеше́ствова тебі́, о́тче Нико́лає, єгда́ в млада́я лі́та твоя́ напра́вил єси́ стопи́ в страну́, дале́че отстоя́щую, да просвіти́ши лю́ди, во тьмі неві́дінія сідя́щия, сві́том Єва́нгелія Христо́ва. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, Смоле́нськия землі́ сла́вноє рожде́ніє;","ра́дуйся, от младе́нства храм Бо́жий возлюби́вий.","Ра́дуйся, в сиротствеі Богома́терію Одиги́трією не оста́вленний;","ра́дуйся, духо́вними уче́ньми умудре́нний.","Ра́дуйся, на бді́нії всено́щнем призва́ніє на труд апо́стольський приє́мий;","ра́дуйся, сла́дость ми́ра ні во что́же вміни́вий.","Ра́дуйся, чи́на а́нгельськаго і са́на свяще́ннаго удосто́єнний;","ра́дуйся, к неве́дящим спасе́нія ми́лости іспо́лненний.","Ра́дуйся, пропові́дати Єва́нгеліє вожделі́вий;","ра́дуйся, і да́льних я́ко бли́жніх возлюби́вий.","Ра́дуйся, гоне́нія за ві́ру не страши́вийся;","ра́дуйся, ко́зней вра́жиїх не убоя́вийся.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 2","ps":["Ви́дя по́двиги святи́теля Інноке́нтія, богому́драго просвіти́теля Сиби́рськаго і Алеу́тськаго, і от того́ благослове́ніє і наставле́ніє на путь свой приє́м, поревнова́л єси́ єму́, сло́во Бо́жиє лю́дем непросвіще́нним неуста́нно пропові́дуя і Го́сподеві поя́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум во смире́нії яви́л єси́, свя́тче, Го́споду моля́ся о є́же прия́ти я́сноє разумі́ніє язи́ка япо́нськаго: \"Ка́ко пропові́даю наро́ду чужде́му? Ка́ко отве́рзу уста́ неіску́сная, а́ще не Сам Ти наста́виши м'я?\" Ми же, див'я́щеся, ка́ко ти словеси́ богодохнове́нними па́ству твою́ свої́м єй наре́чієм поуча́л єси́, восхваля́єм тя:","Ра́дуйся, любо́вію Христо́вою вся побежда́вий;","ра́дуйся, духо́вния младе́нці словеси́ Єва́нгельськими пита́вий.","Ра́дуйся, вражду́ющия в ча́да любо́вію претвори́вий;","ра́дуйся, тіх гріхи́ креще́нієм оми́вий.","Ра́дуйся, уче́ньми неуста́нними ві́ру укрепля́вий;","ра́дуйся, наста́вник рачи́тельний і до́брий яви́вийся.","Ра́дуйся, пресви́теров япо́нських поста́вивий;","ра́дуйся, церко́вний чин устро́ївий.","Ра́дуйся, о страні́ Япо́нськой моли́твенниче;","ра́дуйся, согла́сія бра́тськаго побо́рниче.","Ра́дуйся, світи́льниче ві́ри правосла́вния;","ра́дуйся, сокро́вище кро́тости духо́вния.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго осіни́ і укріпи́ тя, о́тче, єгда́ прише́л єси́ в страну́ язи́чеськую, сме́рті ча́да своя́ предаю́щую за прия́тіє благові́стія Христо́ва. Ти же, в землі́ сей прозрева́я ни́ву Бо́жию, воспіва́л єси́ Спаси́телю: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй любо́в нелицемі́рную, ча́ял єси́ страну́ Япо́нськую би́ти неві́сту укра́шенную, Жениха́ Христа́ на брак ожида́ющую, оба́че сріто́ша тя наро́ди, про́повіді Єва́нгельськия чужда́ющіїся. Ті́мже почита́юще по́двиг апо́стольства твоєго́ в землі́ сей, прославля́єм тя:","Ра́дуйся, сі́ятелю сло́ва Бо́жия нелі́ностний і ще́дрий;","ра́дуйся, всемогу́щею си́лою Креста́ Госпо́дня укрепле́нний.","Ра́дуйся, сто́лпе ві́ри і благоче́стія непоколеби́мий;","ра́дуйся, па́стирю небоя́зненний і чадолюби́вий.","Ра́дуйся, ра́зум іми́й богопросвіще́нний;","ра́дуйся, пропові́дниче неумолка́ющий.","Ра́дуйся, в послуша́нії во́лі Бо́жієй утверди́вийся;","ра́дуйся, помо́щника крі́пка себі́ Бо́га стяжа́вий.","Ра́дуйся, іспові́дников соприча́стниче;","ра́дуйся, ві́рний о нас моли́твенниче.","Ра́дуйся, скорб'я́щих ми́лостивий уті́шителю;","ра́дуйся, по за́повіді Госпо́дні враги́ своя́ люби́вий.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 4","ps":["Бу́рю лю́тую воздвиго́ша на правосла́вних христия́н служи́теліє і́дольстії, зрі́ти не терп'я́щії числа́ ві́рних умножа́ємаго і Це́ркве Христо́ви созида́ющіяся. Ти же, ра́дуяся му́жеству і терпі́нію чад твої́х, в темни́цях заключе́нних, ку́пно с ни́ми возглаша́л єси́ Бо́гові: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще, я́ко уче́ніє Христо́во вся наро́ди об'є́млеть і приє́млеть їх равноче́стно, і я́ко оби́телі ві́рним мно́гі на Небесі́х Госпо́дь угото́ва, притека́ху к тебі́, па́стирю до́брий, му́жіє і жени́, о́троци і ста́рці; ті́мже і ми возглаша́єм ті:","Ра́дуйся, ма́лоє ста́до Христо́во собра́вий;","ра́дуйся, ті́сним путе́м к Бо́гу єго́ приведи́й.","Ра́дуйся, Аки́лі і Приски́ллі подража́ти ві́рния научи́вий;","ра́дуйся, це́ркві дома́шнія утверди́вий.","Ра́дуйся, о́бщія трапе́зи благослови́вий;","ра́дуйся, ча́да в біда́х ніколи́же оставля́вий.","Ра́дуйся, крі́пким во ві́рі немощни́я вруча́вий;","ра́дуйся, ізнемога́ющих оте́чеською дла́нію держа́вий.","Ра́дуйся, му́дро на ни́ві Христо́вой сі́явий;","ра́дуйся, Це́рков на ка́мені тве́рдем стро́ївий.","Ра́дуйся, ра́бе усе́рдний, вруче́ннаго тала́нта не сокри́вий;","ра́дуйся, разсужде́ніє духо́вноє оби́льні яви́вий.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, о́тче, Со́лнцю Пра́вди Христу́ служа́ ре́вностне і ко Го́споду приводя́ ві́рних, я́коже дре́вле звізда́ Вифлеє́мськая. Єгда́ же возведе́н бил єси́ в сан архієре́йський, благода́ть сугу́бую Це́рков Бо́жию устроя́ти і ду́ші челові́чеськія просвіща́ти прия́л єси́. Світоно́сною же моли́твою твоє́ю і ми осіня́ємії, вопіє́м Христу́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя ка́пища і́дольськая, со слеза́ми моля́шеся святи́й: \"Гді сози́жду це́рков Тебі́, Го́споди?\" – і бисть усли́шана моли́тва єго́. Чу́дний храм Воскресе́нія Христо́ва во гра́ді То́кіо труди́ мно́гими і по́мощію люде́й ру́ських воздви́жеся. Сего́ ра́ди і ми богоно́сному святи́телю, в єго́же па́м'ять дони́ні храм той Никола́й-до нариця́ється, возно́сим похвали́ такови́я:","Ра́дуйся, я́ко єле́нь на істо́чники водни́я, к Боже́ственній Трапе́зі притека́вий;","ра́дуйся, собо́р Воскре́сенія Христо́ва і други́я хра́ми возведи́й.","Ра́дуйся, Крест над гра́дом сто́льним утверди́вий;","ра́дуйся, звон кампа́нний до небесе́ вознеси́й.","Ра́дуйся, пла́мень гоне́нія на христия́н угаси́вий;","ра́дуйся, почита́ніє премно́гоє в лю́діх япо́нських стяжа́вий.","Ра́дуйся, благи́м оби́чаєм не возбрани́вий;","ра́дуйся, дру́га і бра́та в наро́ді япо́нськом обріти́й.","Ра́дуйся, Бо́гом по́сланний просвіти́телю;","ра́дуйся, ві́рний Госпо́день домоправи́телю.","Ра́дуйся, ни́ні увінча́нний сла́вою Небе́сною;","ра́дуйся, торжеству́яй ди́вно си́лою Кре́стною.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 6","ps":["Пропові́дници свята́го Єва́нгелія ра́дуються в Го́рніх черто́зіх, приє́млюще тя, я́коже собра́та. Ми же, сро́дниці твої́, в прославле́нії твоє́м ми́лость Бо́жию к нам грі́шним зря́ще ве́лію, Бо́гу воспіва́єм: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ я́ко звізда́ но́вая, о́тче Нико́лає, от землі́ Смоле́нськия да́же до страни́ Япо́нськия доше́д, і апо́стольськими труди́ ди́вним ру́ським святи́м уподо́бився: Вла́димиру равноапо́стольному, Стефа́ну Перми́ просвіти́телю, Інноке́нтію Ірку́тському і Ге́рману Аля́скинскому, і́же суть Це́ркві на́шей боже́ственноє сія́ніє. Ми же, вели́кия ра́дости іспо́лнені, в ли́ці сем прославля́єм тя, но́ваго Бо́жия уго́дника:","Ра́дуйся, дия́кона благочести́ваго до́брий си́не;","ра́дуйся, нищету́ смире́нно претерпі́вий.","Ра́дуйся, обі́т нестяжа́нія Бо́гу принеси́й;","ра́дуйся, обіща́нія і́ночеськая да́же до сме́рти соблюди́й.","Ра́дуйся, архіпа́стирю, в ри́зи ве́тхия облече́нний;","ра́дуйся, во убо́гих ке́ліях пожи́вий.","Ра́дуйся, в ми́рі живи́й, оба́че мирська́я презрі́вий;","ра́дуйся, до преді́лов зіло́ да́льних доше́дий.","Ра́дуйся, му́дрий наста́вниче новопросвіще́нних;","ра́дуйся, попечи́телю о рибака́х а́йнських.","Ра́дуйся, сподви́жников себе́ во учи́лищіх возрасти́вий;","ра́дуйся, вертогра́д в землі́ Япо́нськой насади́вий.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 7","ps":["Хотя́й Це́ркві Япо́нськой па́стирей до́брих і миря́н ві́рних возрасти́ти, о́тче Нико́лає, устроя́л єси́ шко́ли і учи́лища духо́вная, і собра́л єси́ наста́вников прему́дрих, і пі́ніє церко́вноє до́брі учини́л єси́, во є́же па́стві мно́гой ви́ну с тобо́ю пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє яви́ся торжество́ во гра́ді То́кіо, єгда́ соверша́ше святи́тель пра́зднованіє Воскресе́нія Христо́ва в хра́мі собо́рнім, тогда́ ви́діша лю́діє япо́нстії Па́сху Бо́жию спаси́тельную. Ми же, доброді́телем твої́м, о́тче Нико́лає, див'я́щеся, вопіє́м велегла́сно:","Ра́дуйся, устрої́телю церко́внаго пи́ра честні́йший;","ра́дуйся, во ві́ці жесто́цім любо́в Христо́ву сохра́ньшій.","Ра́дуйся, на всяк день і час спасе́нія ра́ди бли́жніх подвиза́вийся;","ра́дуйся, нелі́ностні ві́рния посіща́вий і наставля́вий.","Ра́дуйся, в преложе́нії свяще́нних книг да́же до кончи́ни труди́вийся;","ра́дуйся, благода́ть Бо́жию в ді́ланії непреста́ннім стяжа́вий.","Ра́дуйся, про́повідію зерно́ горчи́чноє насади́вий;","ра́дуйся, дре́во прекра́сноє ві́ри возрасти́вий.","Ра́дуйся, плоди́ трудо́в свої́х при ісхо́ді узрі́вий;","ра́дуйся, дре́во сіє́ многопло́дноє нам завеща́вий.","Ра́дуйся, і по кончи́ні неве́дущия к Бо́гу приводя́й;","ра́дуйся, пребива́яй ни́ні со всі́ми святи́ми в раї́ Ісу́сові.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 8","ps":["Стра́нная і чу́дная ви́діша лю́діє, єгда́ христия́не япо́нстії во́їном ру́ським пліне́нним бра́тськи служа́ху і вся́коє милосе́рдіє тім явля́ху. Ми же, плодо́м любве́ Христо́ви в новопросвіще́нних ча́діх Це́ркве Япо́нськия див'я́щеся, Го́споду піснь воспої́м: Аллилу́я."]},{"h":"Ікос 8","ps":["Всего́ себе́ преда́л єси́ на служе́ніє Бо́гу, равноапо́стольне Нико́лає, і лю́дем та́кожде о Го́споді служа́ непреста́нно, обоя́ запові́данная прему́дре іспо́лнил єси́. Ті́мже тебе́, ца́рським путе́м доброді́телей проше́дшему, умиле́нно воспіва́єм:","Ра́дуйся, Бо́жий усе́рдний служи́телю;","ра́дуйся, пліне́нних ру́ських во́їнов попечи́телю.","Ра́дуйся, Безкро́вную Же́ртву за лю́ди твоя́ приноси́вий;","ра́дуйся, ду́ші смуще́нния умири́вий.","Ра́дуйся, па́ству твою́ в тя́жкия дні бра́ні не оста́вивий;","ра́дуйся, ду́шу свою́ за па́ству полага́вий.","Ра́дуйся, ми́лості і му́жества наста́вниче;","ра́дуйся, отве́рженних ти́хоє приста́нище.","Ра́дуйся, сокро́вище смире́нія;","ра́дуйся, о́бразе покая́нія.","Ра́дуйся, ві́ро непости́дная;","ра́дуйся, любо́в непобіди́мая.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 9","ps":["Вся́коє дре́во по плода́м познає́ться, плод же трудо́в твої́х ве́ліїх єсть спасе́ніє люде́й премно́гих. Яви́ша бо ся мно́гія ти́сящи правосла́вних христия́н та́мо, іді́же пре́жде не бі ні єди́наго. Сего́ ра́ди возопії́м наста́вльшему тя на пропові́даніє твоє́ Го́споду: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії подвиго́м твої́м ізумля́ються, А́нгели с тобо́ю ликовству́ють, ми же, разумі́юще смире́нноє і подви́жничеськоє житіє́ твоє́, духо́вную брань проти́ву ми́ра, пло́ті і дия́вола непреста́нную, і терпі́ніє премно́гоє, хва́лим тя си́це:","Ра́дуйся, не дре́вле, но в послі́дняя времена́ подвиза́вийся;","ра́дуйся, лю́тую брань уни́нія побіди́вий.","Ра́дуйся, Христа́ безстра́шноє іспові́даніє;","ра́дуйся, безбо́жия, язи́чества і єресе́й посрамле́ніє.","Ра́дуйся, о́бразе архипа́стиря правосла́внаго;","ра́дуйся, істо́чниче ві́дінія духо́внаго.","Ра́дуйся, нераде́нія на́шего обличе́ніє;","ра́дуйся, во бранеіх духо́вних укріпле́ніє.","Ра́дуйся, моле́нія оте́чеськи приє́мляй;","ра́дуйся, проше́нія на́ша ісполня́яй.","Ра́дуйся, безсме́ртния ра́дости іспо́лненний;","ра́дуйся, воздая́нієм мно́гим обогаще́нний.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 10","ps":["Спасти́ всеусе́рдно тща́лся єси́ лю́ди отча́янния, І́стиннаго Бо́га не ве́дущия. І вся́кому вопроша́ющему, прему́дрому і некни́жному, я́сний отві́т о твоє́м упова́нії возвіща́л єси́. Ни́ні же, в сі́ні сме́ртній світ узре́вшая, ча́да твоя́ со все́ю Це́рковію вопію́ть: Аллилу́я."]},{"h":"Ікос 10","ps":["\"Стіна́ неруши́ма бу́ди ча́дом Це́ркве но́вия, о Пресвята́я Ді́во Богоро́дице!\" – те́плі моля́шеся святи́тель. Пребива́ше бо Це́рков Япо́нськая посреді́ інові́рія. Ми же, зря́ще ни́ні крі́пость і ві́рность христия́н япо́нських, поє́м богому́дрому па́стирю си́це:","Ра́дуйся, па́стви твоєя́ моли́твенний покро́ве;","ра́дуйся, Го́споду і Ма́тері Єго́ сію́ вруча́яй.","Ра́дуйся, отроко́в і отрокови́ць моли́тися научи́вий;","ра́дуйся, висоту́ цілому́дрія ю́ним із'ясни́вий.","Ра́дуйся, бра́ки честни́я соверша́вий;","ра́дуйся, градо́м і ве́сем мир приноси́вий.","Ра́дуйся, ста́рцю отцю́ до кончи́ни помога́вий;","ра́дуйся, во всіх ну́ждах упова́ніє на Бо́га возлага́вий.","Ра́дуйся, хитросплете́нія злові́рних разруши́вий;","ра́дуйся, хлі́бом Сло́ва Бо́жия па́ству твою́ наси́тивий.","Ра́дуйся, ду́шу за лю́ди япо́нськия полага́вий;","ра́дуйся, успе́нієм твої́м ча́да радостопеча́лія іспо́лнивий.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 11","ps":["Пі́ніє надгро́бноє мно́гажди соверша́шеся, і сле́зи мно́гія пролива́шася, єгда́ почи́ святи́тель Бо́жий, іспо́лнив лі́та до́лга і до дне послі́дняго не оста́вив трудо́в і попече́ній о возлю́бленній па́стві своє́й. Оба́че благода́тію Боже́ственною утеша́ємії, воспева́ша ча́да твоя́, о́тче Нико́лає, Го́сподеві: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тло Це́рков Япо́нськая прия́т благові́стіє на наре́чії своє́м от тебе́, просвіти́телю і́стинний, уподо́бился бо єси́ вселе́нським учи́телем, преложи́в Свяще́нноє Писа́ніє і слу́жбу Боже́ственную на язи́к япо́нський, ізбира́я пи́сьмена і начерта́нія, прему́дрим і прости́м поня́тная. Ті́мже почита́юще доброде́ланіє твоє́, хва́лим тя си́це:","Ра́дуйся, та́йни Свяще́ннаго Писа́нія пости́гнувий;","ра́дуйся, па́стві япо́нськой сія́ із'ясни́вий.","Ра́дуйся, от собо́рнаго ра́зума Церко́внаго ніка́коже отступи́вий;","ра́дуйся, удобоприя́тни твоя́ глаго́ли твори́вий.","Ра́дуйся, в преложе́ніїх рече́нія я́сная ізбира́вий;","ра́дуйся, ло́жная і ле́стная отмета́вий.","Ра́дуйся, слу́жбу свяще́нную на язи́ці Япо́нськом но́вій Це́ркві дарова́вий;","ра́дуйся, наро́д япо́нський я́ко бра́тій до конця́ возлюби́вий.","Ра́дуйся, смири́вий го́рдость мудрецо́в лжеїме́нних;","ра́дуйся, возлюби́вий кро́тких і смире́нних.","Ра́дуйся, па́ству духо́вним ме́дом і млеко́м пита́вий;","ра́дуйся, бла́женне от трудо́в твої́х премно́гих почи́вий.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственная яви́ся я́сно в дія́ніїх твої́х, апо́стольським ра́вних, свяще́нне Нико́лає, в любві́ твоє́й, самоотверже́нії духо́вних чад твої́х ра́ди і в попече́ніїх о стра́ждущих. Найпа́че же Це́рков Япо́нськая дони́ні свя́тость твою́ возвіща́єть, с не́юже ку́пно і ми воспіва́єм Го́споду: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ра́достно в ли́ці ру́ських святи́х твоє́ прославле́ніє і равноапо́стольним іменова́ніє, сро́дниче наш і па́стирю, со все́ю Це́рковію Правосла́вною взива́єм ті си́це:","Ра́дуйся, Святи́я Це́ркве украше́ніє;","ра́дуйся, всіх притека́ющих к тебі́ утіше́ніє.","Ра́дуйся, пра́вих сужде́ній свято́є зерца́ло;","ра́дуйся, страда́ній ди́вноє врачева́ніє.","Ра́дуйся, подвиза́ющихся сподви́жниче;","ра́дуйся, нестроє́нія вся́кая ісправля́яй.","Ра́дуйся, чад твої́х в ра́йських оби́теліх обріта́яй;","ра́дуйся, помина́ющих тя помина́яй.","Ра́дуйся, сві́том невече́рнім вся озаря́яй;","ра́дуйся, звіздо́, от За́пада до Восто́ка просія́вшая.","Ра́дуйся, любве́ Бо́жия пропові́дниче;","ра́дуйся, во вся́ких напа́стіх моля́щимся тебі́ ско́рий помо́щниче.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 13","ps":["О пресла́вний просвіти́телю страни́ Япо́нськия, при́сний моли́твенниче наш пред Го́сподем, равноапо́стольне Нико́лає! Прийми́ ни́нішнєє на́ше приноше́ніє і умоли́ Спаси́теля Бо́га, да утверди́ть во ві́рі і благоче́стії лю́ди правосла́вния, і ізба́вить нас от вся́ких напа́стей, бід і скорбе́й, враго́во ви́димих і неви́димих, і пода́сть гріхо́в оставле́ніє, і ві́чних мук ізбавле́ніє, і Ца́рствія Небе́снаго сподо́бит, да ку́пно с тобо́ю і всі́ми святи́ми Тро́йці Святі́й во ві́ки віко́в поє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел, я́коже Тові́ї іногда́, спутеше́ствова тебі́, о́тче Нико́лає, єгда́ в млада́я лі́та твоя́ напра́вил єси́ стопи́ в страну́, дале́че отстоя́щую, да просвіти́ши лю́ди, во тьмі неві́дінія сідя́щия, сві́том Єва́нгелія Христо́ва. Сего́ ра́ди вопіє́м ті си́це:","Ра́дуйся, Смоле́нськия землі́ сла́вноє рожде́ніє;","ра́дуйся, от младе́нства храм Бо́жий возлюби́вий.","Ра́дуйся, в сиротствеі Богома́терію Одиги́трією не оста́вленний;","ра́дуйся, духо́вними уче́ньми умудре́нний.","Ра́дуйся, на бді́нії всено́щнем призва́ніє на труд апо́стольський приє́мий;","ра́дуйся, сла́дость ми́ра ні во что́же вміни́вий.","Ра́дуйся, чи́на а́нгельськаго і са́на свяще́ннаго удосто́єнний;","ра́дуйся, к неве́дящим спасе́нія ми́лости іспо́лненний.","Ра́дуйся, пропові́дати Єва́нгеліє вожделі́вий;","ра́дуйся, і да́льних я́ко бли́жніх возлюби́вий.","Ра́дуйся, гоне́нія за ві́ру не страши́вийся;","ра́дуйся, ко́зней вра́жиїх не убоя́вийся.","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Кондак 1","ps":["Ізбра́нний от родо́в ру́ських на благові́стіє Христо́во в страні́ Япо́нськой, ду́шу твою́ полага́л єси́ за о́вці твоя́, утвержда́я їх во ві́рі і́стинній. Ті́мже по́двиги твоя́ почита́юще, хва́лим тя:","Ра́дуйся, святи́й равноапостольний Нико́лає, землі́ Япо́нськия просвіти́телю."]},{"h":"Молитва","ps":["Свя́тче Бо́жий, па́стирю до́брий, ді́лателю ві́рний виногра́да Христо́ва, равноапо́стольне Нико́лає! При́зри на град сей і на лю́ди сія́, моли́ Христа́ Бо́га, да сохрани́ть па́ству твою́ от волко́в губ'я́щих ю, да низпо́слеть нам Ду́ха Своєго́ Свята́го дар, во є́же умудри́ти нас ходи́ти пред Ним во вся́ком благоче́стії і чистоті́ во вся дні жи́зні на́шея: да славосло́в'яще і́м'я Єго́ всесвято́є во дні і но́щі, сподо́бимся би́ти наслі́дници жи́зні ві́чния, і просла́вим Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Апо́столов єдинонра́вне і сопресто́льне, / служи́телю Христо́во ві́рний і Богому́дрий, / цівни́це ізбра́нная Боже́ственнаго Ду́ха, / сосу́де преізлива́ющийся любве́ Христо́ви, / Япо́нськия землі́ просвіти́телю, / святи́й Нико́лає, ієра́рше равноапо́стольне, / моли́ся Живонача́льній Тро́йце / о всем твоє́м ста́ді // і о всем ми́рі."]},{"h":"Кондак, глас 4","ps":["Стра́нника і прише́льця прия́т тя страна́ Япо́нськая, / равноапо́стольне святи́телю Нико́лає, / в ней же іспе́рва позна́л єси́ себе́ я́ко чу́ждаго, / оба́че теплоту́ і світ Христо́в істоча́я, / прелага́л єси́ враги́ твоя́ в си́ни духо́вния, / і́мже раздая́ благода́ть Бо́жию, созида́л єси́ Це́рков Христо́ву, / о ней же ни́ні моли́ся, / і тебі́ бо си́нове єя́ і дще́рі взива́ють: // ра́дуйся, па́стирю до́брий наш."]},{"h":"Величання","ps":["Велича́єм тя, равноапо́стольне Нико́лає, і чтим болі́зні і труди́ твоя́, ї́миже труди́лся єси́ во благові́сти Христо́ві."]}],"notes":[]},{"u":"Акафіст благовірним князям Василію і Костянтину Ярославським","e":"Akathist to the Right-Believing Princes Basil and Constantine of Yaroslavl","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і уго́дниці Бо́жії, свята́я кня́жеськая дво́їце, Васи́ліє прехва́льне і Константи́не преди́вне, ви, я́ко два столпа́ непоколеби́ма, зе́млю Яросла́вськую утвержда́єте і по́мощ всеси́льную христия́ном да́руєте; ті́мже, па́м'ять ва́шу сві́тло пра́зднующе, піснь хвали́ поси́льную прино́сим вам і уми́льно вопіє́м:","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Ікос 1","ps":["А́нгелом Небе́сним удивле́ніє би́сте, святі́ї сла́внії кня́зіє, Васи́ліє і Константи́не, єгда́ возжела́ли єсте́ Христу́ со усе́рдієм послужи́ти і за́повіді Єго́ всеці́ло іспо́лнити. Ті́мже равноа́нгельно на землі́ пожи́ли єсте́, ни́ні же вку́пі со безпло́тними піснь хвали́ Царю́ царе́й воспіва́єте і моли́тви те́плия за ни Бо́гу возно́сіте; ми же, недосто́йная ча́да ва́ша, благода́рная вам возглаша́єм, пою́ще ра́достно похвалу́ сицеву́ю:","Ра́дуйтеся, А́нгелом Небе́сним подо́бници;","ра́дуйтеся, ві́ри правосла́вния побо́рници.","Ра́дуйтеся, адама́нти пресві́тлії і столпи́ Це́ркве непоколеби́мії;","ра́дуйтеся, кня́зіє пречу́днії, Оте́честву стіно́ необори́мая.","Ра́дуйтеся, догма́тов церко́вних тве́рдії храни́теліє;","ра́дуйтеся, о наро́ді Бо́жії те́плії попечи́теліє.","Ра́дуйтеся, лучи́ духо́вния Со́лнця Жива́го;","ра́дуйтеся, хра́мини украше́нния Ду́ха Свята́го.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 2","ps":["Ви́дяще, я́ко сокро́вище многоці́нноє, святи́я мо́щі ва́ша, чудеса́ і ісціле́нія оби́льно подаю́щия, лю́діє с ві́рою к ним припа́дають і уми́льно я лобиза́ють, восхваля́юще вас, ди́внії уго́дниці Бо́жії Васи́ліє і Константи́не, а́лчущих пита́теліє, си́рих засту́пниці, немощни́х врачи́, Бо́гу же, дарова́вшу вам крі́пость і си́лу, всім се́рдцем воспіва́ють: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум Боже́ственний озари́ сердця́ ва́ша, святі́ї благові́рнії кня́зіє Васи́ліє і Константи́не, єгда́, ві́ру правосла́вную в наро́ді своє́м утвержда́юще, пред ха́ном пред неві́рними сію́ безбоя́зненно возвести́ли єсте́, сего́ ра́ди і са́мі от Христа́ просла́влени би́сте і вінце́м побі́дним от руки́ Госпо́дні вінча́стеся; ті́мже мо́лим ви, святу́ю дво́їцю князе́й прехва́льних: огради́те ва́шими моли́твами град Яросла́вль і все Оте́чество на́ше і от вся́каго наві́та враг ви́димих і неви́димих ізба́віте ни, ублажа́ющия вас похвали́ сицеви́ми:","Ра́дуйтеся, би́сері многоці́ннії, святи́я мо́щі своя́ лю́дем дарова́вшії;","ра́дуйтеся, кла́дязі неісчерпа́ємії, всеси́льную по́мощ христия́ном подаю́щії.","Ра́дуйтеся, ма́слини плодоно́сния, ісціле́нія оби́льно істоча́ющия;","ра́дуйтеся, ро́ждіє виногра́да Христо́ва, оби́льний плод благода́ті творя́щия.","Ра́дуйтеся, пода́телі боже́ственних утіше́ній;","ра́дуйтеся, світи́льници благода́тних озаре́ній.","Ра́дуйтеся, кри́ни ра́йських насажде́ній;","ра́дуйтеся, сосу́ди духо́вних дарова́ній.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго с тобо́ю бі, пресві́тлий кня́же Васи́ліє, єгда́ твори́л єси́ пра́вду Бо́жию, зе́млю Яросла́вськую от наше́ствія іноплеме́нних охраня́я, Це́рков Ру́ськую в правові́рії утвержда́я і наро́д христия́нський во благоче́стії сохраня́я; ті́мже по́двизі житія́ твоєго́ доброді́тельнаго воспомина́юще, Бо́га прославля́єм, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще ви те́плия моли́твенники за зе́млю на́шу, во́їни Христо́ви непобіди́мії, оба́че на неви́димия враги́ воі́теліє преси́льнії, мо́лим ви, святі́ї Васи́ліє і Константи́не, жи́теліє пресла́внії Оте́чества Небе́снаго: воздіжі́те ва́ші благоуго́днеї ру́ці і воздохні́те у Престо́ла Бо́жия за ни, пою́щия вам такова́я:","Ра́дуйтеся, Сло́ва Бо́жия кре́пції ісполни́теліє;","ра́дуйтеся, во́лі Єго́ неле́ностнії возвісти́теліє.","Ра́дуйтеся, благочести́вому житію́ усе́рднії учи́теліє;","ра́дуйтеся, апо́стольським дія́нієм ре́вностнії подража́теліє.","Ра́дуйтеся, Христу́ Бо́гу ві́рнії служи́теліє;","ра́дуйтеся, чино́в небе́сних сликовствова́теліє.","Ра́дуйтеся, бісо́в плач і зі́льноє рида́ніє;","ра́дуйтеся, христия́н непрестаю́щеє ра́дованіє.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 4","ps":["Бу́рю іскуше́ній претерпі́л єси́, досточу́дне Константи́не, єгда́ воста́ на зе́млю ру́ськую неві́рних власти́тель. Ти же, я́ко щит необори́мий, со дружи́ною на Ту́говой го́ре воздви́глся єси́ і кров свою́ за Оте́чество ізлія́л єси́; ті́мже по́двиг твой воспомина́єм і Бо́гу, укрі́пльшему тя, ра́достно поє́м: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша єва́нгельськоє сло́во: \"Не убо́йтеся от убива́ющих ті́ло\", ти, кня́же Константи́не, все упова́ніє на Бо́га возложи́л єси́, враго́м Оте́чества твоєго́ до́блественне противоста́л єси́ і жизнь свою́ за дру́ги твоя́ положи́л єси́, ті́мже со святи́ми сро́дники свої́ми в небе́сних черто́зіх всели́лся єси́ і та́мо вку́пі с Васи́лієм блаже́нства ра́йськая вкуша́єши і мо́лишися о нас, пою́щих вам такова́я:","Ра́дуйтеся, бу́рю зло́бних іскуше́ній побіди́вшії;","ра́дуйтеся, ві́ру Христо́ву му́жественно пропові́давшії.","Ра́дуйтеся, до́блії во́їни і Оте́чества засту́пниці;","ра́дуйтеся, те́плії моли́твенниці за род христия́нський.","Ра́дуйтеся, а́гнці незло́бивії, Христу́ послі́довавшії;","ра́дуйтеся, же́ртви живи́я, чи́стия і благоуха́нния.","Ра́дуйтеся, нищету́ духо́вную стяжа́вшії;","ра́дуйтеся, бога́тство в Бо́зі ві́рою обрі́тшії.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 5","ps":["Боготе́чния зві́зди яви́стеся, святі́ї кня́зіє Васи́ліє і Константи́не, ви бо сві́том Христо́вим с небесе́ зе́млю озаря́єте, малові́рная сердця́ на́ша во ві́рі утвержда́єте, заблу́ждшия і отпа́дшия от Це́ркве Ма́тере в ло́но єя́ возвраща́єте, моля́щихся вам от поро́ков і вся́ких скверн отвраща́єте, науча́юще благода́рно Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дяще си́лу чудотворе́ній от святи́х моще́й ва́ших подава́ємую і неду́ги разли́чния врачу́ющую, лю́діє Бо́гу благодаре́ніє ве́ліє прино́сять, і вам, святі́ї уго́дниці Васи́ліє і Константи́не, я́ко сокро́вищницям благода́ті Бо́жия, те́плі вопію́ть:","Ра́дуйтеся, сосу́ди златі́ї Ду́ха Свята́го;","ра́дуйтеся, жили́ща пресла́вная Бо́га Жива́го.","Ра́дуйтеся, заблу́ждших в ло́но Це́ркве возвраща́ющії;","ра́дуйтеся, потемне́нних в страстеіх просвіща́ющії.","Ра́дуйтеся, от стра́сті пія́нства ізбавля́ющії;","ра́дуйтеся, неду́жних безме́здно врачу́ющії.","Ра́дуйтеся, в по́двизіх живу́щим помога́ющії;","ра́дуйтеся, от лжеві́рія христия́ни сохраня́ющії.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 6","ps":["Пропові́дници сла́ви Цари́ці Небе́сния би́сте, святі́ї богоно́снії отці́ на́ші, Васи́ліє і Константи́не, єгда́ во Успе́нський храм Богоро́диці Яросла́вськую Єя́ іко́ну принесо́сте, науча́юще лю́ди прославля́ти Пречи́стую Богома́тер, Си́ну же Єя́ і Бо́гу на́шему Го́споду Ісу́су Христу́ благода́рно воспіва́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ в землі́ Яросла́вськой, освеща́яй всю вселе́нную, єгда́ іко́на Богоро́диці, во храм ва́ми принесе́нная, озари́ благода́тію ду́ші христия́нськия, ті́мже с ві́рою к ней лю́діє притека́ють і уми́льно ю лобиза́ють, получа́юще от неду́гов душе́вних і тіле́сних ісціле́нія, вас же, благослови́вших зе́млю на́шу, святі́ї Васи́ліє і Константи́не, похваля́ють си́це:","Ра́дуйтеся, дво́їце свята́я, кня́зіє незабве́ннії;","ра́дуйтеся, дарова́вшії лю́дем іко́ну Богоро́диці в благослове́ніє.","Ра́дуйтеся, сла́ву Цари́ці Небе́сния нам возвеща́ющії;","ра́дуйтеся, іко́ною чудотво́рною зе́млю Ру́ськую благословля́ющії.","Ра́дуйтеся, в хра́мі Успе́нстем Яросла́вськую іко́ну водвори́вшії;","ра́дуйтеся, ве́лію честь Ма́тері Бо́жієй чрез іко́ну Єя́ возда́вшії.","Ра́дуйтеся, лик Єя́ пресві́тлий ни́ні зря́щії;","ра́дуйтеся, при́сно Ю за ни умоля́ющії.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 7","ps":["Хотя́ще Бо́гу уго́дная сотвори́ти і ми́лость Єго́ в пакибитії́ улучи́ти, с ві́рою взира́єм на житіє́ святи́х благові́рних князе́й, Васи́лія пресла́внаго і Константи́на прехва́льнаго, ті́ї бо, власть от Бо́га іму́ще, наро́ду своєму́ ві́рно послужи́ша і оте́чество земно́є по́двиги житія́ своєго́ просла́виша, ті́мже, я́ко дру́зі Христо́ви, во Оте́честві Небе́снім ра́достно пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Світи́льници во гра́ді Яросла́вле возсія́сте і ни́ні Світ Небе́сний на зе́млю на́шу ще́дро ізлива́єте, святі́ї світоно́снії Васи́ліє і Константи́не, Це́ркве Правосла́вния ві́рная ча́да і землі́ на́шея преди́вноє украше́ніє єсте́, ті́мже с ві́рою на ли́ки ва́ша взира́єм і похва́льная вам воспіва́єм:","Ра́дуйтеся, смире́нія і чистоти́ іспо́лненнії;","ра́дуйтеся, о́браз доброді́тельнаго житія́ явля́ющії.","Ра́дуйтеся, кня́зя горди́ні низложи́вшії;","ра́дуйтеся, ко́зні єго́ смиренному́дрієм до конця́ разори́вшії.","Ра́дуйтеся, світи́льници, єва́нгельськи ничи́мже сокри́тії;","ра́дуйтеся, на висоті́ житія́ благоче́стнаго во Оте́честві своє́м возсія́вшії.","Ра́дуйтеся, в терпі́нії ду́ші своя́ стяжа́вшії;","ра́дуйтеся, спасе́ніє і сла́ву от Го́спода восприє́мшії.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 8","ps":["Стра́нници земні́ї, Васи́ліє і Константи́не блаже́ннії, зна́тность ро́да своєго́ презрі́вше, ко го́рдому язи́чеському власти́телю на покло́н ра́ди наро́да і бла́га Оте́чества своєго́ ходи́ли єсте́, і жестокосе́рднаго прави́теля ми́лостива сотвори́ли єсте́, ті́мже му́дрость ва́шу похваля́єм і па́м'ять ва́шу сві́тло пра́зднуєм, Бо́гу же, Влади́ці всіх, поє́м ра́достно: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь град удиви́ся, чу́до ве́ліє созерца́я, ка́ко два сокро́вища, в землі́ сокри́тая, подо́бно двіма́ со́лнцема, возсія́ста, єгда́ лю́діє обріто́ша святи́я мо́щі ва́ша, чу́дная дво́їце, Васи́ліє і Константи́не пресві́тлії; ті́мже мо́лим ви, Бо́жії рабо́тници і дру́зі Христо́ві, дарова́ти гра́ду утвержде́ніє, всім ві́рою вас почита́ющим гріхо́в оставле́ніє і Ца́рствію Бо́жию присвоє́ніє, да воспіва́єм вам похва́льную піснь сицеву́ю:","Ра́дуйтеся, стра́нници земні́ї і челові́ци Небе́снії;","ра́дуйтеся, ско́рії засту́пници на́ші і учи́теліє серде́чнії.","Ра́дуйтеся, я́ко мо́щі ва́ша жизнь ві́чную лю́дем возвіща́ють;","ра́дуйтеся, я́ко ти́я скорб душе́вную на ра́дость прелага́ють.","Ра́дуйтеся, кри́ни се́льнії, чисто́тою на землі́ процві́тшії;","ра́дуйтеся, цві́ти прекра́снії, святи́нею житія́ своєго́ возблагоуха́вшії.","Ра́дуйтеся, істо́чници духо́внії, в жизнь ві́чную при́сно теку́щії;","ра́дуйтеся, ско́рії моли́твенниці, благода́тную по́мощ ві́рним подаю́щії.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 9","ps":["Восхва́ляться преподо́бнії во сла́ві і возра́дуються на ло́жах свої́х, — та́ко возвісти́ боже́ственний Дави́д ро́ду челові́чеському, сего́ ра́ди на до́броє житіє́ ва́ше взира́юще, я́ко преподо́бних вас ублажа́єм, святі́ї сла́внії Васи́ліє і Константи́не, ви бо во весе́лії ві́чнім пребива́юще, науча́єте нас с любо́вію пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́ї многоглаго́ливії умолко́ша, не возмога́ють бо рещи́ сла́ву, дарова́нную вам от Го́спода, ю́же о́ко челові́чеськоє не ви́ді, у́хо челові́чеськоє не сли́ша і я́же на се́рдці челові́ку не взи́де; ті́мже ви, я́ко фи́никси многопло́днії, во дво́ріх Госпо́дніх процвіли́ єсте́; сего́ ра́ди мо́лим ви, святу́ю дво́їцю, Васи́ліє і Константи́не, помина́йте ни, земни́я сро́дники ва́ша, пою́щия вам похвалу́ сицеву́ю:","Ра́дуйтеся, му́жіє сла́внії, ве́лій плод доброді́телей Бо́гу прине́сшії;","ра́дуйтеся, мзду Небе́сную мно́гую от Го́спода восприє́мшії.","Ра́дуйтеся, кади́льници злати́я, фимія́м моли́тв Бо́гу за ни вознося́щия;","ра́дуйтеся, зві́зди небе́сния, во мра́ці неві́рія ві́рно світя́щия.","Ра́дуйтеся, ковче́жці златокова́ннії, сокро́вище Ду́ха Свята́го в себі́ іму́щії;","ра́дуйтеся, гу́сли сладкозву́чния, піснь хвали́ Бо́гу ви́ну пою́щия.","Ра́дуйтеся, мечі́ обоюдоо́стрії, враги́ ми́сленния посеця́ющії;","ра́дуйтеся, в по́двизіх духо́вних христия́ном помога́ющії.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ще ду́ші своя́, не да́ли єсте́ сна очи́ма свої́ма, ні ві́ждома свої́ма дрема́нія, до́ндеже вообрази́ся во вас Христо́с, святі́ї богому́дрії Васи́ліє і Константи́не; ті́мже, ду́ші ва́ша, я́ко неві́сти Христо́ви, укра́сили єсте́, і со світи́льники горя́щими Жениха́ Церко́внаго сре́тили єсте́, с Ни́мже ни́ні ликовству́юще, поє́те Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єсте́ і заступле́ніє гра́ду Яросла́влю, богому́дрії уго́дниці Васи́ліє і Константи́не, і прибі́жище всім, с ві́рою призива́ющим вас на по́мощ во вся́ких біда́х і напа́стіх, дерзнове́ніє бо ве́ліє і́мате у Христа́ Бо́га, святі́ї, помога́ти і спаса́ти вопію́щих вам такова́я:","Ра́дуйтеся, страні́ на́шей сві́тлоє украше́ніє;","ра́дуйтеся, гра́ду Яросла́влю весе́ліє і ра́дованіє.","Ра́дуйтеся, престо́лу Го́спода сла́ви предстоя́щії і те́плі моля́щіїся о душа́х на́ших;","ра́дуйтеся, заре́ю Трисо́лнечнаго Сві́та озаре́ннії.","Ра́дуйтеся, я́ко лице́м к лицю́ Бо́га зрі́те;","ра́дуйтеся, вку́пі в ра́дость Го́спода вше́дшії.","Ра́дуйтеся, я́ко су́щим в біда́х і напа́стіх ізбавле́ніє подає́те;","ра́дуйтеся, я́ко і всім тружда́ющимся ско́рії помо́щници єсте́.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 11","ps":["Піснь хвали́ і благодаре́нія прино́сим Бо́гу, ди́вному во святи́х Свої́х, я́ко дарова́ нам такови́я крі́пкия моли́твенники і во бранеіх духо́вних помо́щники; ті́мже вас, святі́ї бра́тіє, ублажа́єм і мо́лим о спасе́нії душ на́ших, да вку́пі с ва́ми, блаже́ннії кня́зіє Васи́ліє і Константи́не, воспоє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Свіщи́ многосві́тлия, на тве́рди церко́вній возжже́нния, благоімени́тії Васи́ліє і Константи́не, у Престо́ла Пресвяти́я Тро́йці ви́ну предстоя́ще, іспросі́те нам неот'є́млему благода́ть Свята́го Ду́ха, да Їм уті́шеннії і просветле́ннії, воспоє́м вам похвалу́ сицеву́ю:","Ра́дуйтеся, те́плії за ни к Бо́гу моли́твенниці;","ра́дуйтеся, от гні́ва Бо́жия на́ші засту́пниці.","Ра́дуйтеся, о́блаці, росо́ю благода́ті іспо́лненнії;","ра́дуйтеся, істо́чници, напая́ющії жа́ждущия жи́зні.","Ра́дуйтеся, кня́зіє святі́ї, любо́в к Бо́гу іму́щії;","ра́дуйтеся, о благоче́стії зіло́ ревну́ющії.","Ра́дуйтеся, вдов уті́шителіє і ни́щих пита́теліє;","ра́дуйтеся, благ небе́сних незави́стнії пода́теліє.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 12","ps":["Благода́ть неізмі́нно істоча́єте всім с ві́рою к вам притека́ющим, благові́рнії кня́зіє на́ші, Васи́ліє і Константи́не, ми же, я́ко єле́ни на істо́чники водни́я, ко святи́м моще́м ва́шим припа́даєм, нікто́же бо от них тощ і неуті́шен оти́де, оба́че ра́дости духо́вния іспо́лнені, в ликова́нії серде́чнім вам благодаре́ніє прино́сим, Бо́гу же воспіва́єм умиле́нно: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще чудеса́ і по́двиги ва́ша, блаже́ннії Васи́ліє і Константи́не, диві́мся благоутро́бію Бо́жию, ка́ко си́ла благода́тная в немощни́х сосу́діх скуде́льних пребива́ющи, вся́кую я́зю і неду́г врачу́єть, ско́рбних утіша́єть і вся благопотре́бная, с ві́рою прося́щим да́руєть. За сію́ ми́лость благодаре́ніє Бо́гу прино́сим, вас же ублажа́єм похвала́ми сицеви́ми:","Ра́дуйтеся, ка́мені многоці́ннії сла́ви Ца́рства Христо́ва;","ра́дуйтеся, скрижа́ли заве́тния сладча́йшаго І́мене Ісу́сова.","Ра́дуйтеся, цівни́ци ізря́дния Ду́ха Свята́го;","ра́дуйтеся, труби́ громогла́сния Бо́га Небе́снаго.","Ра́дуйтеся, сі́не благоли́ственная, от зно́я страсте́й нас покрива́ющая;","ра́дуйтеся, ві́стници, боже́ственную во́лю нам возвеща́ющії.","Ра́дуйтеся, хода́таї за зе́млю Ру́ськую;","ра́дуйтеся, раде́теліє за Це́рков Правосла́вную.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 13","ps":["О пресла́внії уго́дниці, Васи́ліє і Константи́не, в землі́ Яросла́вськой просія́вшії, приймі́те ма́лоє сіє́ моле́ніє на́ше, помозі́те нам, во юдо́лі скорбе́й живу́щим, іспросі́те у Го́спода мир і ве́лію ми́лость земни́м сро́дником ва́шим, да вку́пі с ва́ми і со всі́ми святи́ми сподо́бимся на землі́ живи́х пі́ти Бо́гу хвале́бную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом Небе́сним удивле́ніє би́сте, святі́ї сла́внії кня́зіє, Васи́ліє і Константи́не, єгда́ возжела́ли єсте́ Христу́ со усе́рдієм послужи́ти і за́повіді Єго́ всеці́ло іспо́лнити. Ті́мже равноа́нгельно на землі́ пожи́ли єсте́, ни́ні же вку́пі со безпло́тними піснь хвали́ Царю́ царе́й воспіва́єте і моли́тви те́плия за ни Бо́гу возно́сіте; ми же, недосто́йная ча́да ва́ша, благода́рная вам возглаша́єм, пою́ще ра́достно похвалу́ сицеву́ю:","Ра́дуйтеся, А́нгелом Небе́сним подо́бници;","ра́дуйтеся, ві́ри правосла́вния побо́рници.","Ра́дуйтеся, адама́нти пресві́тлії і столпи́ Це́ркве непоколеби́мії;","ра́дуйтеся, кня́зіє пречу́днії, Оте́честву стіно́ необори́мая.","Ра́дуйтеся, догма́тов церко́вних тве́рдії храни́теліє;","ра́дуйтеся, о наро́ді Бо́жії те́плії попечи́теліє.","Ра́дуйтеся, лучи́ духо́вния Со́лнця Жива́го;","ра́дуйтеся, хра́мини украше́нния Ду́ха Свята́го.","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Кондак 1","ps":["Ізбра́ннії чудотво́рці і уго́дниці Бо́жії, свята́я кня́жеськая дво́їце, Васи́ліє прехва́льне і Константи́не преди́вне, ви, я́ко два столпа́ непоколеби́ма, зе́млю Яросла́вськую утвержда́єте і по́мощ всеси́льную христия́ном да́руєте; ті́мже, па́м'ять ва́шу сві́тло пра́зднующе, піснь хвали́ поси́льную прино́сим вам і уми́льно вопіє́м:","Ра́дуйтеся, Васи́ліє і Константи́не, землі́ Яросла́вськия чудотво́рці прехва́льнії."]},{"h":"Молитва","ps":["О всехва́льнії і достоблаже́ннії кня́зіє Васи́ліє і Константи́не, ви у́бо по́двигом до́брим подвиза́стеся і житіє́ своє́ во ві́рі сконча́ли єсте́, ни́ні же в Ца́рстві сла́ви со святи́ми веселі́теся і ра́йських блаже́нств наслажда́єтеся; ті́мже на сла́ву ва́шу уми́льно взира́єм і вас, я́ко те́плих моли́твенников ублажа́єм. Єй, всечестна́я богоуго́дная дво́їце, воззрі́те на ни ми́лостивно і да́руйте нам вся потре́бная ко спасе́нію. Єще́ же мо́лим вас, іспросі́те у Го́спода Це́ркві мир і утвержде́ніє, архипа́стирем і па́стирем в благода́ті хожде́ніє, мона́хом во смире́нії і терпі́нії пребива́ти і моли́тву непреста́нно твори́ти, і всім нам друг ко дру́гу любо́в нелицемі́рную імі́ти. Єще́ же да́руйте нам мита́рств возду́шних безбі́дноє прохожде́ніє і на Стра́шнім Суді́ Христо́ві одесну́ю Бо́га стоя́ніє, да прославля́єм Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Возви́сившеся на доброді́тель, к жела́нію кра́йнему, / і достиго́сте к Небе́сній висоті́, / благові́рнії вели́ції кня́зі Васи́ліє і Константи́не, / і безстра́стним житіє́м украси́сте ду́ші своя́, / поще́нієм же ізря́дно побіди́сте бісо́вськия полки́ / і восприя́сте чи́стую со́вість, / в моли́твах я́ко безпло́тнії преби́сте, / возсія́сте в ми́рі, а́ки со́лнце, пресла́внії, // молі́те спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Я́ко цві́ти честні́ї разли́чнії, / в ра́йстій пи́щі процві́тше невеще́ственно, / оте́честву своєму́ сла́ву ве́лію / і сро́дником похвалу́ і честь я́вльше, / всеї́стиннії побі́дници, вели́кий Васи́ліє і сла́вний Константи́не, / но у́бо не преста́йте моля́щеся о гра́ді ва́шем і о всіх рабі́х свої́х, / ізба́вити їх от напа́стей, і бід, і вся́ких лю́тих обхожде́ній, вопію́щих вам: // ра́дуйтеся, гра́ду на́шему Яросла́влю вели́коє утвержде́ніє."]},{"h":"Величання","ps":["Велича́єм вас, / страстоте́рпці Христо́ви, благові́рнії кня́зі Васи́ліє і Константи́не, / і чтим честна́я страда́нія ва́ша, / ви бо мо́лите за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст Собору преподобних отців, у Соловецьких обителях просіяних","e":"Akathist to the Synaxis of the Venerable Fathers who shone forth at Solovki","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії воі́тели Христо́ві і благоче́стія подви́жници, преподо́бнії Зоси́мо, Савва́тіє і Ге́рмане со сподви́жники досто́йними, ва́ми бо ди́вно просла́вися і́м'я Госпо́днє во страна́х Біломо́рія, і вся Ру́ськая Це́рков весели́ться о святи́ні ва́шей; покланя́ющеся той, благода́рно вопіє́м вам:","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Ікос 1","ps":["А́нгельським житіє́м жи́тельствовавше, отці́ преблаже́ннії, безпло́тним подража́ти тща́щеся доброді́тельми, чистото́ю тіх ду́ші своя́ убели́ли єсте́, тілеса́ істончи́вше труди́ по́стничеськими, я́ко а́нгели на землі́ пребива́ли єсте́; ми же таково́му житію́ ва́шему див'я́щеся, сію́ похвалу́ прино́сим вам:","Ра́дуйтеся, ми́ра ізбі́гшії і во ото́ки морськи́я прише́дшії;","ра́дуйтеся, прише́ствієм ва́шим мно́гих ко Христу́ приве́дшії.","Ра́дуйтеся, жи́тельство і́ночеськоє в пусти́ні сі́верній созида́вшії;","ра́дуйтеся, по́двиги до́брими і чудеси́ та́мо просія́вшії.","Ра́дуйтеся, рай благоцвіту́щий во страні́ полу́нощній насади́вшії;","ра́дуйтеся, тоя́ язи́ки сві́том і́стини Христо́ви просвіти́вшії.","Ра́дуйтеся, я́ко труди́ мно́гими труди́вшіїся во благоче́стії;","ра́дуйтеся, а́нгели земні́ї і челові́ци Небе́снії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 2","ps":["Ви́дяще лю́діє страни́ Помо́рськия і Коре́льськия, я́ко до́брі жи́тельствуєте во оби́телі ва́шей, по́двиги ди́вния соверша́юще Бо́жиєю благода́тію, приобща́хуся бра́тству ва́шему, і ку́пно с ва́ми воспіва́ху Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом Небе́сним просвіща́ємі, неразу́міє живу́щих во страні́ сі́верній просвіти́ли єсте́ от неві́рія к ві́рі і́стинній обраще́нієм: ті́ї бо ра́достно сле́доваху стезя́ми ва́шими, учи́телей до́брих вас почита́юще. Сотворі́те і нас недосто́йних ученики́ ва́ша би́ти, да весе́лієм глаго́лем вам:","Ра́дуйтеся, Вседержи́теля Бо́га ві́рнії служи́телі;","ра́дуйтеся, свяще́нних ото́ков свяще́ннії жи́телі.","Ра́дуйтеся, мно́гія ско́рби і біди́ і нападе́нія вра́жия претерпі́вшії;","ра́дуйтеся, Го́спода ра́ди вся блага́я ми́ра сего́ презрі́вшії.","Ра́дуйтеся, Крест Христо́в с любо́вію ве́лією под'є́мшії;","ра́дуйтеся, сла́дость ра́йськую єще́ на землі́ вкуси́вшії.","Ра́дуйтеся, плоть свою́ со страстьми́ і похотьми́ распе́ншії;","ра́дуйтеся, благода́ть у Го́спода обрі́тшії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укріпля́ємі, отці́ всечестні́ї, лю́тих страсте́й побіди́телі яви́стеся, боре́ньми крі́пкими, моли́твами сле́зними, труди́ бді́нними си́лу вра́жию низложи́ли єсте́. Тім ізба́вльшеся злих по́мислов і безстра́стієм украси́вшеся, любо́вію воспе́ли єсте́ лю́б'ящему вас Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще сердця́ своя́ горі́, в Небе́сних оби́теліх сокро́вище себі́ собира́ли єсте́, досточу́днії, і, мно́гими да́ри Всеще́драго Бо́га обогати́вшеся, да́нная вам от Него́ во сто крать приумно́жили єсте́. Ті́мже, прославля́юще по́двиги ва́ша, со умиле́нієм взива́єм вам:","Ра́дуйтеся, нището́ю духо́вною Ца́рство Небе́сноє сниска́вшії;","ра́дуйтеся, мудрова́нієм смире́нним мир непоколеби́м в душа́х стяжа́вшії.","Ра́дуйтеся, кро́тостію ду́ха зе́млю кро́тких наслі́довавшії;","ра́дуйтеся, чистото́ю серде́чною А́нгелом приобщи́вшіїся.","Ра́дуйтеся, я́вльшіїся сокро́вище неіждива́ємоє Солове́цькой оби́телі;","ра́дуйтеся, і́ноком єя́ засту́пниці і покрови́телі.","Ра́дуйтеся, мона́хов мно́жества наста́вници;","ра́дуйтеся, Христо́ві ві́рнії ізбра́нници.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 4","ps":["Бу́ря напа́стей не возмо́же возмути́ти тишини́ душ ва́ших, в Бо́зі уста́вленних і моли́твою к Нему́ управля́ємих: от Того́ бо дар чудотворе́ній приє́мше, бу́ри морськи́я і жите́йськія укроща́єте, вспомощству́юще от тіх стра́ждущим. Ті́мже спа́сшіїся от бід заступле́нієм ва́шим велегла́сно воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє о чудесі́х ве́ліїх, содіва́ємих ва́ми, і о по́мощі, неоску́дно подає́мой прибега́ющим к вам в моли́твах, укріпля́хуся ві́рою ко святи́ні ва́шей, і предста́телей до́брих вас пред Бо́гом полага́юще, хвалу́ воздава́ху вам пі́нії сицеви́ми:","Ра́дуйтеся, в мо́рі пла́вающим благоути́шнії упра́вителі;","ра́дуйтеся, от ги́бельнаго потопле́нія ві́рнії ізба́вители.","Ра́дуйтеся, вопію́щих к вам о по́мощі ско́рії усли́шателі;","ра́дуйтеся, печа́льних і обремене́нних тягота́ми жите́йськими уті́шители.","Ра́дуйтеся, спу́тници благонаде́жнії ше́ствующим путе́м приско́рбним і ті́сним;","ра́дуйтеся, хода́таї те́плії о такови́х пред Отце́м Небе́сним.","Ра́дуйтеся, тружда́ющимся труди́ честни́ми помо́щници усе́рднії;","ра́дуйтеся, Боже́ственних повелі́ній ісполни́тели тве́рдії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 5","ps":["Боголюбе́знії тру́женици ни́ви духо́вния яви́лися єсте́, отці́ преблаже́ннії, жела́нієм Боже́ственним побіжда́юще вся мудрова́нія земна́я, попече́нія іна́го не іму́ще, ра́зві о сла́ві Госпо́дней і о спасе́нії душ ва́ших, є́же і достиго́сте любо́вію Бо́жиєю невозбра́нно. Ни́ні во ві́чній сла́ві єго́ пребива́юще, с ли́ки Небе́сними воспіва́єте Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше вразі́ ро́да челові́чеськаго доброді́тельноє житіє́ ва́ше, я́ко по́двиги до́брими в Ца́рство Небе́сноє путь себі́ удо́бні уготовля́єте, мно́гажди тща́хуся восп'яти́ти вам і погуби́ти нападе́нієм лука́вих супоста́тов: ва́шими же моли́твами ті́ї всегда́ посра́млени отхожда́ху, оби́телі і ото́ком сим ніколи́же могу́ще вреди́ти. Тім с благодаре́нієм серде́чним поє́м вам си́це:","Ра́дуйтеся, землі́ Солове́цькой неуси́пнії храни́тели;","ра́дуйтеся, тишини́ і ми́ра єя́ наде́жнії защи́тителі.","Ра́дуйтеся, всіх враго́в єя́ неща́дно прогоня́ющії;","ра́дуйтеся, всіх живу́щих в ней от злих напа́стей огражда́ющії.","Ра́дуйтеся, вся́кия лжі і ле́сти гро́знії обличи́телі;","ра́дуйтеся, пра́вди Бо́жия до́блественнії ревни́тели.","Ра́дуйтеся, і́стини Христо́ви немо́лчнії пропові́дателі;","ра́дуйтеся, дре́внім святи́м досто́йнії послі́дователі.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 6","ps":["Пропові́дуєть Це́рков Правосла́вная свя́тость житія́ і вели́чіє по́двиг преподо́бних оте́ць Солове́цьких, хвалу́ воздаю́щи сему́ досточти́мому собо́ру пі́нієм духо́вним, ди́внаго же во святи́х Свої́х Бо́га ра́достію прославля́єть, пою́щи: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єсть ва́ми, достоблаже́ннії отці́, во страні́ полу́нощній сла́ва Єди́наго І́стиннаго Бо́га, в Тро́йці покланя́ємаго: є́юже просла́вишася морсті́ї ото́ці, Боже́ственним свяще́нієм освяти́шася, благода́ті преізоби́льно іспо́лнишася. Сего́ ра́ди чту́щії святи́ню сію́ притека́ють сі́мо і по достоя́нію пою́ть вам:","Ра́дуйтеся, благода́ть Госпо́дню ото́ком Солове́цьким усво́ївшії;","ра́дуйтеся, в жили́ще прему́дрости Бо́жия сія́ угото́вившії.","Ра́дуйтеся, Го́спода пред очи́ма вну́треннима при́сно імі́вшії;","ра́дуйтеся, на крилі́х доброді́телей в Го́рній Сіо́н возлете́вшії.","Ра́дуйтеся, подвиза́ющимся по́двигом духо́вним вспомоществу́ющії;","ра́дуйтеся, мона́шеськаго ді́ланія о́браз показу́ющії.","Ра́дуйтеся, ди́вная зна́менія і чудеса́ явля́ющії;","ра́дуйтеся, Бо́га в Це́ркві преподо́бних прославля́ющії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 7","ps":["Хотя́ще мирськи́я суєти́ ізбіжа́ти і єди́ному Бо́гу порабо́тати, в пусти́нних ото́ціх водвори́лися єсте́, преподо́бнії, у челові́к у́бо забве́нних, у Бо́га же возлю́бленних, моле́ній фимія́мом облагоуха́вше я і по́двиги трудо́во возді́лавше, Бо́гу непреста́нно піснь пою́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вії чудотво́рці і уго́дниці Бо́жії показа́стеся, преподо́бнії отці́ на́ші: ви́ше єстества́ житіє́ яви́ли єсте́, си́лою Бо́жиєю укріпля́ємі. На́ше уни́лоє житіє́ оживотворі́те чу́дними диха́нії те́плих моли́тв ва́ших, да ве́тхости совле́кшеся, доброді́тельми обнові́мся і умиле́нно воспоє́м вам:","Ра́дуйтеся, я́ко ва́ми Ви́шняго прему́дрость оправди́ся;","ра́дуйтеся, я́ко ва́ми і́стина Госпо́дня утверди́ся.","Ра́дуйтеся, я́ко по́двиги ва́шими ото́ці Солове́цькії просла́вишася;","ра́дуйтеся, я́ко усе́рдієм ва́шим на спасе́нія стезі́ і́нок мно́жества наста́вишася.","Ра́дуйтеся, в за́повідіх Госпо́дніх поуча́ющимся му́дрії учи́тели;","ра́дуйтеся, обраща́ющихся ко Христу́ блазі́ї попечи́тели.","Ра́дуйтеся, жела́ющим спасти́ся неоску́дно по́мощ подаю́щії;","ра́дуйтеся, в го́рнія оби́телі ко Го́споду зову́щії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 8","ps":["Стра́нници би́сте во юдо́лі земно́й, отці́ преблаже́ннії, восходя́ще душе́ю в Небе́сния кро́ви, жела́ніє се́рдця ва́шего во ви́шнем положи́ли єсте́. Ни́ні жела́ніє сіє́ улучи́вше, в дому́ Бо́жії пребива́єте, со всі́ми святи́ми пою́ще Бо́гу ві́чную піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Всіх вас, ізбра́нников Свої́х, от суєти́ мирськи́я приведе́ Госпо́дь к житію́ надми́рному: во о́нім благоче́стно дні своя́ сконча́вше, соверше́нства і́ночеськаго достиго́сте. Ми же о́браз житія́ ва́шего во очесі́х ми́сленних іму́ще і кончи́ну ва́шу че́стну на па́м'ять приводя́ще, возно́сим вам хвале́нія сицева́я:","Ра́дуйтеся, в тя́жестіх трудо́в мона́шеських на Бо́га упова́вшії;","ра́дуйтеся, спасе́ніє Єго́ всім се́рдцем позна́вшії.","Ра́дуйтеся, в та́йних селе́ніїх Госпо́дніх ду́хом обита́вшії;","ра́дуйтеся, вели́чествія Непостижи́маго і сла́ви Єго́ трепета́вшії.","Ра́дуйтеся, ни́ні во оби́теліх Небе́сних пребива́ющії;","ра́дуйтеся, чудоде́йственную по́мощ лю́дем сви́ше простира́ющії.","Ра́дуйтеся, враго́в спасе́нія на́шего устраша́ющії;","ра́дуйтеся, красото́ю по́двиг ва́ших Це́рков украша́ющії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє диви́ться чу́дному житію́ ва́шему, я́ко безпло́тним подо́б'ящеся, в по́стничестві неосла́бнім, в трезве́нії бде́ннем, в моли́твах непреста́нних на землі́ пребива́ли єсте́: тім укріпля́юще вас в безмі́рних труді́х ва́ших, воздвиза́ху вас на похвалу́ Боже́ственную, вку́пі с ва́ми пою́ще: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не мо́гуть по́двиги ва́ша по достоя́нію просла́вити, достоблаже́ннії; недоумі́ють бо, ка́ко во ото́ціх сі́верних, а́ки во страні́ полу́денній жи́тельствовали єсте́ і подо́бници вели́ким отце́м пусти́нним би́ли єсте́. Ми же ве́лію ми́лость Бо́жию ко отре́кшимся себе́ во і́м'я Єго́ ві́дяще, воспіва́єм вам такова́я:","Ра́дуйтеся, благода́тію Свята́го Ду́ха осія́ннії;","ра́дуйтеся, то́ю к подвиго́м преподо́бія призва́ннії.","Ра́дуйтеся, во мра́зі лю́ті то́ю согріва́ємії;","ра́дуйтеся, пи́щею нетлі́нною ще́дро снабдева́ємії.","Ра́дуйтеся, Ду́хом восхища́ємії в Небе́сния оби́телі;","ра́дуйтеся, я́вльшіїся тіх приснора́достнії жи́телі.","Ра́дуйтеся, благода́ті Бо́жия неізрече́ннії таї́нници;","ра́дуйтеся, дерзнове́ннії о нас ко Го́споду моли́твенниці.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ще ду́ші своя́, в ру́ці Іму́щему спасе́ніє всеці́ло преда́ли єсте́ їх, блаже́ннії, і преізлива́ющіяся сосу́ди благода́ті сотвори́сте їх. Боже́ственним восхожде́нієм на висоту́ доброді́телей восходя́ще, Бо́гу хвале́бную піснь воспіва́сте: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая яви́стеся бра́тству Солове́цькому і всім притека́ющим под кров оби́телі ва́шея, досточу́днії уго́дниці Бо́жії, от напа́стей і бід огражда́юще їх благомо́щною своє́ю моли́твою. Сего́ ра́ди на заступле́ніє ва́ше пред Бо́гом і по́мощ упова́юще, взива́єм к вам хвале́нії такови́ми:","Ра́дуйтеся, в не́мощіх нас посеща́ющії;","ра́дуйтеся, от паде́ній гріхо́вних нас ізбавля́ющії.","Ра́дуйтеся, неду́ги душе́вния і тіле́сния врачу́ющії;","ра́дуйтеся, в зако́ні Госпо́дні ходя́щим вспомоществу́ющії.","Ра́дуйтеся, із бе́здни страсте́й челові́ки ізводя́щії;","ра́дуйтеся, милосе́рдіє Госпо́днє на всіх низводя́щії.","Ра́дуйтеся, враги́ Бо́жия і собла́зни ві́ка сего́ расточа́ющії;","ра́дуйтеся, со всі́ми святи́ми дне прише́ствія Госпо́дня ча́ющії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє непреста́нно возно́сим вам, преподо́бнії отці́ на́ші; ва́ми бо обріто́хом сію́ достосла́вную кинові́ю, ва́ми спаси́тельная благода́ть Госпо́дня простре́ся во ото́ціх Солове́цьких і во всей страні́ полу́нощній; сего́ ра́ди па́м'ять ва́ша ми́лостію Бо́жиєю повсю́ду досто́йно почита́єма бива́єть. І ми прославля́ющему вас Бо́гу всера́достно взива́єм: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льници світоза́рнії, над бе́здною мирська́го м'яте́жа горя́щії, яви́стеся преподо́бнії отці́ Солове́цькії, сві́том Христо́вим осіява́юще богоізбра́нния ото́ки. Не пре́зріте во оби́телі ва́шей жи́тельствующих і всіх, ві́рою к вам притека́ющих, милосе́рдіє Бо́жиє к нам приклоні́те, да благода́рним се́рдцем ви́ну воспіва́єм вам:","Ра́дуйтеся, сві́том Боже́ственним нас просвіща́ющії;","ра́дуйтеся, во́ду живу́ю богопозна́нія нам істоча́ющії.","Ра́дуйтеся, в ді́ланії за́повідей Госпо́дніх нас му́дро наказу́ющії;","ра́дуйтеся, в Ца́рствіє Небе́сноє путь ві́рний нам указу́ющії.","Ра́дуйтеся, в ні́дріх ото́ков морськи́х почива́ющії;","ра́дуйтеся, нетлі́нними мощми́ ва́шими страну́ на́шу освяща́ющії.","Ра́дуйтеся, чудеса́ і ісціле́нія во ізоби́лії творя́щії;","ра́дуйтеся, святи́ню Бо́жию в неоскуде́нії храня́щії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 12","ps":["Благода́тію Бо́жиєю вся по́двиги соверши́ли єсте́, прему́дрії, діла́ ди́вная і до́брая показу́юще, наслі́діє неіждива́ємоє нам оста́вили єсте́. Сим богатя́щеся і утвержда́ющеся в доброді́теліх, поє́м да́вшему вам крі́пость і просла́вльшему вас Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще благопло́дноє житіє́ ва́ше, труди́ богоуго́дними, чудеси́ і благода́тними явле́нії іспо́лненноє, благодаре́ніє прино́сим вам, преподо́бнії, моли́твами всеси́льними ва́шими укріпля́ємі, і ко ісполне́нію во́лі Госпо́дні воздвизає́мі, на по́мощ ва́шу упова́юще зове́м вам:","Ра́дуйтеся, доброді́тельми ди́вними і по́двиги сія́ющії;","ра́дуйтеся, в моли́твах ва́ших к Бо́гу нас не оставля́ющії.","Ра́дуйтеся, а́ще і не поймено́ваннії у челові́к, у Го́спода всі ізочте́ннії;","ра́дуйтеся, Ца́рства Бо́жия наслі́дници благослове́ннії.","Ра́дуйтеся, діла́ Госпо́дня по́мощію Єго́ соверша́ющії;","ра́дуйтеся, вели́чіє Боже́ственноє свя́тостію ва́шею явля́ющії.","Ра́дуйтеся, по́мощ тре́бующим всеще́дро подаю́щії;","ра́дуйтеся, но́ву піснь Госпо́дню на землі́ живи́х пою́щії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 13","ps":["О пресла́вноє і преди́вноє мно́жество святи́х землі́ Солове́цькия, я́ко безчи́сленния свіщи́ сія́ющеє в пусти́ні ото́ков сі́верних! Се приклоня́єм глави́ пред святи́нею ва́шею, пред вели́чієм по́двиг і чудоді́йствієм моли́тв. Мо́лим вас усе́рдно: заступи́ті во оби́телі ва́ми просла́вленній жи́тельствующих і всіх христия́н, во ві́ці сем многом'яте́жнім Бо́гу угоди́ти тща́щихся. Іспросі́те у Всеми́лостиваго Влади́ки проще́нія і оставле́нія всіх на́ших прегріше́ній і душа́м ві́чнаго спасе́нія, да в ра́дості неізглаго́ланній оби́телей Небе́сних вку́пі с ва́ми воспоє́м Всеще́дрому і Всеблаго́му Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельським житіє́м жи́тельствовавше, отці́ преблаже́ннії, безпло́тним подража́ти тща́щеся доброді́тельми, чистото́ю тіх ду́ші своя́ убели́ли єсте́, тілеса́ істончи́вше труди́ по́стничеськими, я́ко а́нгели на землі́ пребива́ли єсте́; ми же таково́му житію́ ва́шему див'я́щеся, сію́ похвалу́ прино́сим вам:","Ра́дуйтеся, ми́ра ізбі́гшії і во ото́ки морськи́я прише́дшії;","ра́дуйтеся, прише́ствієм ва́шим мно́гих ко Христу́ приве́дшії.","Ра́дуйтеся, жи́тельство і́ночеськоє в пусти́ні сі́верній созида́вшії;","ра́дуйтеся, по́двиги до́брими і чудеси́ та́мо просія́вшії.","Ра́дуйтеся, рай благоцвіту́щий во страні́ полу́нощній насади́вшії;","ра́дуйтеся, тоя́ язи́ки сві́том і́стини Христо́ви просвіти́вшії.","Ра́дуйтеся, я́ко труди́ мно́гими труди́вшіїся во благоче́стії;","ра́дуйтеся, а́нгели земні́ї і челові́ци Небе́снії.","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Кондак 1","ps":["Ізбра́ннії воі́тели Христо́ві і благоче́стія подви́жници, преподо́бнії Зоси́мо, Савва́тіє і Ге́рмане со сподви́жники досто́йними, ва́ми бо ди́вно просла́вися і́м'я Госпо́днє во страна́х Біломо́рія, і вся Ру́ськая Це́рков весели́ться о святи́ні ва́шей; покланя́ющеся той, благода́рно вопіє́м вам:","Ра́дуйтеся, преподо́бнії отці́ на́ші, всі святі́ї Солове́цькії."]},{"h":"Молитва","ps":["О сла́вний собо́ре, святі́ї землі́ Солове́цькия, преподо́бних сосло́віє, пусти́нников со́нме, і́ноков ли́че! Собла́зном ві́ка сего́ умертви́вшеся, вре́менному ві́чноє предпоче́тше, ви вселе́нієм в морськи́я ото́ки в рабо́ту Го́споду себі́ всеці́ло преда́ли єсте́, па́че же песка́ морська́го умно́жистеся і па́че звізд небе́сних сія́єте ни́ні в невече́рнім Ца́рствії Влади́ки Христа́ Бо́га. Святи́ться земля́ сія́ по́двиги ва́шими, живе́ть благоуха́ющи ва́шими моли́твами, трепе́щеть содержа́щи честни́я мо́щі ва́ша, і во времена́ послі́дняя освяще́на бисть кро́вію му́ченичеською, за ві́ру Христо́ву зді ізлія́вшеюся. Всі святі́ї Солове́цькії, ї́хже імена́ ві́ми і не ві́ми, вінці́ нетлі́нними от Го́спода увінча́вшіїся, і ри́зами убіле́нними оді́явшіїся, благослове́ннії наслі́дници Го́рняго Ієрусали́ма, молі́те Бо́га о оби́телі ва́шей і бра́тії єя́, і о всем Оте́честві на́шем: да в любві́ і єдиному́дрії во́їнствуєть свята́я Це́рков Правосла́вная, да ві́ра на́ша пребива́єть непри́коснове́нна злу, да да́руєть нам Госпо́дь си́лу ю іспові́довати, і а́ще потре́бно бу́деть, вся за ню претерпі́ти, і да́же до дне су́днаго непоро́чну сохрани́ти і неосужде́нно предста́ти Престо́лу Ца́рствія Єго́ і со всі́ми святи́ми ви́ну прославля́ти держа́ву, і великолі́піє, і человіколю́біє Єго́ во ві́ки віко́в. Амі́нь."]},{"h":"Інша молитва","ps":["О Боже́ственний по́лче, небе́снії во́їни Христа́ Бо́га, преподо́бнії і богоно́снії отці́ Солове́цькії! Ви пе́рвіє ра́лом єва́нгельських уче́ній ду́ші своя́ плодоно́сни яви́ли єсте́, по́сліжде і непло́дную пусти́ню сію́ я́ко благоцвіту́щий рай соді́лали єсте́ і яви́лися єсте́ же́ртви благоприя́тния Бо́гу, преобрази́вшеся у́мним ді́ланієм, во сві́ті невече́рнім узрі́ли єсте́ бу́дущия жи́зні сла́ву. Боже́ственним огне́м ду́ші своя́ возже́гше, востекли́ єсте́ в Сіо́н го́рній, і нетва́рнаго сві́та причасти́лися єсте́. Ті́мже і нам на землі́ су́щим, хода́тайствуйте душа́м спасе́ніє, земни́х плодо́в ізоби́ліє, времена́ ми́рна, бла́га, да і ми недосто́йнії, направля́ємії ва́шими моли́твами, поне́ на коне́ць на́шего многом'яте́жнаго житія́, возлю́бим ві́чная па́че вре́менних, і во єдинонадеся́тий час порабо́таєм со усе́рдієм Небе́сному Домовлади́ці Христу́, і усли́шим Єго́ благоуві́тливий глас: прийді́те, наслі́дуйте угото́ванноє вам Ца́рство от сложе́нія ми́ра. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Взиску́юще Христа́ вожделі́ннаго би́сера во страну́ полу́нощную востекли́ єсте́, і по́двигом первонача́льников Солове́цьких поревнова́вше, ліса́ і пусти́ні облагоуха́ли єсте́ свої́ми Богоуго́дними моли́твами. Тім же і Христо́с вас просла́ви, і ми вам вопіє́м: всі святі́ї Солове́цтії, молі́те Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Духо́внаго жи́тельства жела́юще, устреми́стеся в суро́вия о́строви Біломо́рія, і безбі́дно препли́вше жите́йськоє мо́ре, собла́знов мирськи́х ізбіго́сте і в ра́дості ве́лієй водвори́стеся. Непреста́нним у́мним восхожде́нієм Бо́га дости́гли єсте́ і нас у́чіте небе́сному восхо́ду."]},{"h":"Величання","ps":["Велича́єм вас, / всі святі́ї Солове́цтії, / і чтим святу́ю па́м'ять ва́шу, / ви бо мо́лите за нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Василію Великому, архієпископу Кесарії Каппадокійської","e":"Akathist to St Basil the Great, Archbishop of Caesarea in Cappadocia","secs":[{"h":"Кондак 1","ps":["Взбра́нний Царя́ Небе́снаго служи́телю і вели́кий Це́ркве Христо́ви святи́телю, пра́вия ві́ри іспові́данієм во всем ми́рі просія́вий, ве́ліє імі́яй дерзнове́ніє ко Святі́й Тро́йці, от вся́ких нас бід огражда́й, со умиле́нієм тебі́ вопію́щих:","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, от ві́ка предизбравий тя, преблаже́нне о́тче Васи́ліє, би́ти вели́каго світи́льника Це́ркве Своєя́, ангелоподобна житіє́м яви́ тя: вельми́ бо богоми́слієм і поще́ньми в пусти́ні подвиза́вся, на висоту́ доброді́телі восше́л єси́. Ті́мже, ве́лію на небесі́х сла́ву стяжа́вий, прийми́ от нас смире́нних, восхваля́ти тя дерза́ющих, сія́ хвале́бния глаго́ли:","Ра́дуйся, Васи́ліє, ца́рствія тезоимени́тий;","ра́дуйся, ієра́рше Христо́во вели́кий.","Ра́дуйся, Це́ркве непоколеби́мий сто́лпе;","ра́дуйся, ро́да свята́го пречестна́я о́трасле.","Ра́дуйся, от ю́ности Царю́ Небе́сному всеусе́рдно служи́вий;","ра́дуйся, все́ю земно́ю, найпа́че же небе́сною, прему́дростію ум свой обогати́вий.","Ра́дуйся, ку́пно со друго́м твої́м Григо́рієм Богосло́вом в любому́дрії преуспевавий;","ра́дуйся, учи́теля твоєго́ Євву́ла прему́дрими словеси́ ко Христу́ обрати́вий.","Ра́дуйся, чистоти́ і цілому́дрія преди́вний храни́телю;","ра́дуйся, ко спасе́нію ві́рний путеводи́телю.","Ра́дуйся, душепа́губних єресе́й разори́телю;","ра́дуйся, богому́дрий вселе́нния учи́телю.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 2","ps":["Ви́дя Це́рков Христо́ву аріянським злові́рієм обурева́єму, і Бо́жию призванію повину́яся, ізше́л єси́, преподо́бне о́тче, із пусти́ні, ю́же возлюби́л єси́, во град Кесарі́ю, іді́же благода́ть свяще́нства восприя́л єси́ і во архієпи́скопа поста́влен бил єси́, сло́во спасе́нія велегла́сно всім конце́м землі́ благовіству́я, ві́рния же по вся дні поуча́я Бо́гу, Созда́телю всіх, досто́йно воспіва́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум ві́рних богові́дінієм просвіща́я, святи́телю Христо́во Васи́ліє, єстество́ су́щих із'яснил єси́, і Бо́га неви́димаго в творе́ніїх ру́ку Єго́ познава́ти научи́л єси́. Ті́мже і ми, твої́ми богому́дрими уче́ньми просвіща́ємії, взива́єм си́це:","Ра́дуйся, позна́нієм Бо́га, в шесть дній вся сотво́рша, ві́рния озари́вий;","ра́дуйся, ди́вния діла́ Єго́ досто́йно восхваля́ти научи́вий.","Ра́дуйся, пала́то му́дрости преукраше́нная;","ра́дуйся, сокро́вищниця богосло́вія преізоби́льная.","Ра́дуйся, я́ко та́йни прему́дрости Бо́жия во всем ми́рі ви́діти науча́л єси́;","ра́дуйся, я́ко і в ма́лих ве́щіх вели́чіє Бо́жиє зрі́ти наставля́л єси́.","Ра́дуйся, сві́та первозда́ннаго красоту́ живописа́вий;","ра́дуйся, тве́рдую си́лу пе́рваго глаго́ла Бо́жия во вселе́нній показа́вий.","Ра́дуйся, би́лієм травним ско́рую ги́бель сла́ви земни́я ізобразивий;","ра́дуйся, во благолі́пії світи́л небе́сних Со́лнце Пра́вди Христа́ зрі́ти указа́вий.","Ра́дуйся, трудолю́бієм ма́лой тва́рі от лі́ності люде́й отвращавий;","ра́дуйся, челові́ку, царю́ тва́рей, над страстьми́ ца́рствовати повелевавий.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго укріпля́єм, о́тче святи́й Васи́ліє, противобо́рствовал єси́ богоотступнику Іулія́ну, і зло́є єго́ на христия́ни умишле́ніє разруши́ти умоли́л єси́ Го́спода і Пречи́стую Єго́ Ма́тер, да всі Єди́ному Бо́гу благода́рно пою́ть: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй ре́вность ве́лію по Бо́зі Вседержителе і меч сло́ва Єго́ в ру́ці восприї́м, пле́вели язи́чеськаго Іуліянова нече́стія ско́ро посі́кл єси́, ві́рния же во благоче́стії утверди́л єси́; научи́ і нас, преподо́бне о́тче, єди́ному то́чію Бо́гу чи́стим житіє́м служи́ти, зову́щих ті си́це:","Ра́дуйся, го́рдаго Іулія́на в богоотсту́пстві му́жественно обличи́вий;","ра́дуйся, христоненавистния єго́ начина́нія разруши́вий.","Ра́дуйся, моли́твою сле́зною, я́ко копем, того́ порази́вий;","ра́дуйся, ско́рую єго́ поги́бель предвозвісти́вий.","Ра́дуйся, лю́ди Бо́жия, я́коже Мойсе́й дре́вле Ізра́їля, от ідолослуже́нія свободи́вий;","ра́дуйся, пле́вели нече́стія істребивий.","Ра́дуйся, пи́щею слове́с Бо́жиїх ві́рния ізоби́льно наси́тивий;","ра́дуйся, струя́ми благода́ті се́рдця напоі́вий.","Ра́дуйся, скрижа́ли велі́ній Христо́вих тве́рдо содержа́ти увещевавий;","ра́дуйся, уче́ніє уст твої́х житіє́м утверди́вий.","Ра́дуйся, ра́бе благи́й і ві́рний;","ра́дуйся, ді́лателю вертогра́да Христо́ва усе́рдний.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 4","ps":["Бу́рю я́рости царя́ Уа́лента, аріянським злові́рієм одержи́ма, ти, свя́тче Бо́жий, си́лою Ду́ха в тебі́ живу́ща, утиши́л єси́, і мир Це́ркві Святі́й дарова́л єси́, святи́ми труда́ми твої́ми і те́плими к Бо́гу моли́твами Єму́же ра́дуяся воспі́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав злочести́вий Уа́лент, я́ко ти, ієра́рше Бо́жий, во і́стині стої́ши, і всі ві́рнії гла́су твоєму́ повину́ються, восхоті́ от пра́вия ві́ри тя отврати́ти; сего́ ра́ди посла́ к тебі́ єпа́рха своєго́ Моде́ста, по́сліжде же і сам при́йде в Кесарі́ю. Но ти, богоно́се о́тче, ні гні́ва царе́ва, ні преще́ній гро́знаго єго́ воєво́ди не устраши́лся єси́; ми же, прославля́юще сицево́є твоє́ тве́рдоє іспові́даніє, вопіє́м ті:","Ра́дуйся, побо́рниче пра́вия ві́ри непоколеби́мий;","ра́дуйся, па́стирю, ду́шу за ві́рния положи́ти гото́вий.","Ра́дуйся, тве́рдоє іспові́даніє Петро́во показа́вий;","ра́дуйся, Іліїну́ ре́вность о сла́ві Святи́я Тро́йці яви́вий.","Ра́дуйся, гнів царя́ нечести́ваго боголепієм священнослуженія ути́шивий;","ра́дуйся, богому́дрими словеси́ уста́ зловернаго воєво́ди загради́вий.","Ра́дуйся, я́ко преще́нія ізгна́нієм і му́ками не убоя́лся єси́;","ра́дуйся, я́ко і смерть за Христа́ восприя́ти жела́л єси́.","Ра́дуйся, гоне́ніє за ві́ру претерпі́вий;","ра́дуйся, скорбми́ мно́гими в ра́дость Го́спода вше́дий.","Ра́дуйся, і́стину Христо́ву пред цари́ і влади́ки небоя́зненно віща́вий;","ра́дуйся, ві́рнаго служи́теля Царя́ Небе́снаго тве́рдим іспові́данієм себі́ показа́вий.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́, святи́телю Христо́во Васи́ліє, пресві́тлими милосе́рдія луча́ми нощ скорбе́й мра́чную осіява́ющая, мглу бід отгоня́ющая, і всім, в мо́ре житія́ бурном пливущим, путь ві́рний к Ца́рству Небе́сному показу́ющая, да всі спаса́ющему Бо́гу ра́дующеся пою́ть: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше всі тя, святи́телю Бо́жий, я́ко отця́ чадолюби́ва, в напа́стіх і ско́рбіх от тебе́ по́мощі усе́рдно іска́ху; ти же о всіх милосердовал єси́, о́браз ві́ри і́стинния в себі́ сим показу́я. Бу́ди, преблаги́й о́тче, ско́рий помо́щник і нам, гріхми́ і скорбми́ обурева́ємим, с любо́вію ті вопію́щим:","Ра́дуйся, світи́льниче любве́, от Христа́ возсія́вий;","ра́дуйся, Отцю́ Небе́сному в милосе́рдії подража́вий.","Ра́дуйся, неіму́щих бога́тоє сокро́вище;","ра́дуйся, в ну́ждах ві́рноє прибі́жище.","Ра́дуйся, гла́дния, я́коже Іо́сиф дре́вле, препита́вий;","ра́дуйся, мно́гі оби́телі бездомним і убо́гим в Кесарі́ї основа́вий.","Ра́дуйся, прокаже́нних ра́ни свої́ма рука́ма, я́ко самаряни́н до́брий, врачевавий;","ра́дуйся, гони́теля твоєго́ Моде́ста неду́гующа ісціли́вий і от народния ка́зні того́ ізба́вивий.","Ра́дуйся, вдови́цю убо́гую от оби́ди єпа́рха защити́вий;","ра́дуйся, жені́ грі́шниці проще́ніє гріхо́в у Бо́га іспроси́вий.","Ра́дуйся, сиро́т о́тче і стра́ждущих утіше́ніє;","ра́дуйся, во грісі́х погиба́ющих вразумле́ніє і ісправле́ніє.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 6","ps":["Пропові́дник всему́ ми́ру і́стини Христо́ви яви́лся єси́, святи́телю о́тче Васи́ліє, си́лою благода́тною сло́ва твоєго́, я́ко о́стрієм меча́, гріхо́вная се́рдця прониця́яй і к покая́нію возбужда́яй, да всі чи́стим се́рдцем Тро́йці Святі́й пою́ть: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ на тве́рди церко́вній, я́ко вели́коє світоза́рноє світи́ло, о́тче Васи́ліє, всю поднебе́сную разумі́нієм ві́ри і́стинния просвіща́ющеє, мрак же страсте́й гріхо́вних отгоня́ющеє, от ни́хже і нас свободи́, зову́щих ті си́це:","Ра́дуйся, Тро́йці Святи́я ві́рний служи́телю;","ра́дуйся, та́їн ві́ри богоозаренний із'яснителю.","Ра́дуйся, я́ко Отцю́ Си́на Єдиносу́щна і Ду́ха сопресто́льна велегла́сно пропові́дал єси́;","ра́дуйся, я́ко і́стину о Сві́ті Превечном, от Сві́та Преві́чна просіявшем, ві́рним із'яснил єси́.","Ра́дуйся, Го́спода Спаси́теля, я́ко Бо́га воплоще́нна і Творця́ всіх вік іспові́давий;","ра́дуйся, та́їнство двух єсте́ств і єди́ной Іпоста́си во Христі́ Бо́зі показа́вий.","Ра́дуйся, си́лою царственнаго сло́ва твоєго́ бога́тим жи́тници откри́ти повелі́вий;","ра́дуйся, от кори́сти непра́ведния мно́гі уче́нієм отврати́вий.","Ра́дуйся, душепагубноє пія́нство сло́вом, я́ко гро́мом, поражавий;","ра́дуйся, жестокосе́рдіє і за́висть із серде́ць істреблявий.","Ра́дуйся, воздержа́нія ревнительний наста́вниче;","ра́дуйся, покая́нія неумолчний пропові́дниче.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 7","ps":["Хотя́ ві́рния от соборищ арія́нських огради́ти, ти, свя́тче Бо́жий Васи́ліє, вся в це́ркві благоукрасил єси́, і чин умили́тельний Боже́ственния Литургі́ї му́дре сложил єси́, мно́гі же моли́тви, я́ко ми́ро благово́нноє, от уст твої́х огнедохновенних ізлія́шася, і́миже во грісі́х проще́нія себе́ і усо́пшим бра́тіям про́сим, Тро́йцю же Пресвяту́ю сла́вим, пою́ще: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго Ааро́на ві́рнії зря́ху в тебі́, о́тче святи́й Васи́ліє, єгда́ боголі́пно Же́ртву Безкро́вну священноді́йствовал єси́, дарова́нії Свята́го Ду́ха, я́ко многоці́нними ка́меньми светящеюся оде́ждою, укра́шен. Ни́ні же во ви́шнем же́ртвенниці о Це́ркві предстательствуяй, помина́й ви́ну і нас, тебі́ умиле́нно зову́щих:","Ра́дуйся, архієре́ю Бо́жий, преізобильную, я́коже і Ааро́н, благода́ть свяще́нства восприя́вий;","ра́дуйся, ве́ліє дерзнове́ніє в моли́тві за лю́ди стяжа́вий.","Ра́дуйся, та́їн Бо́жиїх му́дрий строї́телю;","ра́дуйся, чи́на церко́внаго благоукраси́телю.","Ра́дуйся, служе́нію Литургі́ї от Самаго́ Христа́, я́коже і Іа́ков апо́стол, науче́нний;","ра́дуйся, моли́твенниче, Ду́хом Бо́жиїм озаре́нний.","Ра́дуйся, небе́сним сві́том, я́коже ні́циї ви́діша, в служе́нії осіява́ємий;","ра́дуйся, А́нгели, я́ко ні́киїми пресві́тлими мужами, окружа́ємий.","Ра́дуйся, я́ко твоє́ю пе́рвіє моли́твою к восприя́тію Та́їн Христо́вих себі́ уготовляєм;","ра́дуйся, я́ко твої́ми словеси́ во ве́чер П'ятидеся́тници колінопокло́нная проше́нія возсила́єм.","Ра́дуйся, Кесарі́йськаго святи́тельськаго престо́ла сла́во і украше́ніє;","ра́дуйся, я́ко ієре́ом всея́ Це́ркве подає́ши от Бо́га благода́тноє в служе́нії укріпле́ніє.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє виді́ніє откри́ся о тебі́, святи́телю Васи́ліє, преподо́бному Єфре́му Сиріянину: єди́ножди бо показа́ єму́ тя Бог, я́ко столпа́ о́гненна, висоти́ небе́сния досязающа, по́сліжде же, прише́д в Кесарі́ю, преподо́бний узрі́ тя о́гненним язи́ком лю́ди поуча́юща і умиле́нно возопи́ Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь сві́том небе́сним серафи́мськия любве́ пламені́л єси́, богоно́се Васи́ліє; словеса́ бо твоя́ бі́ша, я́ко мо́лнія, є́ресі попаля́ющая, душі́ же ві́рних пла́менем ві́ри і любве́ просвіща́ющая; даждь у́бо і нам, о́тче, моли́твою твоє́ю, і́скру хотя́ ма́лую твоєя́ любве́ імі́ти, зовущим сицева́я:","Ра́дуйся, пламеновидний сто́лпе, є́ресі попаля́яй;","ра́дуйся, огнь ві́ри і́стинния і любве́ нелицемі́рния возгреваяй.","Ра́дуйся, лжі А́рієви є́ресі тве́рдий обличи́телю;","ра́дуйся, і́стини Христо́ви пла́менний ревни́телю.","Ра́дуйся, я́ко го́рдаго Євно́мія, Си́на Бо́жия хуливша, посрами́л єси́;","ра́дуйся, я́ко Македо́нієво хуле́ніє Ду́ха Свята́го препрі́л єси́.","Ра́дуйся, суєму́дрія Несто́рієва разори́телю;","ра́дуйся, че́сти Пресвяти́я Богома́тере усе́рдний защити́телю.","Ра́дуйся, па́стирю, небе́сним блиста́нієм любве́ осіява́ємий;","ра́дуйся, учи́телю ві́ри, словеса́ молнієно́сная віща́вий.","Ра́дуйся, богонасажде́нная ма́слино, мно́гих святи́х Це́ркві проізве́дшая;","ра́дуйся, лозо́, богому́дрих Правосла́вія побо́рников ізрасти́вшая.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 9","ps":["Все єрети́чеськоє собо́рище не возмо́же противостоя́ти благода́тній, я́же в тебі́, святи́й о́тче, обита́ше, си́лі; ю́ношу бо ні́коєго, во власть сатани́ впа́дша, си́лою моли́тви твоєя́ от сіте́й вра́жиїх от'ял єси́, пока́явшася же ко Христу́ возврати́л єси́, благода́рно поя́ Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йством богодухнове́нним твої́м, святи́телю Васи́ліє, побеждаємії і ви́дівше пресла́вноє на ю́ноші би́вшеє чу́до, мно́зі от єрети́ко ко єди́ній присоєдинишася Це́ркві, єя́же ві́рними і послу́шними ча́дами і нас би́ти сподо́би, зову́щих ті си́це:","Ра́дуйся, вся конці́ землі́ небе́сним уче́нієм осія́вий;","ра́дуйся, благода́тію Христо́вою те́мния си́ли а́да побеждавий.","Ра́дуйся, ю́ношу от сіте́й сатани́ свободи́вий;","ра́дуйся, Ті́лом і Кро́вію Христо́вою того́ наси́тивий.","Ра́дуйся, я́ко душе́, Кро́вію Христо́вою іскупленней, поги́бнути не дал єси́;","ра́дуйся, я́ко, в поги́бельний гріх впа́дша, ю́ношу прости́ти, Христа́ умоли́л єси́.","Ра́дуйся, я́ко пресла́вним чу́дом лю́ди удиви́л єси́;","ра́дуйся, я́ко обраще́нієм заблу́ждша А́нгели возрадовал єси́.","Ра́дуйся, проси́ти у Го́спода А́нгелов огражде́нія нас науча́яй;","ра́дуйся, А́нгела Храни́теля моли́твою твоє́ю к нам приближаяй.","Ра́дуйся, от наві́тов вра́жиїх свободи́телю;","ра́дуйся, во іскуше́ніїх ско́рий защити́телю.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ Творе́ць Своє́ слове́сноє созда́ніє, показа́ тя тве́рдаго ві́рних защи́тителя, о́тче Васи́ліє, і Це́ркве Своєя́ храни́теля, да світ Правосла́вія тобо́ю всему́ ми́ру явле́н бу́деть, і всі ві́рнії благода́рні Тро́йці Святі́й воспіва́ють: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ Це́ркве, і тве́рдоє ві́рних огражде́ніє яви́лся єси́, о вели́кий в ієра́рсіх Васи́ліє, єгда́ во гра́ді Нике́йстім врата́ церко́вная си́лою моли́тви твоєя́ отве́рзл єси́ і і́стину пра́вия ві́ри сим яви́л єси́, уста́ же ху́лящих і́м'я Христо́во загради́л єси́. Нам же, Го́спода Спаси́теля правосла́вно ісповедающим, отве́рзи, о́тче, милосе́рдія Бо́жия две́рі, заступле́нієм твої́м, да зове́м ті си́це:","Ра́дуйся, А́нгеле земни́й, Це́ркве Христо́ви храни́телю;","ра́дуйся, Бо́гом предизбранний ві́рних защити́телю.","Ра́дуйся, врата́ церко́вная, я́коже Ілія́ дре́вле не́бо, моли́твою откри́вий;","ра́дуйся, храм святи́й, єретиками восхище́нний, па́ки ві́рним возврати́вий.","Ра́дуйся, ві́рних от єресе́й оградивий;","ра́дуйся, Це́рков Христо́ву неврежде́нну от лжеуче́ній сохрани́вий.","Ра́дуйся, превели́коє на небесі́ і́м'я Христо́во і на землі́ чудеси́ возвели́чивий;","ра́дуйся, Правосла́віє во вселе́нній утверди́вий.","Ра́дуйся, я́ко тобо́ю го́рдость нечести́вих низложи́ся;","ра́дуйся, я́ко тобо́ю смире́ніє ві́рних вознесе́ся.","Ра́дуйся, я́ко тобо́ю ві́ра свята́я прославля́ється;","ра́дуйся, я́ко тобо́ю Це́рков Христо́ва ди́вно красу́ється.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 11","ps":["Пі́ніє подоба́ше возноси́мо би́ти тебі́ с небесі́, а не от землі́, о пречу́дний Васи́ліє, небе́с бо явле́ніє на землі́ бил єси́, к небесі́ богому́дрими уче́ньми твої́ми уми́ ві́рних возводи́л єси́, і ни́ні с небе́с на ни ми́лостиво призира́єши і преізобильную всім нам благода́ть подає́ши от Щедродателя Христа́ Бо́га, Єму́же со А́нгели в небесі́х ви́ну поє́ши: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоно́сний світи́льниче, весь мно́гими дара́ми Бо́жиїми і доброді́тельми сія́ющ, бил єси́, свя́тче Бо́жий Васи́ліє, ї́миже і ни просвіти́, в доброді́телі наста́ви і ко Ца́рствію Небе́сному напра́ви, зову́щих тебі́ си́це:","Ра́дуйся, Це́ркве Христо́ви незаходи́моє сія́ніє і пресві́тлоє украше́ніє;","ра́дуйся, я́ко подає́ши христия́ном во вся ві́ки во ві́рі пра́вій утвержде́ніє.","Ра́дуйся, тала́нти, Бо́гом вруче́нния тебі́, усовершивий;","ра́дуйся, от земни́я му́дрости вся ко спасе́нію поле́зная собра́вий.","Ра́дуйся, си́ну царе́ву во сла́ву правові́рія чуде́сноє ісціле́ніє дарова́вий;","ра́дуйся, цілому́дренноє житіє́ Анаста́сія пресви́тера і супру́жници єго́ прозрі́вий.","Ра́дуйся, кро́тко обидящим тя прощавий;","ра́дуйся, смире́нієм і терпі́нієм клевети́ на тя побеждавий.","Ра́дуйся, уста́в соверше́ннаго житія́ і́ноком учредивий;","ра́дуйся, мно́гі і́ноки в оби́теліх собра́вий.","Ра́дуйся, пра́вила і кано́ни і спаси́тельная уче́нія в наслі́діє Це́ркві оста́вивий;","ра́дуйся, богому́дрими списа́ньми твої́ми многоці́нноє сокро́вище к назида́нію христия́ном дарова́вий.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 12","ps":["Благода́ть вели́кую дарова́ тебі́ Христо́с Бог, святи́телю о́тче Васи́ліє, не то́чію заблу́ждшия к покая́нію приводи́ти, но і мно́гі неві́рния ко Христу́ обраща́ти; єгда́ бо уже́ сме́ртно болі́зновал єси́, ко блаже́нній кончи́ні приближа́яся, євре́янина врача́, с жено́ю і ча́ди, Святи́м Креще́нієм просвіти́л єси́ і Тро́йці Святі́й ку́пно с ни́ми благода́рственную воспі́л єси́ піснь: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ть ті ве́лія похвали́ всі ві́рнії, о вели́кий ієра́рше Васи́ліє, вельми́ бо на землі́ до конця́ житія́ твоєго́ во сла́ву правові́рія потруди́вся, в Небе́сная Свята́я Святи́х вшел єси́, і я́ко ві́рний Бо́жий служи́тель, Тро́йці Святі́й предста́л єси́, іді́же і о нас ви́ну моли́ся, о преблаги́й о́тче, ві́рою ча́діх твої́х, с любо́вію зову́щих ті си́це:","Ра́дуйся, ца́рськоє свяще́ніє, прехва́льне Васи́ліє;","ра́дуйся, Тро́йці Святи́я преукрашенноє селе́ніє.","Ра́дуйся, чуде́сними дія́ньми Царя́ Небе́снаго просла́вивий;","ра́дуйся, ре́вности своєя́ о сла́ві ві́ри і в болі́зні сме́ртній не оста́вивий.","Ра́дуйся, ра́ди обраще́нія неві́рна чуде́сноє продленіє себі́ житія́ у Бо́га іспроси́вий;","ра́дуйся, свої́ма рука́ма, возста́в с одра́ сме́ртнаго, Креще́нієм того́ просвіти́вий.","Ра́дуйся, труда́ми і му́дростію си́лу злові́рія побіди́вий;","ра́дуйся, благові́рним царе́м побі́ди на враги́ іспроси́вий.","Ра́дуйся, апо́столом в труді́х єдинонра́вний;","ра́дуйся, со святи́телі Григо́рієм Богосло́вом і Іоа́нном Златоу́стом, по повелі́нію твоєму́, єдиноче́стно прославля́ємий.","Ра́дуйся, нетлі́нієм моще́й просія́вий і сла́вою на небесі́х увінча́нний;","ра́дуйся, те́плий і вели́кий засту́пниче, от Бо́га нам дарова́нний.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 13","ps":["О пресвяти́й і вели́кий ієра́рше Христо́во Васи́ліє, Правосла́вія світи́ло і ві́рних огражде́ніє! При́зри с небесе́ на сіє́, приноси́моє ті на́ми, хвале́ніє, і моли́твами твої́ми от страсте́й і бід нас огради́, в пра́вій ві́рі соблюди́ і Ца́рствія Небе́снаго сподо́би, да ку́пно с тобо́ю і всі́ми святи́ми Тро́йці Святі́й во ві́ки віко́в поє́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць, от ві́ка предизбравий тя, преблаже́нне о́тче Васи́ліє, би́ти вели́каго світи́льника Це́ркве Своєя́, ангелоподобна житіє́м яви́ тя: вельми́ бо богоми́слієм і поще́ньми в пусти́ні подвиза́вся, на висоту́ доброді́телі восше́л єси́. Ті́мже, ве́лію на небесі́х сла́ву стяжа́вий, прийми́ от нас смире́нних, восхваля́ти тя дерза́ющих, сія́ хвале́бния глаго́ли:","Ра́дуйся, Васи́ліє, ца́рствія тезоимени́тий;","ра́дуйся, ієра́рше Христо́во вели́кий.","Ра́дуйся, Це́ркве непоколеби́мий сто́лпе;","ра́дуйся, ро́да свята́го пречестна́я о́трасле.","Ра́дуйся, от ю́ности Царю́ Небе́сному всеусе́рдно служи́вий;","ра́дуйся, все́ю земно́ю, найпа́че же небе́сною, прему́дростію ум свой обогати́вий.","Ра́дуйся, ку́пно со друго́м твої́м Григо́рієм Богосло́вом в любому́дрії преуспевавий;","ра́дуйся, учи́теля твоєго́ Євву́ла прему́дрими словеси́ ко Христу́ обрати́вий.","Ра́дуйся, чистоти́ і цілому́дрія преди́вний храни́телю;","ра́дуйся, ко спасе́нію ві́рний путеводи́телю.","Ра́дуйся, душепа́губних єресе́й разори́телю;","ра́дуйся, богому́дрий вселе́нния учи́телю.","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Кондак 1","ps":["Взбра́нний Царя́ Небе́снаго служи́телю і вели́кий Це́ркве Христо́ви святи́телю, пра́вия ві́ри іспові́данієм во всем ми́рі просія́вий, ве́ліє імі́яй дерзнове́ніє ко Святі́й Тро́йці, от вся́ких нас бід огражда́й, со умиле́нієм тебі́ вопію́щих:","Ра́дуйся, Васи́ліє, вели́кий ієра́рше, Правосла́вія всеми́рний світи́льниче."]},{"h":"Молитва","ps":["О вели́кий во ієра́рсіх, вселе́нния учи́телю богому́дрий, преблаже́нне о́тче Васи́ліє! Ве́лія по́двиги і труди́ твоя́, я́же во сла́ву Святи́я Це́ркве соверши́л єси́: ти іспові́дник тве́рдий і світи́льник ві́ри Христо́ви на землі́ бил єси́, сві́том Богові́дінія ві́рния озаря́яй, ло́жная уче́нія попаля́яй і всему́ ми́ру сло́во спаси́тельния і́стини возвіща́яй. Ни́ні же, ве́ліє на Небесі́х імі́яй дерзнове́ніє ко Святі́й Тро́йці, помози́ нам, со смире́нієм к тебі́ припадающим, тве́рдо і неізмі́нно святу́ю Правосла́вную ві́ру до конця́ житія́ на́шего сохрани́ти, от малові́рія же, сомні́ній і колеба́нія во ві́рі соблюди́, да не прельще́ни бу́дем богопроти́вних і душепа́губних уче́ній словеса́ми. Дух ре́вности святи́я, є́юже ти пламені́л єси́, о пресла́вний Це́ркве Христо́ви па́стирю, возгрі́й предста́тельством твої́м і в нас, ї́хже Христо́с поста́ви би́ти па́стирями, да всеусе́рдно просвіща́єм і утвержда́єм в пра́вій ві́рі слове́сноє ста́до Христо́во. Умоли́ Го́спода, да возви́ситься страна́ на́ша, і да да́руєть всему́ наро́ду на́шему здра́віє, долгоде́нствіє і во всем благо́є поспіше́ніє. Іспроси́, о милосе́рдий святи́телю, от Отця́ сві́тов і всім, вся́кий дар коєму́ждо благопотре́бен: младе́нцем благо́є в стра́сі Бо́жиєм возраста́ніє, ю́ним целому́дріє, ста́рим і немощни́м укріпле́ніє, скорб'я́щим утіше́ніє, недугующим ісціле́ніє, заблуждшим вразумле́ніє і ісправле́ніє, оби́димим заступле́ніє, сирота́м і вдови́цям защище́ніє, іскуша́ємим благода́тноє поможе́ніє, отшедшим от сего́ вре́меннаго житія́ отце́м і бра́тіям на́шим блаже́нноє упокоє́ніє. Єй, свя́тче Бо́жий, при́зри ми́лостиво от оби́телей Го́рніх на нас, смире́нних, мно́гими соблазнами і напа́стьми обурева́ємих, і к землі́ приве́рженних возведи́ к висоті́ Небе́сній. Препода́ждь нам, преблаги́й о́тче, твоє́ архипа́стирськоє і свято́є благослове́ніє, да, о́ним осіня́ємії, в сіє́ но́воє лі́то і во все про́чеє вре́м'я живота́ на́шего в ми́рі, покая́нії і послуша́нії Святі́й Правосла́вній Це́ркві поживе́м, за́повіді Христо́ви усе́рдно творя́ще, по́двигом до́брим ві́ри подвиза́ющеся, і та́ко Ца́рствія Небе́снаго дости́гнем, іді́же с тобо́ю і всі́ми святи́ми сподо́би Тро́йцю Святу́ю, Єдиносу́щную і Неразді́льную пі́ти і сла́вити во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий і пресвяти́й святи́телю о́тче Васи́ліє, пресла́вний Вселе́нськия Це́ркве учи́телю, сла́ви Пресвяти́я Тро́йці всеусе́рдний побо́рниче, Ма́тере Бо́жия і Єя́ пренепоро́чнаго ді́вства предизбранний іспові́дниче, пресві́тлий чистоти́, смире́нія і терпі́нія о́бразе. Се аз многогрі́шний і недосто́йний на висоту́ небе́сную взира́ти, смире́нно молю́ тя, о прему́дрий Це́ркве Христо́ви учи́телю, научи́ м'я та́ко богобоя́зненно житіє́ своє́ проводи́ти, да нікогда́ же на путь, Бо́жиїм повелі́нієм проти́вен, уклоню́ся іли́ совраще́н бу́ду. Соблюди́ і ізба́ви м'я твої́м многомо́щним предста́тельством от собла́знов ми́ра і ко́зней дия́вольських, я́коже ізба́вил єси́ от них ю́ношу, от Сладча́йшаго Спаси́теля на́шего отступи́вша і во власть сатани́ впа́дша. Да́руй мні си́лу душе́вную усе́рдним би́ти подража́телем доброді́телей твої́х висо́ких; соді́лай м'я во ві́рі пра́вій тве́рда і непоколеби́ма, укріпи́ м'я малоду́шнаго в терпі́нії і упова́нії на Го́спода, возгрі́й в се́рдці моє́м і́стинную Христо́ву любо́в, да небе́сних благ па́че всіх жела́ю і і́ми услажда́юся. Іспроси́ мні у Го́спода і́скреннєє о грісі́х сокруше́ніє, да про́чеє вре́м'я живота́ моєго́ в ми́рі, покая́нії і ісполне́нії за́повідей Христо́вих провожда́ти бу́ду. Єгда́ же час моєго́ сконча́нія приблизиться, ти, о преблаги́й о́тче, с Преблагослове́нною Ді́вою Марі́єю, тогда́ ускори́ на по́мощ, защити́ м'я от зло́бних наві́тов вра́жиїх, і сподо́би м'я наслі́дника би́ти ра́йських селе́ній, да ку́пно с тобо́ю і со всі́ми святи́ми непристу́пнаго Бо́жия вели́чества Престо́лу предста́ну і Живонача́льную, Єдиносу́щную же і Неразді́льную Тро́йцю прославля́ю і воспіва́ю, при́сно і в безконе́чния ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["О вели́кий і пресла́вний святи́телю Христо́в, всея́ вселе́нськия Це́ркве учи́телю богому́дрий, Правосла́вія тве́рдий іспові́дниче і побо́рниче, всеблаже́нне о́тче Васи́ліє! При́зри от висо́т небе́сних на нас, смире́нно к тебі́ припа́дающих, і умоли́ Го́спода Вседержи́теля, Єго́же ві́рний на землі́ служи́тель бил єси́, да да́руєть нам ві́ри пра́вия тве́рдоє і неізмі́нноє сохране́ніє, Це́ркві Святі́й послуша́ніє, житія́ на́шего ісправле́ніє, і во всіх ну́ждах, ско́рбіх і іскуше́ніїх ско́роє поможе́ніє, терпі́ніє же і укріпле́ніє. Пода́ждь нам твоє́ свято́є благослове́ніє, да о́ним осіня́ємії, сіє́ но́воє лі́то і во вся дні богоуго́дно в ми́рі і покая́нії поживе́м і во Ца́рствії Небе́снім сподо́бимся ку́пно с тобо́ю і со всі́ми святи́ми Живонача́льную Тро́йцю воспіва́ти і сла́вити, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Во всю зе́млю ізи́де віща́ніє твоє́, / я́ко приє́мшую сло́во твоє́, / і́мже боголі́пно научи́л єси́, / єстество́ су́щих уясни́л єси́, / челові́чеськія оби́чаї украси́л єси́, / ца́рськоє свя́щеніє, о́тче преподо́бне, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ основа́ніє непоколеби́моє Це́ркве, / подая́ всім некра́домоє госпо́дство челові́ком, / запечатлі́я твої́ми велі́ньми, // небоявле́нне Васи́ліє, преподо́бне."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Васи́ліє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Феодосію Великому","e":"Akathist to our Venerable Father Theodosius the Great","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, і́ночествующих му́дрий наста́вниче і покрови́телю, преблаже́нне о́тче Феодо́сіє, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Ікос 1","ps":["А́нгельський о́браз житія́ от ю́ности возлюби́вий, я́ко безпло́тен во пло́ті пожи́л єси́, преподо́бне Феодо́сіє, вся вре́менная і земна́я во уме́ти вміня́я. Сего́ ра́ди, я́ко а́нгела земна́го і челові́ка небе́снаго і́стинно тя почита́юще, со умиле́нієм вопіє́м ті:","Ра́дуйся, Каппадокі́ї свято́є прозябе́ніє.","Ра́дуйся, благочести́вих роди́телей благослове́нний пло́де.","Ра́дуйся, во ві́рі і благоче́стії воспита́нний.","Ра́дуйся, благода́тію Бо́жиєю приосіне́нний.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послі́дователю.","Ра́дуйся, за́повідей Госпо́дніх ві́рний ісполни́телю.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 2","ps":["Ви́дів на тебі́ сугу́бую благода́ть, о́тче Феодо́сіє, прозорли́вий уго́дник Бо́жий преподо́бний Симео́н благослови́в тя, предрече́, я́ко мно́го подвиза́тися бу́деши в превременнем сем житії́, Го́спода ра́ди. Ми же, ві́дяще, я́ко ти воі́стину ре́вностний служи́тель Бо́гу і бра́тії яви́лся єси́, в моли́твах, поще́ніїх і бді́ніїх о́браз бив твої́м ученико́м, воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум несумненний імі́л єси́ в себі́, о́тче Феодо́сіє, єгда́ сла́ву ми́ра сего́ презрі́в, і́ночеським по́двигом всеці́ло преда́лся єси́, стра́сті гріхо́вния в себі́ умерщвля́я і непреста́нними к Бо́гу моли́твами ду́шу свою́ насища́я. Ті́мже, усе́рдіє твоє́ похваля́юще, взива́єм си́це:","Ра́дуйся, от ю́ности по́стничеськоє житіє́ возлюби́вий.","Ра́дуйся, і́го Христо́во с любо́вію понеси́й.","Ра́дуйся, пло́ті мудрова́ніє умертви́вий.","Ра́дуйся, нищету́ во́льную себі́ усво́ївий.","Ра́дуйся, моли́тви, поста́ і воздержа́нія храни́телю.","Ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний ревни́телю.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 3","ps":["Си́лою сви́ше обле́клся єси́, мно́гія доброді́телі в себі́ стяжава́я, богому́дре Феодо́сіє, і благода́тію, я́ко ри́зою, оді́явся, собра́л єси́ і́ночествующих мно́жество, во є́же славосло́вити Творця́ вся́чеських пі́снію: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ве́лію ре́вность о по́двизі і́ночеськаго житія́ і сла́ви челові́чеськія ізбіга́я, потща́лся єси́, преподо́бне, в пусти́ню отити, і в пеще́ру, в не́йже волсви́ с дара́ми во Вифлеє́м к ро́ждшемуся Богомладенцю Христу́ ше́ствовавшії укривахуся, всели́лся єси́. Ми же, див'я́щеся пустиннолюбному житію́ твоєму́, усе́рдно вопіє́м:","Ра́дуйся, всего́ себе́ во́лі Бо́жієй преда́вий.","Ра́дуйся, житію́ безпло́тних поревнова́вий.","Ра́дуйся, пусти́ні благода́тноє украше́ніє.","Ра́дуйся, мона́шествующих сла́во і утіше́ніє.","Ра́дуйся, і́ночеськаго житія́ рачи́телю.","Ра́дуйся, чистоти́ душе́вния і тіле́сния усе́рдний храни́телю.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 4","ps":["Бу́рю помисло́в і страсте́й му́жественно претерпі́в, преподо́бне о́тче, обрі́л єси́ ти́хоє приста́нище - Христа́, Єго́же ра́ди во мно́зі долготерпі́нії нелі́ностно в житії́ твоє́м потруди́лся єси́, ни́ні же на небесі́х во сла́ві со А́нгели воспіва́єши Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше о подвижничестем житії́ твоє́м, пресла́вне Феодо́сіє, прихожда́ху к пеще́рі твоє́й і́щущії спасе́нія, ї́хже ти любому́дренно наставля́л єси́, да о суєтности земна́го житія́ сего́ і о сме́ртном часі́ непреста́нно помишля́ють. Ми же, ви́дяще таково́є попече́ніє твоє́ о спасе́нії бра́тії твоєя́, дерза́єм воспіва́ти си́це:","Ра́дуйся, пустиннолюбцев усе́рдний сподви́жниче.","Ра́дуйся, братолю́бія приле́жний строї́телю і те́плий о всіх моли́твенниче.","Ра́дуйся, на висоту́ доброді́телей возше́дий.","Ра́дуйся, на землі́ а́нгельськи пожи́вий.","Ра́дуйся, рабо́тающих Го́сподеві наста́вниче прему́дрий.","Ра́дуйся, помо́щниче немощни́м предо́брий.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́бился єси́, преподо́бне о́тче Феодо́сіє, сві́том богоуго́днаго житія́ твоєго́ всіх освіща́я і приходя́щих к тебі́ люби́ти Го́спода і Спаси́теля на́шего і Єму́ єди́ному нелі́ностно служи́ти науча́я, вопію́ще со умиле́нієм: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дим тя, преподо́бне о́тче Феодо́сіє, дости́гшаго в му́жа соверше́нна о Христі́ і преіспо́лненнаго дарова́ній Боже́ственних, во Єва́нгелії Христо́вом ві́рним обітова́нних. Ті́мже, воспіва́юще по́двиги і труди́ твоя́, взива́єм ті си́це:","Ра́дуйся, Це́ркви Христо́ви украше́ніє.","Ра́дуйся, благода́ті Бо́жия вмісти́лище.","Ра́дуйся, по́стниче неізнемогающий.","Ра́дуйся, трудолю́бче благослове́нний.","Ра́дуйся, о́бразе смире́нія і послуша́нія.","Ра́дуйся, учи́телю чистоти́ і цілому́дрія.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 6","ps":["Пропові́дник і́стиннаго покая́нія і послуша́нія бил єси́, преподо́бне Феодо́сіє, сего́ ра́ди мно́зі прихожда́ху к тебі́, спасе́нія і́щуще; єгда́ же число́ ученико́в твої́х умно́жишася, ти оби́тель і́ночеськую на мі́сті, чу́дним о́бразом тебі́ от Го́спода указанном, основа́л єси́, в не́йже воспіва́шеся богокра́сная піснь: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во всем ми́рі сла́ва оби́телі твоєя́, преподо́бне о́тче, іді́же обріто́ша душе́вноє успокоє́ніє не то́кмо живу́щії в ней, но і всі і́щущії спасе́нія: ю́ния і ста́рці, бога́тії і ни́щії, немощни́я і убо́гія. Ми же, помина́я попече́нія твоя́ о спасе́нії всіх к тебі́ притека́ющих, ублажа́єм тя, глаго́люще:","Ра́дуйся, і́ноков му́дрий руководи́телю.","Ра́дуйся, в по́двизі су́щих предста́телю.","Ра́дуйся, гла́дних ще́дрий пита́телю.","Ра́дуйся, немощни́х безме́здний ціли́телю.","Ра́дуйся, усе́рдний пред Бо́гом хода́таю.","Ра́дуйся, те́плий о нас моли́твенниче.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 7","ps":["Хотя́й, да всі іспові́дують ві́ру і́стинную, во Святи́й Град Ієрусали́м стопи́ твоя́ направи́л єси́, преподо́бне, іді́же єрети́чеськая мудрова́нія посрами́в, ві́рних научи́л єси́ Трийпоста́сному Бо́гу воспіва́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вний воі́стину защи́тник Правосла́вния ві́ри яви́лся єси́, богому́дре Феодо́сіє, лжеученія єрети́чеськая вся́чеськи облича́я і іспові́дати і́стинную ві́ру всіх призива́я. Сего́ ра́ди от імпера́тора Анаста́сія заточе́ніє темни́чноє і у́зи претерпі́л єси́, ві́рнії же, ви́дяще такову́ю ре́вность твою́, воспі́ша ті такова́я:","Ра́дуйся, Пресвяти́я Тро́йці і́стинний служи́телю.","Ра́дуйся, во́лі Бо́жієй усе́рдний ісполни́телю.","Ра́дуйся, Правосла́вния ві́ри іспові́дниче.","Ра́дуйся, і́стини Христо́ви пропові́дниче.","Ра́дуйся, єрети́чеськая уче́нія разоря́яй.","Ра́дуйся, христия́н правосла́вних во ві́рі утвержда́яй.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 8","ps":["Стра́нноє і пресла́вноє зна́меніє благоволе́нія Бо́жия ви́диться на тебі́, о́тче Феодо́сіє, да́нною бо тебе́ благода́тію с ві́рою прося́щих от вся́ких напа́стей охраня́єши, от скорбе́й свобожда́єши і вся́ко проше́ніє во бла́го ісполня́єши, науча́я ди́вному в чудесі́х Свої́х Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Всему́ ми́рові моли́твенник ізря́ден і чудотво́рець яви́лся єси́, богоблаже́нне Феодо́сіє, і весь в Бо́зі бив, вся за́повіді Христо́ви ві́рно храни́ти ученики́ твоя́ наставля́л єси́. Ті́мже, я́ко возше́дий на висоту́ соверше́нства духо́внаго, наставля́й і нас на путь спасе́нія, вопію́щих ті сицева́я:","Ра́дуйся, житія́ вели́ких подви́жников приє́мниче.","Ра́дуйся, ві́чния блаже́нния жи́зні наслі́дниче.","Ра́дуйся, ли́ка і́ночеськаго предстоя́телю богому́дрий.","Ра́дуйся, пи́щі небе́сния приобщи́вийся.","Ра́дуйся, бра́тії твоєя́ оте́ць чадолюби́вий.","Ра́дуйся, кри́не пусти́нний, свя́тостію благоуха́яй.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ а́нгельськоє удиви́л єси́ висото́ю по́двигов твої́х, преподо́бне о́тче, невеще́ственноє житіє́ на землі́ явля́я, сего́ ра́ди Небе́сним Си́лам сопричтен, Престо́лу Царя́ Сла́ви ни́ні предстої́ши, со А́нгельськими ли́ки воспіва́я Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Віти́йствующий язи́к не мо́жеть досто́йно восхвали́ти тя, о́тче Феодо́сіє, мно́гія бо пресла́вния по́двиги в житії́ твоє́м соверши́л єси́. Ми же к тебі́ любо́вію подвизаємії, во смире́нії се́рдця дерза́єм воспі́ти тебі́ такова́я:","Ра́дуйся, я́ко Го́сподеві все́ю душе́ю і все́ю крі́постію твоє́ю послужи́л єси́.","Ра́дуйся, я́ко сего́ ра́ди многообра́зних даро́в от Него́ сподо́бился єси́.","Ра́дуйся, Правосла́вния ві́ри світи́ло і утвержде́ніє.","Ра́дуйся, оби́телі твоєя́ покро́ве і защище́ніє.","Ра́дуйся, в біда́х і обстоя́ніїх помо́щниче ско́рий.","Ра́дуйся, предста́телю о нас пред Го́сподем непости́дний.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мно́жество люде́й твої́м попече́нієм, Преблаги́й Госпо́дь ізбра́ тя досто́йна наста́вника, преблаже́нне о́тче Феодо́сіє: тобо́ю бо мно́зі на путь спасе́нія наста́влени би́ша і моли́твами твої́ми Ца́рствіє Небе́сноє наслі́доваша, іді́же благода́рно воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда і огра́да несокруши́ма оби́телі твоєя́ суть неусипния твоя́ к Бо́гу моли́тви, о́тче Феодо́сіє. Ті́мже живу́щії в ней, тобо́ю от бід ізбавля́ємі, благода́рно возно́сять к тебі́ гла́си своя́, взива́юще си́це:","Ра́дуйся, послі́дователю Христо́в благопослушли́в.","Ра́дуйся, Влади́ки своєго́ ра́бе благи́й і ві́рний.","Ра́дуйся, трудолюбнейший вертогра́да Христо́ва ді́лателю.","Ра́дуйся, тщали́війший за́повідей Христо́вих ісполни́телю.","Ра́дуйся, і по отше́ствії оби́тель твою́ соблюда́яй.","Ра́дуйся, молящимся в ней благопотре́бная подава́яй.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прийми́ от нас, преподо́бне о́тче, внемли́ моле́ніям на́шим, защити́ нас от вся́каго зла, сохрани́ оби́тель твою́, да бу́деть ві́рним во утіше́ніє і прибі́жище, іді́же непреста́нно возно́ситься піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник, от І́стиннаго Сві́та озаря́ємий, су́щим на землі́ явля́єшися, преподо́бне о́тче Феодо́сіє, се́рдця ві́рних просвіща́я і к ра́зуму Боже́ственному вся наставля́я, со умиле́нієм взиваюших си́це:","Ра́дуйся, наста́вниче ко спасе́нію прему́дрий.","Ра́дуйся, в по́двизіх неутоми́мий.","Ра́дуйся, А́нгелов і всіх святи́х собесі́дниче.","Ра́дуйся, о всем ми́рі усе́рдний моли́твенниче.","Ра́дуйся, тезоімени́тия тебі́ оби́телі стра́же неуси́пний.","Ра́дуйся, в напа́стіх і ско́рбіх помо́щниче ско́рий.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ нам, святи́й уго́дниче Бо́жий, да при́сно покрива́єть нас от враго́во ви́димих і неви́димих, да научи́ть ни подража́ти тебі́ в преподо́бії і пра́вді, да напра́вить се́рдця на́ша к смире́нію, покая́нію і неослабному ісполне́нію за́повідей Христо́вих, да ку́пно с тобо́ю сподо́бимся узрі́ти сла́ву Вели́каго Бо́га і ві́чно пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ богоуго́дноє житіє́, восхваля́єм ми́рную кончи́ну твою́, о́тче Феодо́сіє, і мо́лим ті ся: не забу́ди нас, грі́шних і недосто́йних, бу́ди нам во всем ко бла́гу ско́рий помо́щник, со умиле́нієм зовущим ті такова́я:","Ра́дуйся, те́плий хода́таю о всіх і́м'я твоє́ призива́ющих.","Ра́дуйся, огражде́ніє і упова́ніє тя почита́ющих.","Ра́дуйся, стада́ Христо́ва до́брий наста́вниче.","Ра́дуйся, оби́димих і обездо́ленних засту́пниче.","Ра́дуйся, правосла́вних христия́н похвало́.","Ра́дуйся, мона́шествующих сла́во.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 13","ps":["О преди́вний чудотво́рче і вели́кий уго́дниче Христо́в, преподо́бне о́тче Феодо́сіє, предстоя́й ни́ні Престо́лу Пресвяти́я Тро́йці, прийми́ от нас, грі́шних, приноси́мия ті хвале́бния пі́нія, і моли́твами твої́ми іспроси́ нам у Го́спода оставле́ніє гріхо́в, ізбавле́ніє от бід вре́менних і спасе́ніє от мук ві́чних, да с тобо́ю ви́ну воспіва́єм Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський о́браз житія́ от ю́ности возлюби́вий, я́ко безпло́тен во пло́ті пожи́л єси́, преподо́бне Феодо́сіє, вся вре́менная і земна́я во уме́ти вміня́я. Сего́ ра́ди, я́ко а́нгела земна́го і челові́ка небе́снаго і́стинно тя почита́юще, со умиле́нієм вопіє́м ті:","Ра́дуйся, Каппадокі́ї свято́є прозябе́ніє.","Ра́дуйся, благочести́вих роди́телей благослове́нний пло́де.","Ра́дуйся, во ві́рі і благоче́стії воспита́нний.","Ра́дуйся, благода́тію Бо́жиєю приосіне́нний.","Ра́дуйся, Єва́нгелія Христо́ва усе́рдний послі́дователю.","Ра́дуйся, за́повідей Госпо́дніх ві́рний ісполни́телю.","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, і́ночествующих му́дрий наста́вниче і покрови́телю, преблаже́нне о́тче Феодо́сіє, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, да с ра́достію зове́м ті:","Ра́дуйся, преподо́бне о́тче Феодо́сіє, общежи́тельнаго мона́шеськаго житія́ устрої́телю."]},{"h":"Молитва","ps":["О преподо́бне і богоно́сне о́тче наш Феодо́сіє! Ти, порабо́тати Го́сподеві жела́я, нелі́ностно в труді́х, во бді́ніїх, в моли́твах і пості́х подвиза́лся єси́, і бил єси́ наста́вник монашествующим, всім же лю́дем - оте́ць чадолюби́вий. Ни́ні у́бо, по отше́ствії твоє́м от земни́х, Небе́сному Царю́ предстоя́, моли́ бла́гость Єго́, є́же уще́дрити мі́сто селе́нія твоєго́, святу́ю оби́тель твою́, іді́же ду́хом любве́ твоєя́ неотсту́пно пребива́єши, і всім с ві́рою к тебі́ припадающим во блага́я проше́нія їх іспо́лнити. Іспроси́ у Ми́лостиваго Го́спода на́шего, да низпосле́ть нам оби́ліє благ земни́х, па́че же я́же на по́льзу душ на́ших да да́руєть нам, і сконча́ти житіє́ сіє́ привре́менноє в покая́нії да сподо́бит, в день же Су́дний десна́го предстоя́нія і наслажде́нія во Ца́рствії Своє́м да удосто́їть нас во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Слез твої́х тече́ньми пусти́ні безпло́дноє возді́лал єси́, / і і́же із глубини́ воздиха́ньми во сто трудо́в уплодоноси́л єси́, / і бил єси́ світи́льник вселе́нній, сія́я чудеси́, Феодо́сіє, о́тче наш, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Насажде́н во дво́ріх Го́спода твоєго́, / преподо́бними твої́ми доброді́тельми красно́ процві́л єси́, / і умно́жил єси́ ча́да твоя́ в пусти́ні, / слез твої́х ту́чами напая́ємая, / стадонача́льниче Бо́жий Боже́ственних дворо́в. Ті́мже зове́м: // ра́дуйся, о́тче Феодо́сіє."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Феодо́сіє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Саві, архієпископу Сербському","e":"Akathist to St Sava, Archbishop of Serbia","secs":[{"h":"Кондак 1","ps":["Ізбра́нний от Царя́ сил Го́спода Ісу́са Христа́ і призва́нний благода́тію от кралевськаго ро́да во і́ночество і архієре́йство, первосвяти́телю Се́рбськия Це́ркве, богоно́сне о́тче Са́вво, удовли́ нас восхваля́ти тя с любо́вію, я́ко богодарова́ннаго па́стиря і учи́теля на́шего; ти же, імі́я дерзнове́ніє ко Го́споду, вку́пі с отце́м і бра́том твої́ма по пло́ті, мироточивим Симео́ном і преподо́бним Си́моном, первовенчанним кралем, моли́ся ви́ну о спасе́нії всего́ достоя́нія своєго́, правосла́внаго наро́да се́рбськаго, і о нас грі́шних, ізбавля́я от вся́ких зол, бід і скорбе́й, вопію́щия ті:","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгельськую чистоту́ от ю́ности возлюби́в, Са́вво блаже́нне, во мла́дости вели́кий подви́жник благоче́стія показа́лся єси́, во є́же всім диви́тися благонравію і благоче́стію душі́ твоєя́, зане́ я́ко ю́ноша сий і кралевич рожде́нієм, посто́м, бді́нієм і моли́твами, плоть твою́ обузда́л єси́. Сего́ ра́ди і сли́шиши от нас похва́льния пі́сні такови́я:","Ра́дуйся, отця́ благочести́ваго і ма́тере благонра́вния, си́не Бо́гом возлю́бленне;","Ра́дуйся, єди́наго Бо́га всім се́рдцем твої́м возлюби́вий;","Ра́дуйся, рожде́нієм твої́м роди́теля уті́шивий і непло́діє є́ю разріши́вий;","Ра́дуйся, плод благослове́нний, мно́гими моли́твами іспрошенний;","Ра́дуйся, кралевськаго ро́да Немани о́трасль святопрозябшая;","Ра́дуйся, Се́рбськия землі́ духо́вная красото́;","Ра́дуйся, роди́телю твоє́ю в ста́рости утіше́ніє і ра́дованіє;","Ра́дуйся, і́ма па́че други́х чад, зіло́ люби́мий;","Ра́дуйся, плотоугодіє єще́ во мла́дости отвергнувий;","Ра́дуйся, о благи́х небе́сних па́че не́же о земни́х ви́ну помишля́вий;","Ра́дуйся, чистоти́ душе́вния і тіле́сния до́брий рачи́телю.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дів суєту́ і непостоя́нство сла́ви земни́я, Са́вво богому́дре, устреми́лся єси́ ду́хом твої́м в го́рняя ко Го́споду, І́же зря твоє́ жела́ніє боже́ственноє, посла́ к тебі́ і́нока преподо́бнаго із святи́я гори́ Афо́нськия, єго́же поуче́нієм наставля́ємий, оста́вил єси́ роди́теля твоя́ і оте́чество твоє́, в жре́бій же земни́й Пресвяти́я Богоро́диці на святу́ю го́ру Афо́нськую прише́л єси́, і та́мо во оби́телі Украї́нській водвори́лся єси́, зови́й немо́лчно с работающими Го́сподеві, а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́вше отше́ствіє твоє́, роди́теля твоя́ пла́кастеся го́рці, скорб'я́ще о твоє́м лише́нії, Са́вво преподо́бне, та́же поми́слиша і а́біє посла́ша іска́ти тя да́же до Афо́на ві́рния слуги́ своя́, я́ко да убедять тя к ни́ма возврати́тися. Ти же, свя́те, прише́ствіє по́сланних слуг уві́дів, му́дре с ни́ми бесі́довал єси́, та́же от них удали́вся, на пирг висо́кий возше́л єси́, і та́мо постриже́ніє і́ночеськоє восприя́вий, кралевськую ри́зу твою́, вку́пі с власи́ глави́ твоєя́, в постриже́нії отятими, по́сланним тім с пирга пове́ргл єси́, запові́дав їм рещи́ роди́телема твої́ма, я́ко син є́ю Растко, уже́ і́нок Са́вва єсть. Такову́ю ре́вность твою́ о спасе́нії помина́юще, зове́м ті си́це:","Ра́дуйся, владенія земна́го сла́ву презрі́вий;","Ра́дуйся, роди́теля твоя́ і оте́чество твоє́ Христа́ ра́ди оста́вивий;","Ра́дуйся, на святу́ю Афо́нськую го́ру рабо́тати Го́сподеві прише́дий;","Ра́дуйся, во оби́телі Украї́нській та́мо водворивийся;","Ра́дуйся, сея́ оби́телі постриженець би́вий;","Ра́дуйся, по́двиги твої́ми о́ную просла́вивий;","Ра́дуйся, я́ко в ней досе́лі і́м'я твоє́ моли́твенно ублажа́ється;","Ра́дуйся, я́ко оби́тель сія́ тобо́ю сві́тло красу́ється;","Ра́дуйся, по́двиги поста́ і моли́тви отце́в Афо́нських удиви́вий;","Ра́дуйся, во єди́ной власянице боси́ма нога́ма оби́телі Афо́нськия обошедий;","Ра́дуйся, тала́нт, вруче́нний ті, умно́живий;","Ра́дуйся, в послуша́ніє ста́рцю богому́дрому во оби́телі Ватопедстей себі́ преда́вий;","Ра́дуйся, во смире́нії і терпі́нії зіло́ преуспі́вий.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою Всеви́шняго укріпля́ємий, свя́тче Бо́жий, по́двиги вели́кия во і́ночестві соверша́л єси́, во оби́телі Ватопедстей на Афо́ні, посто́м, бді́нієм і вся́ким ізнуренієм умерщвля́я плоть твою́, мраз і зной терпі́л єси́, а́ки безпло́тний, і бос ходя́й по о́строму ка́мені неуязвим пребива́л єси́, покоря́я плоть ду́ху, любо́вію ко Го́споду ви́ну пламеневий, во є́же пі́ти тебі́ немо́лчную Єму́ піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я попече́ніє о спасе́нії душе́внім родителію твоє́ю, о́тче Са́вво, ви́ну моли́лся єси́ о сем Бо́гу. Благи́й же Человіколю́бець, творя́й во́лю боя́щихся Єго́, внуши́ роди́телема твої́ма писа́нієм твої́м к ни́ма зіло́ умиле́нним, владеніє земно́є оста́вити і постриже́ніє і́ночеськоє восприя́ти. Сего́ ра́ди оте́ць твой, преподо́бний Симео́н, із Се́рбії на Афо́н при́йде і вку́пі с тобо́ю во Ватопеді водвори́ся, с ним же тя ни́ні ублажа́єм і зове́м:","Ра́дуйся, спасе́нія душе́внаго родительма твої́ма усе́рдний желателю;","Ра́дуйся, ко оставле́нію сла́ви земни́я, і́ма богому́дрий советодателю і увещателю;","Ра́дуйся, прише́ствієм к тебі́ на Афо́н отця́ твоєго́ зіло́ уті́шенний;","Ра́дуйся, спо́стник і сомолитвенник єму́ би́вий;","Ра́дуйся, по́двиги і́ночеськия нести́ єму́ помогавий;","Ра́дуйся, не́мощі єго́ старчеськия терпіли́во носи́вий;","Ра́дуйся, в неду́зіх єму́ любвеобильно послужи́вий;","Ра́дуйся, тяготу́ скорбе́й і лише́ній пусти́нних єму́ облегчивий;","Ра́дуйся, по́двиги твої́ми по́двиги о́тчія восполнявий;","Ра́дуйся, уго́дника Бо́жия і́стиннаго єго́ соверши́вий;","Ра́дуйся, єго́ благослове́нієм святи́м осіне́нний;","Ра́дуйся, вку́пі с ним от ві́рних люде́й моли́твенно почита́ємий.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рею мо́ря жите́йськаго обурева́ємим, ти́хоє приста́нище на Афо́ні построіти потща́лся єси́, о́тче Са́вво, і́ночеськую се́рбському ро́ду оби́тель, Хилендар іменуєму, ю́же Пресвяті́й Богоро́дице посвяти́л єси́, хра́ми Бо́жиїми і зданьми мно́гими сію́ украси́в, імі́нієм же дово́льним ю снабдив, і грамматами царе́й утверди́в, в не́йже і сам с роди́телем твої́м, преподо́бним Симео́ном, всели́лся єси́ жи́ти. Сего́ ра́ди оби́тель сія́ ви о́ба ктиторома свої́ма почита́єть, і па́м'яті ва́ші торжеству́ющи, моле́бно возсила́єть хвале́бную піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав зва́ніє Бо́жиє преподо́бний Симео́н, к ві́чним оби́телем єго́ призива́ющеє, стяжа́ тя, Са́вво богоно́сне, моли́твеннаго помо́щника при ісхо́ді своє́м, і на ру́ку твоє́ю сино́вню дух свой Го́сподеві предаде́, ті́ло же єго́ свято́є ти с подоба́ющею че́стію во гро́бі мраморне в собо́рнім хра́мі Хилендарськия оби́телі положи́л єси́, і моли́твами твої́ми моще́м отця́ твоєго́ мироточенія благода́ть от Бо́га іспроси́л єси́, сим подвиза́я ві́рния лю́ди зва́ти к тебі́:","Ра́дуйся, всеси́льний і богоприя́тний к Бо́гу моли́твенниче;","Ра́дуйся, равноа́нгельний челові́че;","Ра́дуйся, я́ко святи́я мо́щі і са́мий гроб отця́ твоєго́, по моли́тві твоє́й к Бо́гу, ми́ро благоуха́нноє і целебноє істочи́ша;","Ра́дуйся, я́ко сим зіло́ обра́дованний Бо́га немо́лчно славосло́вил єси́;","Ра́дуйся, я́ко оте́ць твой преподо́бний, по сме́рті послуша́ніє ди́вноє тебі́ показа́;","Ра́дуйся, я́ко по твоєму́ проше́нію, ізсякшеє от гро́ба ми́ро, па́ки істочи́ся;","Ра́дуйся, во сла́ві святи́х отця́ твоєго́ та́їнственно созерца́вий;","Ра́дуйся, во сві́тлом виді́нії обітова́нія благи́я от него́ усли́шавий;","Ра́дуйся, я́ко по за́повіді отця́ твоєго́ мо́щі єго́ от Афо́на в Се́рбію тобо́ю принесе́ни би́ша;","Ра́дуйся, я́ко та́ко в оби́телі Студеницькой со сла́вою мно́гою тобо́ю положе́ні би́ша;","Ра́дуйся, прославле́нія отця́ твоєго́ в ли́ці святи́х вино́вниче;","Ра́дуйся, святи́я па́м'яті єго́ усе́рдний почита́телю.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 5","ps":["Богосія́нноє світи́ло бив, Са́вво богому́дре, во́лею Пастиренача́льника Ісу́са, на сві́щниці Се́рбськия Це́ркве поста́влен бил єси́, і от патріа́рха Вселе́нськаго во архієпи́скопа се́рбському наро́ду от землі́ єго́ яви́лся єси́, єго́же тща́тельні везді́ і всегда́ поуча́л єси́ во ві́рі святі́й правосла́вній тве́рдо і неукло́нно пребива́ти, богоуго́дно же возноси́ти хвале́бную піснь Пресвяті́й Тро́йце: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів себі́ разлуча́єма с любимою тобо́ю афо́нською пусти́нею, о́тче Са́вво, скорбі́л єси́ ду́хом твої́м, оба́че Пресвята́я Богоро́диця яви́ся ті в сві́тлом виді́нії, і обетованьми по́мощі от Нея́ і заступле́нія, скорб'я́щую ду́шу уті́ши і укріпи́. Тебі́ си́це обрадовану виді́нієм і бесі́дою Цари́ці Небе́сния, і ми, земні́ї, ра́достно вопіє́м:","Ра́дуйся, ізбра́нний сосу́де Ду́ха Свята́го;","Ра́дуйся, при хиротонії твоє́й сві́том небе́сним сви́ше осія́нний;","Ра́дуйся, таї́нниче Пресвяти́я Тро́йці;","Ра́дуйся, собесі́дниче Пресвяти́я Богоро́диці;","Ра́дуйся, сли́шавий от уст Єя́ ми́лостивия глаго́ли;","Ра́дуйся, приє́мий от Нея́ обітова́ніє по́мощі і заступле́нія;","Ра́дуйся, равноапостолний Се́рбськия страни́ первопресто́льниче;","Ра́дуйся, учредителю богоблагословенния ієрархії, поставленієм єпи́скопов в Се́рбстій держа́ві;","Ра́дуйся, кра́снії но́зі твої́ напра́вивий к распространенію про́повіді Єва́нгельськия;","Ра́дуйся, Се́рбію сві́том Христо́вим соверше́нно просвіти́вий;","Ра́дуйся, мно́гі хра́ми Бо́жії і оби́телі і́ночеськия в ней воздви́гнувий;","Ра́дуйся, щедродательний ми́лостині пода́телю;","Ра́дуйся, благосе́рдний ни́щих пита́телю.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник Правосла́вния ві́ри яви́лся єси́ в Се́рбії, Са́вво свяще́нне, єгда́ в собо́рнім хра́мі твоє́м Жичстем симво́л Правосла́вния ві́ри громогласно іспові́дал єси́, і сей іспові́дати па́ству твою́ научи́л єси́, да всі єдиномисленни пребу́дуть с тобо́ю, і возмо́гуть єди́німи усти́ і єди́нім се́рдцем пі́ти вку́пі с тобо́ю піснь хвали́ і благодаре́нія Трийпоста́сному Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, святи́телю Христо́в, я́ко звізда́ пресві́тлая в оте́честві твоє́м земні́м, і лю́ди твоя́ в Правосла́вній ві́рі і благоче́стії утвержда́л єси́ златослове́сними поуче́нії твої́ми, є́ресі же і раско́ли іскореня́л єси́ мече́м сло́ва Бо́жия. Сего́ ра́ди тя, я́ко а́нгела Бо́жия лю́ди сербстії почита́ху, зову́ще і велегла́сно глаго́люще:","Ра́дуйся, архієре́ю, власть в'яза́ти і ріши́ти досто́йно восприя́вий;","Ра́дуйся, ієра́рше, во всеору́жіє Христо́во облече́нний;","Ра́дуйся, па́стирю до́брий, гото́вий ду́шу свою́ положи́ти за богода́нния ті лю́ди і па́ству твою́;","Ра́дуйся, усе́рдний ді́лателю виногра́да Госпо́дня;","Ра́дуйся, світи́льниче, сія́ющий і просвіща́ющий се́рдця челові́чеськая;","Ра́дуйся, лучу́ пресві́тлий Со́лнця пра́вди Христа́;","Ра́дуйся, чудотворе́нія да́ром от Го́спода просла́вленний;","Ра́дуйся, ісціле́нія мно́гая рука́ма твої́ма соверши́вий;","Ра́дуйся, разсла́бленнаго моли́твою твоє́ю здра́ва сотвори́вий;","Ра́дуйся, вражду́ єдинокро́вних благода́тно умиротвори́вий;","Ра́дуйся, в стан неприя́зненних єди́н ходи́вий;","Ра́дуйся, словеси́ твої́ми враждовавших смири́вий;","Ра́дуйся, уме́ршаго бра́та краля́ Стефа́на воскреси́вий і жела́ніє єго́ іспо́лнь, в і́ночество облеки́й єго́, нарекши Си́моном.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 7","ps":["Хоті́ніє єди́но імі́л єси́, свя́тче Бо́жий, є́же Бо́гу благоугожда́ти і спасе́нію душе́вному бли́жніх твої́х служи́ти. Сего́ ра́ди не дал єси́ сна очи́ма твої́ма, ні ві́ждома дрема́нія, нелі́ностно подвиза́яся во бла́го святи́я Це́ркве Се́рбськия і во спасе́ніє і по́льзу вві́ренних ті от Бо́га благові́рних люде́й, і воі́стину соді́лался єси́ столп Правосла́вія і сохране́ніє наро́да се́рбськаго непоколеби́моє, і́же тя неле́стно хва́лить і зове́ть укріпи́вшему тя Це́ркве Зижди́телю Христу́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя Никола́я Мирлікі́йськаго і Златоу́ста Царегра́дськаго стяжа́ земля́ Се́рбськая: чудеси́ бо твої́ми пе́рвому подо́бен бил єси́, златослове́сними же уче́нії второ́му подража́л єси́, святи́телю о́тче наш Са́вво, воі́стину досто́йний благохваленій такови́х:","Ра́дуйся, немо́лчний пропові́дниче Єва́нгелія Христо́ва;","Ра́дуйся, ві́рний послі́дователю преда́ній апо́стольських;","Ра́дуйся, святи́х богоно́сних оте́ць нра́ви себі́ усво́ївий;","Ра́дуйся, те́плий моли́твенниче о душа́х на́ших;","Ра́дуйся, неуси́пноє моле́ніє в типикарниці карейстей на Афо́ні соверша́ти повелі́вий;","Ра́дуйся, благовре́менно і безвре́менно па́ству твою́ благоче́стію поучавий;","Ра́дуйся, мечу́, є́ресі і раско́ли посіка́яй;","Ра́дуйся, гро́ме, соблазнителей устраша́яй;","Ра́дуйся, оби́димих засту́пниче;","Ра́дуйся, вдов і сиро́т благоді́телю;","Ра́дуйся, скорб'я́щих уті́шителю;","Ра́дуйся, ка́ющихся с Бо́гом примири́телю;","Ра́дуйся, отроко́в богому́дрий наказа́телю;","Ра́дуйся, младе́нцев любвеобильний покрови́телю і богому́дрий наста́вниче.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нник і пришле́ць восхоті́л єси́, Христа́ ра́ди би́ти, святи́телю Са́вво, подража́яй Спа́су душ на́ших, не імевшему гді главу́ приклонити, Єго́же ра́ди ти оте́чество твоє́ оста́вил єси́, і на поклоне́ніє святи́м мі́стом в разли́чния страни́ поте́кл єси́, с ві́рою і любо́вію святи́ням в них покланя́яся, ми́лостиню же мно́гу це́рквам, оби́телем і ни́щим раздава́я і воспіва́я при́сно Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі би́вий, святи́телю преподо́бне, о Бо́зі стопі́ твої́ странничестеї направи́л єси́ і во святі́м гра́де Ієрусали́ме, мі́ста свята́я, житіє́м і страда́нієм Христа́ Спаси́теля ознаменованная, моли́твенно обходил єси́, сим покланя́яся і сле́зи те́плия от о́чію твоє́ю ізлива́я, я́ко же́ртву любве́ твоєя́ к пострада́вшему нас ра́ди Го́споду, І́же внуша́єть нам вопи́ти тебі́:","Ра́дуйся, му́дрий стра́нниче, іски́й оте́чествія небе́снаго;","Ра́дуйся, Христо́в ізбра́нниче, презрі́вий вся бла́га земна́я;","Ра́дуйся, свята́го гра́да Ієрусали́ма до́льняго благогові́йний покло́нниче;","Ра́дуйся, сві́тлаго гра́да Ієрусали́ма го́рняго усе́рдний і му́дрий іска́телю;","Ра́дуйся, Царгра́д, Палести́ну, Єги́пет, Сина́й і Афо́н посіти́вий;","Ра́дуйся, Ливи́ю, Фиваїду, Антіохі́ю, Сирі́ю і Арме́нію обходивий;","Ра́дуйся, по мо́рю і су́ші многотру́дно путеше́ствовавий;","Ра́дуйся, мно́гія вели́кия святи́ні в путі́ твоє́м собра́вий;","Ра́дуйся, от па́стирей Правосла́вния Це́ркве везді́ с любо́вію і че́стію приє́млемий;","Ра́дуйся, от ни́щих і убо́гих за благотворе́нія твоя́ благословляємий;","Ра́дуйся, плі́нников свободи́телю;","Ра́дуйся, пустинножи́телей уті́шителю.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 9","ps":["Всі і́ноці вели́кия Ла́ври преподо́бнаго Са́вви Освяще́ннаго с ра́достію сріто́ша тя, богому́дре Са́вво, єгда́ к ним на поклоне́ніє прише́л єси́, і позна́ша тя ди́внаго прише́льця, от літ дре́вніх їм обітова́ннаго. Ті́мже тебі́, я́ко досто́йному, жезл преподо́бнаго Са́вви Освяще́ннаго і дві іко́ні Богородични чудотворнеї, Троєручиці і Млекопитательници іменуємеї, на благослове́ніє дарова́ша ті, пою́ще гла́си преподо́бними Творцю́ вся́чеських Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ветийство челові́чеськоє не довлі́єть к прославле́нію мно́гих чуде́с твої́х, святи́телю ієра́рше приснопа́м'ятне: мо́ре бо волну́ющеєся моли́твою твоє́ю укроти́л єси́, і ри́бу ди́вно із глубини́ морськи́я в корабли́ прия́л єси́, неду́жния возложе́нієм ру́ку твоє́ю ісціля́л єси́ і ме́ртвия пресла́вно воскрешал єси́, я́ко ві́рний учени́ко Христа́ Бо́га. Ті́мже тебе́ вопіє́м хвале́бно, ублажа́я тя си́це:","Ра́дуйся, обітова́ній Єва́нгельських ісполне́ніє приє́мий;","Ра́дуйся, смире́нієм висо́кая стяжа́вий;","Ра́дуйся, врачу́ безме́здний, ісціля́яй неду́ги душе́вния і тіле́сния;","Ра́дуйся, ціле́бниче благода́тний в болі́зніх с ві́рою к тебі́ притекающим;","Ра́дуйся, я́ко ру́ці твої́ честні́ї ору́дія ціле́б яви́стася;","Ра́дуйся, я́ко се́ю возложе́нієм моли́твенним, боля́щим здра́віє подава́л єси́;","Ра́дуйся, я́ко в чужди́х страна́х пребива́я, і́м'я Христо́во чудеси́ твої́ми прославля́л єси́;","Ра́дуйся, я́ко от гра́да в град преходя́, ві́рния во благоче́стії утвержда́л єси́;","Ра́дуйся, я́ко от восто́ка і до за́пада хва́льно бисть і́м'я твоє́;","Ра́дуйся, я́ко бли́жніх і да́льних усе́рдно ко Христу́ приводи́л єси́;","Ра́дуйся, вселе́нную я́ко со́лнце пресві́тлоє, обтеки́й;","Ра́дуйся, я́ко луна́ по́лная богоуго́дноє тече́ніє соверши́вий.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 10","ps":["Спасе́нія наде́жду несумні́нную імі́я, святи́телю уго́дниче Бо́жий, во град Терно́в прише́л єси́ і зді коне́ць стра́нствія земна́го соверши́л єси́, почи́в о Го́споді кончи́ною пра́ведною і свято́ю, є́ю же мног плач землі́ Се́рбстій сотвори́л єси́. Оба́че ві́руєм, о́тче і архієре́ю наш, я́ко а́ще і вні оте́чества, по смотре́нію Госпо́дню почи́л єси́, неразлуче́н же с ним ду́хом твої́м пребива́єши і ви́ну мо́лишися Бо́гу о воспіва́ющих Єму́ піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ ві́рний раб і служи́тель бил єси́, богоно́сне о́тче наш Са́вво, і а́ще почи́л єси́ о Го́споді сном сме́рти, оба́че чудотвори́ти не престає́ши і по сме́рті: свяще́нная і всечестна́я ра́ка твоя́ враче́бниця яви́ся неду́гом челові́чеським, і са́мая персть от гро́ба твоєго́ ціле́бна бисть, я́ко всім зва́ти тебі́:","Ра́дуйся, первопресто́льниче свя́те Се́рбськия страни́, со святи́ми почива́яй;","Ра́дуйся, уго́дниче Христо́в, і по сме́рті пресла́вно чудоді́йствуяй;","Ра́дуйся, град Терно́в преподо́бною твоє́ю кончи́ною освяти́вий;","Ра́дуйся, Болгарськую страну́ чудеси́ твої́ми благода́тно озари́вий;","Ра́дуйся, по жела́нію твоєму́ в по́двизі стра́нствія жизнь сконча́вий;","Ра́дуйся, вні оте́чества твоєго́ сном сме́ртним опочивий;","Ра́дуйся, я́ко смерть твоя́ честна́ пред Го́сподем;","Ра́дуйся, я́ко успе́ніє твоє́ торжеству́єть свята́я Правосла́вная Це́рков;","Ра́дуйся, я́ко архистрати́г Се́рбськия страни́, во́єм єя́ во бра́ніх побораяй;","Ра́дуйся, покро́вом моли́тв твої́х па́ству твою́ при́сно соблюда́яй;","Ра́дуйся, просвіще́нія духо́внаго распространителю і насади́телю;","Ра́дуйся, младе́нцев і отроко́в любвеобильний наста́вниче, училищ же христия́нських покрови́телю і озарителю.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́нієм молебним честву́єм тя і велича́єм, святи́телю, Бо́жий уго́дниче, і ві́рно соверша́єм святу́ю па́м'ять твою́: а́ще бо і в Се́рбії просія́л єси́, вся же Це́рков вселе́нния стяжа́ тя до́бля побо́рника, предста́теля і моли́твенника ко Го́споду. Ті́мже, помина́я житіє́ твоє́ богоуго́дноє і мно́гія по́двиги твоя́ і чудеса́, прославля́єм просла́вльшаго тя Го́спода Ісу́са, і смиренному́дренно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлостію чуде́с сія́я, любо́в твою́ к Се́рбії показа́л єси́, равноапо́стольне святи́телю Са́вво, єгда́ благоволи́л єси́ принесе́нним би́ти святи́м моще́м твої́м в оте́чество твоє́ земно́є; ти бо отечестволю́бець бив при жи́зні, і по успе́нії такови́м яви́лся єси́, і к люб'ящей тя па́стві твоє́й возврати́тися моща́ми твої́ми восхоті́л єси́, да возвесели́ши чад твої́х, тебі́ вопію́щих:","Ра́дуйся, началопа́стирю Се́рбський, па́ству твою́ моли́твенно назираяй;","Ра́дуйся, благи́й предста́телю с ві́рою тя призива́ющих;","Ра́дуйся, я́ко моще́м твої́м святи́м в Се́рбію принесе́нним би́ти восхоті́л єси́;","Ра́дуйся, я́ко во́лю твою́ о сем царю́ Болга́рському Асену во виді́нії возвісти́л єси́;","Ра́дуйся, со сла́вою і че́стію із Тернова в Се́рбію принесе́нний;","Ра́дуйся, в собо́рнім хра́мі Милешеви, я́ко твоєя́ кафедри, с любо́вію прия́тий і че́стно положе́нний;","Ра́дуйся, братаничем твої́м, Сербським кралем Владиславом, благогові́йно почита́ємий;","Ра́дуйся, преє́мником твої́м, святи́телем Арсе́нієм, моли́твенно ублажа́ємий;","Ра́дуйся, всі́ми людьми́ сербськими ра́достно прия́тий;","Ра́дуйся, прише́ствієм твої́м печа́ль па́стви твоєя́ утоли́вий;","Ра́дуйся, чудеси́ мно́гими от гро́ба твоєго́ свя́тость твою́ ознаменовавий;","Ра́дуйся, по́ля, гори́ і де́бри ше́ствієм освяти́вий;","Ра́дуйся, богоуго́дним житіє́м, му́дростію і вели́ким тща́нієм Правосла́віє в наро́ді своє́м утверди́вий;","Ра́дуйся, благода́тним заступле́нієм і по отше́ствії твоє́м єго́ сохраня́яй;","Ра́дуйся, а́нгеле житіє́м, проро́че благода́тію Свята́го Ду́ха, апо́столе благовіствова́нієм, му́чениче іспові́данієм.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жия сокро́вище, святи́я і нетлі́нния мо́щі твоя́, Са́вво, о́тче наш, гріх ра́ди на́ших от нечести́вих ага́рян, враго́в христия́нських, огню́ пре́дани би́ша. Оба́че ві́руєм, я́ко ти і ни́ні с на́ми єси́, я́коже і пре́жде, єгда́ благоволи́л єси́ моща́ми твої́ми ви́димо род свой утіша́ти, і моли́твами твої́ми нас сохраня́єши от вся́каго зла. Ті́мже покланя́ющеся мі́сту свято́му, на не́мже мо́щі твоя́ злочестивими огню́ преда́шася, лобиза́єм персть, і́ми освяще́нную, і поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще свято́є і богоуго́дноє житіє́ твоє́ і мно́гая пресла́вная чудотворе́нія твоя́, святи́телю о́тче наш Са́вво, смире́нно про́сим тя: не возгнуша́йся на́ших не довлеющих похва́л, і́миже тя, от усе́рдія на́шего чествова́ти дерза́єм, но приклони́ся ми́лостивно к зовущим ті всеусе́рдно хвале́нія такова́я:","Ра́дуйся, сострада́тельний і любвеобильний Се́рбськия страни́ неуси́пний храни́телю;","Ра́дуйся, я́ко с не́ю вку́пі от злих ага́рян в мощеіх твої́х о́гненноє іскуше́ніє прия́вий;","Ра́дуйся, столпо́м сія́ющим до небе́с над сожигаємими моща́ми твої́ми, свя́тость їх чуде́сне проявивий;","Ра́дуйся, сожегшаго мо́щі твоя́ воєво́ду ага́рянськаго гро́зно наказавий;","Ра́дуйся, і по сожженії моще́й твої́х чудотвори́ти непреставий;","Ра́дуйся, і са́моє мі́сто сожже́нія їх благода́ті прича́стно сотвори́вий;","Ра́дуйся, во виді́ніїх і со́ніїх ві́рния посіща́яй;","Ра́дуйся, бли́жнім і да́льним по́мощ твою́ подава́яй;","Ра́дуйся, Правосла́вния Це́ркве боголі́пноє украше́ніє;","Ра́дуйся, архієре́єв сла́во і похвало́;","Ра́дуйся, в ли́ці преподо́бних сія́ющая звіздо́;","Ра́дуйся, по Бо́зі і Богоро́дице, крі́пкоє на́ше упова́ніє.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 13","ps":["О, пресвяти́й і преди́вний чудотво́рче, святи́телю о́тче наш Са́вво, Се́рбськия страни́ покрови́телю і всіх правосла́вних христия́н предста́телю! Прийми́ ми́лостивно сіє́ ма́лоє моле́ніє на́ше, в похвалу́ тебі́ приноси́моє, і моли́твами твої́ми ко Го́споду, ізба́ви нас от бід вре́менних і ві́чних, і сподо́би нас вку́пі с тобо́ю в Ца́рствії небе́снім пі́ти Бо́гу, Спаси́телю на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельськую чистоту́ от ю́ности возлюби́в, Са́вво блаже́нне, во мла́дости вели́кий подви́жник благоче́стія показа́лся єси́, во є́же всім диви́тися благонравію і благоче́стію душі́ твоєя́, зане́ я́ко ю́ноша сий і кралевич рожде́нієм, посто́м, бді́нієм і моли́твами, плоть твою́ обузда́л єси́. Сего́ ра́ди і сли́шиши от нас похва́льния пі́сні такови́я:","Ра́дуйся, отця́ благочести́ваго і ма́тере благонра́вния, си́не Бо́гом возлю́бленне;","Ра́дуйся, єди́наго Бо́га всім се́рдцем твої́м возлюби́вий;","Ра́дуйся, рожде́нієм твої́м роди́теля уті́шивий і непло́діє є́ю разріши́вий;","Ра́дуйся, плод благослове́нний, мно́гими моли́твами іспрошенний;","Ра́дуйся, кралевськаго ро́да Немани о́трасль святопрозябшая;","Ра́дуйся, Се́рбськия землі́ духо́вная красото́;","Ра́дуйся, роди́телю твоє́ю в ста́рости утіше́ніє і ра́дованіє;","Ра́дуйся, і́ма па́че други́х чад, зіло́ люби́мий;","Ра́дуйся, плотоугодіє єще́ во мла́дости отвергнувий;","Ра́дуйся, о благи́х небе́сних па́че не́же о земни́х ви́ну помишля́вий;","Ра́дуйся, чистоти́ душе́вния і тіле́сния до́брий рачи́телю.","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нний от Царя́ сил Го́спода Ісу́са Христа́ і призва́нний благода́тію от кралевськаго ро́да во і́ночество і архієре́йство, первосвяти́телю Се́рбськия Це́ркве, богоно́сне о́тче Са́вво, удовли́ нас восхваля́ти тя с любо́вію, я́ко богодарова́ннаго па́стиря і учи́теля на́шего; ти же, імі́я дерзнове́ніє ко Го́споду, вку́пі с отце́м і бра́том твої́ма по пло́ті, мироточивим Симео́ном і преподо́бним Си́моном, первовенчанним кралем, моли́ся ви́ну о спасе́нії всего́ достоя́нія своєго́, правосла́внаго наро́да се́рбськаго, і о нас грі́шних, ізбавля́я от вся́ких зол, бід і скорбе́й, вопію́щия ті:","Ра́дуйся, святи́телю Са́вво, первопа́стирю і учи́телю Се́рбський, ди́вний чудотво́рче."]},{"h":"Молитва","ps":["О, свяще́нная главо́, пресла́вний чудотво́рче, святи́телю Христо́в Са́вво, Се́рбськия землі́ первопресто́льниче, храни́телю і просвіти́телю, всіх же христия́н благонаде́жний пред Го́сподем предста́телю! Тебі́ припа́даєм і мо́лимся: даждь нам би́ти прича́стником любве́ твоєя́ к Бо́гу і бли́жнему, є́ю же при жи́зні свята́я душа́ твоя́ преіспо́лнена бисть.","Озари́ нас і́стиною, просвіти́ ум і се́рдце на́ше сві́том Боже́ственнаго уче́нія, научи́ нас тебі́ подража́ти ві́рно, Бо́га і бли́жняго на́шего люби́ти і за́повіді Госпо́дні соверша́ти непогріши́тельно, да бу́дем і ми ча́да твоя́, не по і́мені то́кмо, но всім житіє́м на́шим.","Моли́ся, святи́й архієре́ю, о святі́й Правосла́вній Це́ркві і оте́честві твоє́м земні́м, при́сно тя любо́вію чту́щем. При́зри благоутро́бно на вся́ку ду́шу ві́рних твої́х чти́телей, ми́лості і по́мощі твоєя́ і́щущих, бу́ди всім нам в болі́зніх ціли́тель, в ско́рбіх уті́шитель, в печа́ліх посіти́тель, в біда́х і ну́ждах помо́щник, в час же сме́ртний ми́лостивий покрови́тель і защи́титель, да по́мощію моли́тв твої́х святи́х, сподо́бимся і ми грі́шнії спасе́ніє ві́рноє получи́ти і Ца́рствіє Христо́во унаслі́довати.","Єй, свя́тче Бо́жий, не посрами́ упова́нія на́шего, є́же на тя крі́пко возлага́єм, но яви́ нам твоє́ многомо́щноє заступле́ніє, да сла́вим і поє́м ди́внаго во святи́х Свої́х Бо́га Отця́ і Си́на і Свята́го Ду́ха, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Во святи́теліх вели́коє украше́ніє, богому́дре о́тче Са́вво, мо́лимся раби́ твої́ і припа́дающе, вопіє́м ті: не оста́ви свої́х чад, о́тче, но бу́ди всегда́ с на́ми, я́коже обіща́лся єси́, да і ми по до́лгу воспоє́м тя, ублажи́м тя і просла́вим вели́чіє і си́лу твою́ і досто́йную піснь принесе́м ті, вопію́ще і глаго́люще: тебі́ ублажа́єм, святи́телю; тебі́ воспіва́єм, світи́льниче; тебі́ покланя́ємся, о́тче Са́вво! Моли́, моли́мтися, спасти́ся пою́щим святу́ю твою́ па́м'ять. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Правосла́вія наста́вниче, / благоче́стія учи́телю і чистоти́, / вселе́нния світи́льниче, / архієре́єв Богодухнове́нноє удобре́ніє, / Са́вво прему́дре, / уче́ньми твої́ми вся просвіти́л єси́, / цівни́це духо́вная. // Моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Струя́ми слез твої́х, Богоно́сне Са́вво, / це́рков тіле́сную очи́стив, / слуга́ бисть Святи́я Тро́йці, / сохраня́й оте́чество своє́ непобіди́мо, // тому́ бо ти єси́ утвержде́ніє."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Са́вво, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст преподобному Євфимію Великому","e":"Akathist to our Venerable Father Euthymius the Great","secs":[{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом Всеви́дящим в слуги́ Себі́ пре́жде рожде́нія твоєго́, пло́де кра́сний роди́телей бесчадних, і́м'я нося́й утіше́нію тезоімени́тоє і воі́стину яви́вийся утіше́ніє мно́гим, моли́ Го́спода, Єму́же послужи́л єси́ ві́рне, ізба́вити ни от вся́каго зла, да ра́достно вопіє́м ті:","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Ікос 1","ps":["А́нгельському чи́ну посвяти́ти тя обіща́ша роди́телі твоя́, Євфи́міє, єще́ пре́жде рожде́нія твоєго́: сей вели́кий обі́т соверша́ющи ма́тер твоя́ Діони́сія, приведе́ тя, о́трока би́вша, ко бра́ту своєму́ пресви́теру Євдоксі́ю: сей же отведе́ тя ко Мелитійському єпи́скопу Євтро́пію, сказу́юще єму́ о виді́нії і гла́се Боже́ственнім, возвестившим рожде́ніє твоє́. Возра́довася же єпи́скоп сему́, возопи́:","Ра́дуйся, блаже́нноє отроча́, я́ко воі́стину Дух Бо́жий почи́ на тебі́.","Ра́дуйся, ди́вним промишле́нієм Бо́жиїм от ю́ности мир оста́вивий.","Ра́дуйся, возлюби́вий тишину́ і безмо́лвіє.","Ра́дуйся, учи́телей твої́х Ака́кия і Синодія вели́коє утіше́ніє.","Ра́дуйся, украше́ніє Це́ркве на́шея яви́вийся.","Ра́дуйся, я́ко ма́тер твоя́ блаже́нная Діони́сія, ві́рне Це́ркве послужи́вшая, дияконисса поста́вися.","Ра́дуйся, в чистоті́ душе́вній і тіле́сній воспитавийся.","Ра́дуйся, жизнь свою́ безраздельне Го́сподеві вручивий.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 2","ps":["Ви́дя єпи́скоп Мелитійськия Це́ркві усе́рдноє твоє́, Євфи́міє, к науче́нію боже́ственних книг, та́же ді́вственноє і доброді́тельноє житіє́ твоє́, поста́ви тя пресви́тера, і вручи́ ті старейшество і попече́ніє о монастирі́х. Ти же, блаже́нне, возскорбел єси́ о сем, возлюби́вий безмо́лвіє і є́же в тишині́ пі́ти Бо́гу а́нгельськи: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом му́дрости боже́ственния просвіще́нний, Євфи́міє, уясня́я, я́ко ра́ди спасе́нія душі́ твоєя́ поле́зніє єсть безмо́лвноє уєдине́ніє, не́же нача́льствовати, укрился єси́ в приста́нище небу́рноє в Ла́врі Фаранстей, і та́мо Го́сподеві угожда́л єси́, сего́ ра́ди зове́м ті такова́я:","Ра́дуйся, смиреннейший па́че всіх і́ноков.","Ра́дуйся, поста́вленний старейшим над ни́ми.","Ра́дуйся, о монастирі́х попечи́телю.","Ра́дуйся, монашеського житія́ рачи́телю.","Ра́дуйся, похвали́ челові́чеськія возненави́дівий.","Ра́дуйся, сих ра́ди в Ла́вру Фаранськую бежавий.","Ра́дуйся, всели́вийся в ке́ллії уєдине́нній.","Ра́дуйся, та́мо от трудо́в рук свої́х питавийся, Бо́гу непреста́нную хвалу́ воздава́л єси́.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 3","ps":["Си́лою братнея любві́ свя́зани би́ша, преподо́бнії Євфи́міє і Феокти́сте, я́коби в двух тілесі́х єди́ну ду́шу і єди́ну во́лю імі́вшії, навико́ша на вся́кий год во осьми́й день по пра́здниці Богоявле́нія Госпо́дня ісходи́ти в пусти́ню Кутиллійськую, іді́же да́же до светлого Христо́ва Воскресе́нія пребива́ху посто́м плоть свою́ ізнуря́я, душі́ же веселя́ще пі́снію: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще жела́ніє соверше́ннаго уєдине́нія, обріто́ста святі́ї дру́зі пеще́ру і возра́довастася о ней, я́ко о Госпо́днем указа́нії і́ма мі́ста, і па́ки не возвраща́яся в Ла́вру, вселистася в той пеще́рі, би́лієм пита́ющеся. Ви́дяще таково́є му́дроє устроє́ніє мона́шеськоє взива́єм ті, преподо́бне о́тче Євфи́міє, си́це:","Ра́дуйся, ра́ди уєдине́нія оста́вивий Ла́вру.","Ра́дуйся, у́зами святи́я дру́жби с Феоктистом сочетанний, ку́пно с ним в моли́тві ко Єди́ному Бо́гу пребива́вий.","Ра́дуйся, я́ко убі́жище ва́ше ві́домо сотвори́шася лю́дем і потеко́ша к вам жаждущия спасе́нія і от болі́зней ісціле́нія.","Ра́дуйся, я́ко приходя́щих к тебі́, о́тче Євфи́міє, направля́л єси́ к дру́гу твоєму́ Феокти́сту, не хотя́й лиши́тися безмо́лвія.","Ра́дуйся, я́ко в ма́лом вре́мені киновія зді учредися, я́ко пеще́ра ва́ша пе́рвіє звіре́м приста́нище би́вшая в Це́рков претвори́ся.","Ра́дуйся, я́ко бра́тія по́мисли своя́ тебі́ открива́ти навико́ша.","Ра́дуйся, я́ко поуча́л єси́ і́стинному мона́шеському путі́.","Ра́дуйся, я́ко полага́л єси́ спасе́ніє найпа́че в смире́нії і послуша́нії.","Ра́дуйся, науча́вий отсеченію во́лі своєя́.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 4","ps":["Бу́ри і м'яте́жа мирська́го біжа́вшії блаже́нни суть, і́же под покро́в Євфимієвой кино́вії укри́шася! І́бо обріто́ша ту мир і безмо́лвіє, па́че же тебі́, о́тче преподо́бне, наста́вника прему́драго, поучающаго о всем благода́рні к Бо́гу взива́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще бра́тія поуче́нія твоя́, о́тче Євфи́міє, умиляшася се́рдцем, ду́хом же к небесі́ устремляшася, тебі́ же, врачу́ душ їх, вопію́ще:","Ра́дуйся, наста́вниче прему́дрий.","Ра́дуйся, врачу́ющий духо́вния не́мощі безме́здно.","Ра́дуйся, призива́яй всіх храни́ти воздержа́ніє.","Ра́дуйся, науча́яй укріпля́ти па́м'ять сме́ртную.","Ра́дуйся, повелі́вий і́ноком не отмета́тися трудо́в тіле́сних.","Ра́дуйся, науча́яй подража́ти всім свято́му апо́столу Па́влу.","Ра́дуйся, поуча́яй боя́тися огня́ ві́чнаго.","Ра́дуйся, призива́яй найпа́че люби́ти сла́ву Ца́рствія Небе́снаго.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 5","ps":["Богоізбра́нная звізда́ яви́лся єси́, святи́й Євфи́міє, єгда́ нача́льник сарацин Аспеветь с боля́щим сино́м отроко́м Теревоном е́ллини су́ще, возжела́вше восприя́ти святу́ю Христо́ву ві́ру: яви́лся бо єси́, преподо́бне, сп'я́щу і пові́дал єси́ тому́, да при́йдеть к тебі́ в пусти́ню і ісціле́ніє обря́щеть. Пришедшим же їм, с во́ї сарацинськими к тебі́, ісціли́л єси́ боля́щаго о́трока Теревона, уверовавше же всі во Христа́ і креще́ніє свято́є от тебе́ приі́мше, Бо́гу ра́достно воспі́ша: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́діша і сли́шаша сія́ боля́щия, мно́зі нача́ша стекатися к тебі́, врачу́ безме́здний блаже́нне Євфи́міє, і ісціле́ніє получа́я, прославля́ху тя по всей страні́ той. Ти же, святи́й, не терп'я́ще сла́ви, оста́вил єси́ кинові́ю тай, взем с собо́ю єдиного от учени́к свої́х Дометія́на, ізидо́ша в пусти́нь при Мертвом мо́ре і обрі́тше ке́ллію ве́тхую при горі́ Марда, всели́лся єси́ с Дометія́ном, отту́ду пресели́лся в пеще́ру, іді́же іногда́ Дави́д скрива́шеся от лиця́ Сау́ла, і созда́л єси́, Євфи́міє, та́мо монасти́р, чудесе́м же тобо́ю творимим умно́жися сла́ва твоя́ і па́ки отше́л єси́, обрі́тше пеще́ру ма́лу близ кино́вії Феоктистови, всели́лся єси́ в ней до кончи́ни своєя́. Ми же ви́дяще такову́ю любо́в твою́ к безмо́лвію, со умиле́нієм восклиця́єм ті:","Ра́дуйся, пусти́нноє житіє́ найпа́че возлюби́вий.","Ра́дуйся, мно́гія неві́рния к ві́рі Христо́вой обрати́вий.","Ра́дуйся, манихейського злові́рія обличи́телю.","Ра́дуйся, правосла́вния христия́ни в і́стинній ві́рі укріпи́телю.","Ра́дуйся, чудеси́ твої́ми просла́вивий Бо́га.","Ра́дуйся, своє́й сі сла́ві проти́вник би́вий.","Ра́дуйся, мно́гі монастири́ та́же і Ла́вру вели́кую созда́вий.","Ра́дуйся, я́ко воспо́лни Госпо́дь оскуді́ніє хлі́ба, вина́ і єле́я по благослове́нії твоє́м.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 6","ps":["Пропові́дник і́стиннаго покая́нія, і послуша́нія бил єси́, вели́кий Євфи́міє, та́же увещаватель є́же непотре́бно єсть от своєго́ монастиря́ бі́гати, і́щущи лу́чшаго, но бла́го єсть пребива́ти в ке́ллії своє́й, терп'я́ще вся тяготи́ житія́ і́ночеськаго, Бо́гу же поя́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́в ду́хом проро́чеським, Євфи́міє, прозрі́л єси́ Анаста́сія сосудохранителя Патріа́рха би́ти, єгда́ той при́йде к тебі́, та́кожде і іни́я чудеса́ сотвори́л єси́: поуче́нієм же мно́гим бра́тію наставля́л єси́ і вразумля́л. І нас грі́шних і непотре́бних вразуми́ і научи́ о́бразом житія́ твоєго́ богоуго́дная твори́ти, пою́щих ті си́це:","Ра́дуйся, прозорли́вче, бу́дущая, а́ки настоя́щая зрі́вий.","Ра́дуйся, мно́гія боля́щия ісціли́вий.","Ра́дуйся, мно́гими наставленіями ученико́м твої́м о́брази покая́нія показа́вий.","Ра́дуйся, увіря́яй, я́ко не мі́сто, но душе́вноє устроє́ніє ко спасе́нію приво́дить хотя́щих спасти́ся.","Ра́дуйся, я́ко моли́твою твоє́ю дождь низве́л єси́ с небесі́.","Ра́дуйся, я́ко послу́ша Госпо́дь ви́ну моли́тви твоя́.","Ра́дуйся, я́ко мольба́ми твої́ми подаде́ Госпо́дь плодоро́діє ве́ліє землі́ той.","Ра́дуйся, я́ко поуче́нії твої́ми умно́жися і́ноці і́стинния в Ла́врі твоє́й.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 7","ps":["Хотя́ укріпи́ти і́стинную правосла́вную ві́ру, прия́л єси́, о́тче Євфи́міє, от учени́к свої́х Єпи́скопов Стефа́на і Іоа́нна, написа́ніє дія́ній четве́ртаго Вселе́нськаго Собо́ра і́же в Халкидо́ні, обличи́вшаго злоче́стіє Діоско́ра, патріа́рха Александрі́йськаго. Ті́мже возвісти́ся по всей пусти́ні Палестинстей, я́ко вели́кий Євфи́мій послі́дуєть Халкидонському Собо́ру. Сему́ ра́дующеся, воспі́ша і́ноці: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий враг і́стини, єрети́к Феодо́сій, лживими словеси́ оклеветав Халкидонський Собо́р, привлече́ к себі́ мно́гія, та́же цари́цю Євдокі́ю, і мно́гим лука́вством взи́де на престо́л патріаршій, отню́дуже нача́ть гна́ти держа́щия правосла́вную ві́ру, найпа́че же хотя́й привлещи́ в сі́ті своєя́ є́ресі преподо́бнаго Євфи́мія. Ми же тя, о́тче, а́ки сті́ну нези́блему правосла́вія зря́ще, та́ко зове́м ті:","Ра́дуйся, сто́лпе правосла́вія.","Ра́дуйся, стіно́ непоколеби́мая єрети́чеськими ві́три.","Ра́дуйся, пусти́нника Гера́сима заблу́ждшаго к і́стинній ві́рі па́ки обрати́вий.","Ра́дуйся, удали́вийся со мно́гими бра́тіями в пусти́ню.","Ра́дуйся, возврати́вийся па́ки в Ла́вру по паде́нії лжепатріарха Феодо́сія.","Ра́дуйся, я́ко об'ятий Боже́ственним огне́м со а́нгелом литургисающий, ви́дін бил єси́.","Ра́дуйся, прилі́жно бра́тію свою́ наставля́яй чи́стою со́вістію і стра́хом Бо́жиїм ко святи́м Христо́вим Та́йнам приступа́ти.","Ра́дуйся, прови́дяй ка́ко ки́йждо от бра́тій причаща́тися прихо́дить.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 8","ps":["Стра́нно і неразумливо Євтихієвою єресью прельще́нная цари́ця Євдокия, нача́ колеба́тися умо́м, не ві́дуще, ко́єго держа́тися іспові́данія. По́сланная же от преподо́бнаго Симео́на сто́лпника ко Євфи́мію і приї́мши поуче́нія єго́, я́ко подоба́ше держа́тися чети́ріх Вселе́нських Собо́ров, просвіти́ся ра́зумом, Бо́гу воспіва́я: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ в Бо́зі, блаже́нне Євфи́міє, сія́нієм житія́ твоєго́ привлека́я к себі́ но́вия ученики́: та́ко преподо́бний Са́вва, ю́ний бі, при́йде к тебі́ спасе́нія іски́й і іні́ї мно́зі, отвращающия о́чі своя́ от м'яте́жа жите́йского мо́ря, і к тебі́ небу́рному приста́нищу прите́кшії. Ти же оте́чеською любо́вію прийма́л єси́ вся, прозира́я, я́ко столпи́ Це́ркві сі́ї бу́дуть. Сего́ ра́ди зове́м ті, о́тче, си́це:","Ра́дуйся, я́ко мно́гия світи́ла к тебі́ стека́хуся.","Ра́дуйся, собира́яй, а́ки ко́кош под крилі́ своя́, всіх і́щущих і́ночеських по́двигов.","Ра́дуйся, я́ко в юном Са́вві прозрі́л єси́ вели́каго учи́теля мона́шества.","Ра́дуйся, двух пустинников Нитрі́йських Марти́рія і Ілію́ приє́мий.","Ра́дуйся, я́ко в сих прови́діл єси́ наслі́дники Престо́ла Апо́стола Іа́кова бра́та Госпо́дня, Патріа́рха Ієрусали́мськаго.","Ра́дуйся, я́ко сих ви́ну вземлющий с собо́ю в пусти́ню.","Ра́дуйся, я́ко та́мо от своєя́ руки́ сих вели́ких муже́й приобщил єси́ Святи́х Христо́вих Та́їн.","Ра́дуйся, возлюби́вий ученики́ своя́, і пі́стунствуяй їх оте́чеськи.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє ра́дости ісполня́шеся, ви́дя равноа́нгельноє житіє́ твоє́, вели́кий Євфи́міє, і умножившіїся о́крест тебі́ оби́телі і́ноков, в а́нгельськом чи́ні сла́в'ящих Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния не возмо́гуть досто́йно возвели́чити да́ра прозорливости твоєя́, преподо́бне, вся бо бу́дущая я́ко настоя́щая прови́дяй, мно́гая проро́чествовал єси́. Преклоня́я колі́на пред вели́чієм Бо́га та́ко просла́вившаго уго́дника Своєго́, зове́м благогові́йно:","Ра́дуйся, даро́в многообра́зних от Го́спода сподо́бивийся.","Ра́дуйся, прозорли́вче ди́вний.","Ра́дуйся, Анастасію сосудохранителю сан Патріа́рха прорекший.","Ра́дуйся, я́ко ісполнившемуся сему́ проро́честву всі дивля́хуся.","Ра́дуйся, цари́цю Євдокі́ю в правосла́вії укріпи́л єси́.","Ра́дуйся, той близькую предсказав кончи́ну.","Ра́дуйся, повелі́вий той пригото́витися ко ісхо́ду своєму́.","Ра́дуйся, я́ко проро́чество сіє́ іспо́лнися і блаже́нная Євдокия, мно́гих хра́мов строїтельниця, вско́рі почи́ о Го́споді.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 10","ps":["Спасе́нія жа́ждущим бил єси́, Євфи́міє преподо́бне, я́ко столп о́гненний, путеводя́й стра́нствующих во тьмі житія́ сего́ в зе́млю небе́снаго Ханаа́на, ра́достно Бо́гу вопію́щих: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв і поуче́ній твої́х, Євфи́міє, па́че о́бразом житія́ твоєго́ равноа́нгельнаго огражда́л єси́ ученико́в твої́х, от іскуше́ній пло́ті, ми́ра і дия́вола. Ви́дяще таково́є попече́ніє о ча́діх твої́х, с любо́вію зове́м ті:","Ра́дуйся, до́брий па́стирю ове́ць слове́сних.","Ра́дуйся, о́тче, о мно́зіх ча́діх твої́х веселя́щийся.","Ра́дуйся, Феокти́ста, і́скренняго дру́га і спо́стника твоєго́ в болі́зні посіти́вий і уті́шивий.","Ра́дуйся, цілова́ніє тому́ послі́днєє с любо́вію да́вий.","Ра́дуйся, пророкованного тобо́ю патріа́рха Анаста́сія, на погребе́ніє Феоктистово приби́вшаго, срі́тивий.","Ра́дуйся, сла́дці с ним бесі́ди наслади́вийся.","Ра́дуйся, преподо́бнаго Са́вву с собо́ю в пусти́ню появший.","Ра́дуйся, тому́ от жа́жди в путі́ ізнемо́гшу, от землі́ моли́твою твоє́ю во́ду ізведший.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 11","ps":["Пі́ніє моли́твенноє по оби́чаю соверша́л єси́, блаже́нний Євфи́міє, удаля́яся в пусти́ню во осьми́й день по пра́здниці Богоявле́нія Госпо́дня. Приближавшейся кончи́ні твоє́й, преподо́бне, прозира́я ту, восхоті́л єси́ в Ла́врі преби́ти, гото́в'ящися ко ісхо́ду своєму́, Бо́гу за вся благода́рні поя́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє житіє́ твоє́, вели́кий Євфи́міє, ко концю́ прибли́жися, і плоди́ виногра́да своєго́ гото́вился єси́ принести́ Домовлади́ці, ви́дяще же ся близ кончи́ни су́ща, собра́л єси́ пресві́тери лаврськия, даби́ послі́днєє наставле́ніє всім да́ти. Пла́кахуся же всі, я́ко ча́да, разлуча́ющися со отце́м свої́м, оба́че реко́ша к тебі́:","Ра́дуйся, вели́кий па́стирю ове́ць мно́гих.","Ра́дуйся, ві́ру і́стинную соблюди́й і той научи́вий заблудшия.","Ра́дуйся, послі́днєє твоє́ поуче́ніє да́вий ча́дом твої́м, да сою́з любве́ неруши́м в них пребу́деть.","Ра́дуйся, реки́й, я́ко не возмо́жно єсть без любве́ доброді́телі соверша́тися.","Ра́дуйся, па́ки реки́й, я́ко вся́кая доброді́тель любо́вію і смире́нієм крі́пка єсть.","Ра́дуйся, поучавий вся преда́нія і уста́ви монасти́рськия ніколи́же оставля́ти.","Ра́дуйся, повелі́вий, да врата́ монасти́рськия ніколи́же затворе́ни бу́дуть стра́нних ра́ди.","Ра́дуйся, повелі́вий та́же о ни́щих пещи́ся.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 12","ps":["«Благода́ть, а́ще обря́щу у Бо́га дерзнове́ніє, і́мам проси́ти, да бу́ду с ва́ми ду́хом всегда́» — рекл єси́ послі́днєє сло́во ученико́м свої́м, блаже́нне Євфи́міє, ті́ї же, пла́чущи о ісхо́ді твоє́м, сим сло́вом утешахуся і со умиле́нієм Го́сподеві взива́ху: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще труди́ твоя́, по́двиги і дарова́нія є́же от ма́лих літ обрі́л єси́ у Бо́га, восхваля́єм тя, святи́й преподо́бне о́тче, і с любо́вію вопіє́м ті:","Ра́дуйся, от ю́ности весь живо́т свой Го́сподеві преда́вий.","Ра́дуйся, возраставший от си́ли в си́лу.","Ра́дуйся, о́рле, ми́слію в го́рніх паря́й.","Ра́дуйся, в до́льних оби́телі земни́я а́нгелом созидавий.","Ра́дуйся, прозорливости да́ра сподо́бивийся от Влади́ки Христа́.","Ра́дуйся, ісціле́ній неоску́дний істо́чниче.","Ра́дуйся, вели́ких муже́й учи́телю.","Ра́дуйся, і по сме́рті, чад твої́х духо́вних ві́рний храни́телю.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 13","ps":["О, пречу́дний і пресла́вний о́тче Євфи́міє! Прийми́ от нас непотре́бних моле́ніє сіє́ ма́лоє, і не осуди́ грі́шних уст, дерза́ющих сла́вити твоя́ труди́, по́двиги і чудеса́, да ми́лостивно призира́яй на всіх спасе́нія взиску́ющих, і о нас Го́сподеві моля́ся да очи́стимся от земни́я суєти́, чи́стим се́рдцем воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельському чи́ну посвяти́ти тя обіща́ша роди́телі твоя́, Євфи́міє, єще́ пре́жде рожде́нія твоєго́: сей вели́кий обі́т соверша́ющи ма́тер твоя́ Діони́сія, приведе́ тя, о́трока би́вша, ко бра́ту своєму́ пресви́теру Євдоксі́ю: сей же отведе́ тя ко Мелитійському єпи́скопу Євтро́пію, сказу́юще єму́ о виді́нії і гла́се Боже́ственнім, возвестившим рожде́ніє твоє́. Возра́довася же єпи́скоп сему́, возопи́:","Ра́дуйся, блаже́нноє отроча́, я́ко воі́стину Дух Бо́жий почи́ на тебі́.","Ра́дуйся, ди́вним промишле́нієм Бо́жиїм от ю́ности мир оста́вивий.","Ра́дуйся, возлюби́вий тишину́ і безмо́лвіє.","Ра́дуйся, учи́телей твої́х Ака́кия і Синодія вели́коє утіше́ніє.","Ра́дуйся, украше́ніє Це́ркве на́шея яви́вийся.","Ра́дуйся, я́ко ма́тер твоя́ блаже́нная Діони́сія, ві́рне Це́ркве послужи́вшая, дияконисса поста́вися.","Ра́дуйся, в чистоті́ душе́вній і тіле́сній воспитавийся.","Ра́дуйся, жизнь свою́ безраздельне Го́сподеві вручивий.","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Кондак 1","ps":["Ізбра́нний Бо́гом Всеви́дящим в слуги́ Себі́ пре́жде рожде́нія твоєго́, пло́де кра́сний роди́телей бесчадних, і́м'я нося́й утіше́нію тезоімени́тоє і воі́стину яви́вийся утіше́ніє мно́гим, моли́ Го́спода, Єму́же послужи́л єси́ ві́рне, ізба́вити ни от вся́каго зла, да ра́достно вопіє́м ті:","Ра́дуйся, о́тче преподо́бне, вели́кий Євфи́міє."]},{"h":"Молитва","ps":["Ди́вний і пресла́вний уго́дниче Христо́в, вели́кий о́тче Євфи́міє, от свята́го черто́га, іді́же ти со всі́ми святи́ми лику́єши, при́зри на нас, во мра́ці житія́ сего́ су́щих, і научи́ ни презира́ти вся, я́же в ми́рі нариця́ються блага́я. Научи́ нас люби́ти бли́жнія своя́, терпі́ти оби́ди і поноше́нія, ско́рби і болі́зні, в смире́нії благодаря́ще Бо́га. Научи́ нас моли́тися і ка́ятися во грісі́х свої́х, очи́ститися нам от вся́кия скве́рни. Умоли́ Го́спода, Єму́же послужи́л єси́ от ю́ности своєя́ да́же до ста́рости масти́тій, да сподо́бимся і ми, раби́ неключи́мії, со світи́льники горя́щими усрі́сти Жениха́ Христа́ і с Ним вни́ти в черто́г украше́нний Ца́рствія Єго́. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Весели́ся пусти́ня неражда́ющая, / благоду́шствуй неболя́щая, / я́ко умно́жи тебі́ ча́да муж жела́ній духо́вних, / благоче́стієм насади́в, / воздержа́нієм воспита́в доброді́телей в соверше́нство. / Того́ моли́твами Христе́ Бо́же, // умири́ живо́т наш."]},{"h":"Кондак, глас 8","ps":["В честні́м рождестві́ твоє́м ра́дость твар обрі́те, / і в Боже́ственній па́м'яті твоє́й, преподо́бне, / благоду́шіє прия́т мно́гих твої́х чуде́с, / от ни́хже пода́ждь бога́тно в ду́ші на́ша, і очи́сти гріхо́в скве́рни, // я́ко да поє́м: аллилу́я."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Євфи́міє, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов // і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святителю Феодосію, архієпископу Чернігівському","e":"Akathist to St Theodosius, Archbishop of Chernihiv","secs":[{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче, вели́кий уго́дниче Христо́в, святи́телю о́тче Феодо́сіє, нетлі́нієм моще́й твої́х і мно́жеством чуде́с от Бо́га просла́вленний, в пі́сніх ра́достних ублажа́єм тя, засту́пника на́шего. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свобожда́й, да зове́м ті:","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті яви́лся єси́, богому́дре Феодо́сіє, а́нгельськими нра́ви ізмла́да себі́ украша́я; ті́мже і А́нгел це́ркве Черні́говськия досто́йні поста́влен бил єси́ от Бо́га, всіх наставля́я ко спасе́нію і всім явля́я в себі́ пра́вило ві́ри і о́браз кро́тости, воздержа́нія же і любве́. Сего́ ра́ди, ча́да твоя́ су́ще, любо́вію вопіє́м ті си́це:","Ра́дуйся, А́нгеле земни́й і челові́че небе́сний;","ра́дуйся, небе́сних сил собесі́дниче і сослужи́телю.","Ра́дуйся, в житії́ твоє́м безпло́тним поревнова́вий;","ра́дуйся, і по сме́рті с ни́ми водвори́вийся.","Ра́дуйся, от ю́ности Христа́ всім се́рдцем твої́м возлюби́вий;","ра́дуйся, от у́тра жи́зні твоєя́ Тому́ єди́ному порабо́тавий.","Ра́дуйся, вся за́повіді Госпо́дні ві́рно і непоро́чно сохрани́вий;","ра́дуйся, мног плод духо́вний о Христі́ сотвори́вий.","Ра́дуйся, усе́рдною моли́твою дух твой окрили́вий;","ра́дуйся, чту́щих любо́вію па́м'ять твою́ от бід покрива́ющий.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 2","ps":["Ви́дів суєту́ ми́ра сего́ скороги́бнущую, всім се́рдцем возжела́л єси́, о́тче Феодо́сіє, мир сей оста́вити і во і́ночестві Бо́гу послужи́ти. Ті́мже і́го Христо́во благо́є і ле́гкоє усе́рдні восприя́в, і́нок святи́я оби́телі Кі́єво-Пече́рськия смире́н і послушли́в бил єси́, воспіва́я всіх Творцю́ а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний твой ви́дів, святи́тель Ки́євський Діони́сій поста́ви тя, Феодо́сіє, архидия́кона собо́рния це́ркве Софі́ї Прему́дрости Бо́жієй, да слу́жиши олтарю́ Госпо́дню при соверше́нії Та́їн Бо́жиїх. Ми же, в тебі́ ізбра́нний сосу́д Ду́ха Свята́го ві́дуще, со умиле́нієм зове́м ті сицева́я:","Ра́дуйся, под кро́вом чудотво́рцев Пече́рських нача́ло по́двигов твої́х положи́вий;","ра́дуйся, от ю́ности доброді́тельми мона́шеськаго житія́ преізря́дно себі́ украси́вий.","Ра́дуйся, і́ноков пресві́тлая красото́;","ра́дуйся, по́стников пресла́вная похвало́.","Ра́дуйся, святи́телей благогові́йних люби́мий собесі́дниче;","ра́дуйся, послуша́нія нелицемі́рний рачи́телю.","Ра́дуйся, подви́жниче смире́нний, на Го́спода все упова́ніє возложи́вий;","ра́дуйся, уєдине́ннаго житія́ до́брий ревни́телю.","Ра́дуйся, ізбра́нниче Христо́в преблаже́нний;","ра́дуйся, Бо́гом да́нний нам засту́пниче непреобори́мий.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 3","ps":["Си́ла Бо́жия осіни́ тя, о́тче Феодо́сіє, єгда́ во ієре́я посвяще́н бил єси́ от святи́теля Діони́сія і во ігу́мена оби́телі Корсу́нськия от него́ поста́влен, да пасе́ши Христо́во ста́до і руково́диши і́ноки ко спасе́нію, воспіва́я ку́пно с ни́ми хвале́бную піснь в Тро́йці сла́вимому Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я смире́ніє нелицемі́рноє, прах і пе́пел себі́ іменова́л єси́, преблаже́нне Феодо́сіє, і запреще́ніє от архієре́я, непови́нен сий, безро́потно поне́сл єси́; ті́мже і ми, ублажа́юще таково́є, воі́стину христоподража́тельноє, незло́біє твоє́, воспіва́єм тебі́ си́це:","Ра́дуйся, а́гнче незло́бивий, нікому́же зла за зло возда́вий;","ра́дуйся, я́ко запреще́ніє архієре́йськоє нося́, послуша́ніє вели́коє яви́л єси́.","Ра́дуйся, я́ко тогда́ і єпитрахи́ли косну́тися не дерза́л єси́;","ра́дуйся, смире́нієм і преда́нієм себі́ во во́лю Бо́жию врага́ побіди́вий.","Ра́дуйся, і́ноче боголюбе́зний, преподо́бієм і кро́тостію благоукраше́нний;","ра́дуйся, по́стничеським житіє́м, я́ко безкро́вним му́ченичеством увінча́нний.","Ра́дуйся, мона́шествующим оте́ць і наста́вник богому́дрий;","ра́дуйся, оби́телей і́ночеських многоо́питний руководи́телю.","Ра́дуйся, Престо́ла Бо́жия ві́рний і благогові́йний служи́телю;","ра́дуйся, пред Бо́гом те́плий о нас хода́таю.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 4","ps":["Бу́рю гоне́ній на Це́рков Бо́жию во гра́ді Ки́єве воздви́же мудрова́ніє лати́нськоє; ти же, богому́дре Феодо́сіє, во ігу́мена оби́телі Ви́дубецькия тогда́ поста́влен бив, сію́ от лжеуче́нія огради́л єси́, утвержда́я бра́тію свою́ в правосла́вній ві́рі непоро́чно воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав богоуго́дноє житіє́ твоє́, о́тче Феодо́сіє, святи́тель Бо́жий Ла́зар, призва́ тя от Ки́єва в Черни́гов і, поста́вив во архімандрі́та пречестни́я оби́телі Єле́цькия, сотвори́ помо́щника себе́ во управле́нії церко́внім; ти же с любо́вію сино́внею послужи́л єси́ єму́ і воі́стину досто́їн яви́лся єси́, да воспіва́єм ті сицева́я:","Ра́дуйся, ста́рцю святи́телю с любо́вію послужи́вий;","ра́дуйся, я́ко син отцю́ во всем єму́ послу́шен би́вий.","Ра́дуйся, ста́рость єго́ упоко́ївий;","ра́дуйся, труди́ святи́тельськия єму́ облегчи́вий.","Ра́дуйся, благолі́пія церко́внаго усе́рдний рачи́телю;","ра́дуйся, преда́ній апо́стольських ві́рний храни́телю.","Ра́дуйся, пра́вди ре́вностний блюсти́телю;","ра́дуйся, до́лга па́стирськаго непоколеби́мий ісполни́телю.","Ра́дуйся, олтаря́ Госпо́дня служи́телю непоро́чний;","ра́дуйся, па́стирем сві́тлий о́бразе.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 5","ps":["Боготе́чную звізду́, ко го́рнему Ієрусали́му путеводя́щую і доброді́тельми сві́тло сія́ющую, зря́ще тя, преди́вний Феодо́сіє, і́ноці же і мирсті́ї с любо́вію послі́доваху тебі́, внима́юще твоєму́ уче́нію душеполе́зному і взира́юще на о́браз чи́стаго житія́ твоєго́, поуча́хуся взива́ти с тобо́ю Бо́гу, ди́вному во святи́х Свої́х: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів себі́ святи́тель Ла́зар ста́ростію преутружде́на і в си́лах тіле́сних ізнемо́гша, возжела́ імі́ти тя, Феодо́сіє, преє́мника по себі́ во святи́тельстві і проси́ Святі́йшаго Патріа́рха Моско́вськаго посвяти́ти тя во архієпи́скопа. Ми же в сем Бо́жиє зва́ніє, є́же на тебі́, уразумева́юще, любо́вію прославля́єм тя си́це:","Ра́дуйся, архієре́ю Бо́жий, от Предві́чнаго Архієре́я ди́вно предизбра́нний;","ра́дуйся, Апо́столов досто́йний преє́мниче і усе́рдний ревни́телю.","Ра́дуйся, святи́телю Христо́в, от собо́ра святи́телей украї́нських освяще́нний;","ра́дуйся, ієра́рше благи́й і нищелюби́вий.","Ра́дуйся, архіпа́стирю ми́лостивий і сострада́тельний;","ра́дуйся, святи́телєм Митрофа́ну і Дими́трію собесі́дниче і сопресто́льниче.","Ра́дуйся, архієре́єв правосла́вних красото́;","ра́дуйся, па́стирю до́брий, ду́шу твою́ за о́вці положи́ти гото́вий.","Ра́дуйся, учи́телю златослове́сний;","ра́дуйся, богосві́тлий світи́льниче Це́ркве Христо́ви, во тьмі ві́ка сего́ возсія́вший.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 6","ps":["Пропові́дник не сло́вом то́чію, но і ді́лом яви́лся єси́ Христо́ва уче́нія, святи́телю Феодо́сіє, я́ко па́стир до́брий, по о́бразу Пастиренача́льника Христа́ всіх с любо́вію наставля́я ко спасе́нію, всім о́браз житія́ по за́повідем Христо́вим подава́я і всіх поуча́я взива́ти при́сно Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко у́тро світоза́рноє, страні́ Черни́говстій, святи́телю Бо́жий Феодо́сіє, і па́ству, тебі́ вві́ренную, сві́том доброді́телей твої́х озари́л єси́, смире́нієм висо́кая стяжава́я і нищету́ і́ночеськую соблюда́я; вся бо, я́же імі́л єси́, неіму́щим усе́рдні раздава́л єси́. О сем див'я́щеся, я́ко нищелю́бця соверше́ннаго ублажа́єм тя, зову́ще:","Ра́дуйся, милосе́рдія істо́чниче неісчерпа́ємий;","ра́дуйся, си́рим прибі́жище благонаде́жноє.","Ра́дуйся, вдови́цям ми́лостивий покрови́телю;","ра́дуйся, а́лчущих неоску́дний пита́телю.","Ра́дуйся, оби́димим ско́рий засту́пниче;","ра́дуйся, скорб'я́щим благонаде́жний уті́шителю.","Ра́дуйся, су́щим в біда́х гото́вий помо́щниче;","ра́дуйся, младе́нцем до́брий воспита́телю.","Ра́дуйся, ю́ношам і ді́вам в цілому́дрії наста́вниче;","ра́дуйся, ста́рцем і немощни́м тве́рдоє укріпле́ніє.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 7","ps":["Хотя́ всім се́рдцем твої́м єди́ному Го́споду благоугожда́ти, по́двигом до́брим до конця́ подвиза́лся єси́, Феодо́сіє, труди́ к трудо́м во смире́нії прилага́я, посто́м і бді́нієм с моли́твою плоть твою́ умерщвля́я і любо́вію всіх согріва́я. Ті́мже і сподо́бился єси́ єще́ на землі́ досто́йно і пра́ведно воспіва́ти а́нгельськую піснь Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя моли́твенника і чудотво́рця преди́внаго яви́ Госпо́дь в страні́ Украї́нській, святи́телю о́тче Феодо́сіє; ті́мже і сві́тло красу́ється тобо́ю Це́рков Правосла́вная, я́ко дерзнове́ніє ве́ліє ко Христу́ і́маши, Єму́же моли́ся, святи́телю, о нас грі́шних, любо́вію тебі́ вопію́щих сицева́я:","Ра́дуйся, пресві́тлий світи́льниче ві́ри правосла́вния;","ра́дуйся, правосла́вія стра́же неусипа́ющий.","Ра́дуйся, благоче́стія ре́вностний побо́рниче;","ра́дуйся, Це́ркве Бо́жия сто́лпе непоколеби́мий.","Ра́дуйся, хра́мино доброді́телей приукраше́нная;","ра́дуйся, безстра́стія і чистоти́ ревни́телю преізря́дний.","Ра́дуйся, моли́тви сокро́вище неістощи́моє;","ра́дуйся, та́їн Бо́жиїх ві́рний строї́телю.","Ра́дуйся, па́ству твою́ во ві́рі і благоче́стії соблюда́яй;","ра́дуйся, со святи́ми сликова́нія в Небе́сном Ца́рствії сподо́бивийся.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є богоуго́дні соверши́в, святи́телю о́тче Феодо́сіє, свя́то і пра́ведно почи́л єси́ о Го́споді сном сме́рти, я́же бисть тебі́ прохожде́ніє от трудо́в на поко́й ві́чний; прия́л бо єси́ от Христа́ Бо́га віне́ць сла́ви нетлі́нний і водвори́лся єси́ со святи́ми воспіва́ти Єму́ ві́чно хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь єси́ любо́в неоскудіва́ющая, святи́телю Бо́жий Феодо́сіє; я́коже бо в житії́ сем, та́ко і по преставле́нії к Бо́гу чад твої́х не оставля́єши; на всіх, к тебі́ ві́рою притека́ющих, ми́лостивне призира́єши, боля́щим ісціле́ніє подава́я, скорб'я́щих утіша́я, от бід избавля́я. Сего́ ра́ди, благода́рні су́ще, воспіва́єм ті си́це:","Ра́дуйся, нищету́ духо́вную от ю́ности возлюби́вий;","ра́дуйся, Христу́ в ме́ньших бра́тіях Єго́ ві́рно послужи́вий.","Ра́дуйся, две́рі милосе́рдія Бо́жия нам отверза́ющий;","ра́дуйся, гнів Бо́жий, пра́ведно на ни дви́жимий, на ми́лость прелага́ющий.","Ра́дуйся, по отше́ствії твоє́м к Бо́гу с на́ми пребива́ющий;","ра́дуйся, умерщвле́нния гріха́ми ду́ші благода́тію Христо́вою оживля́ющий.","Ра́дуйся, істо́чниче сострада́нія к лю́дем приснотеку́щий;","ра́дуйся, омраче́нних заблужде́ніями бла́гостний просвіти́телю.","Ра́дуйся, с небе́сних висо́т на ско́рби на́ші призира́ющий;","ра́дуйся, всіх нас любо́вію твоє́ю об'є́млющий.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 9","ps":["Всі лю́діє черни́говстії просла́виша Бо́га, єгда́ усли́шаша о пресла́вном явле́нії твоє́м, святи́телю Феодо́сіє, преє́мнику твоєму́ архієпи́скопу Іоа́нну, єго́же от неду́га тя́жка ісціли́л єси́, явля́я дерзнове́ніє твоє́ ко Го́споду. Сего́ ра́ди і потща́ся гроб твой благоукраси́ти і подо́біє лиця́ твоєго́ над ним поста́вити, зови́й ди́вному во святи́х Свої́х Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть восхвали́ти тя по достоя́нію, ві́чния сла́ви досто́йнаго, святи́телю о́тче Феодо́сіє; і кто мо́жеть пові́дати мно́гая і пресла́вная чудеса́ твоя́, я́же істочи́л єси́ от нетлі́нних моще́й і іко́н твої́х святи́х; о сем у́бо ра́дующеся і Бо́га, святи́х Свої́х прославля́ющаго, сла́в'яще, вопіє́м ті си́це:","Ра́дуйся, в пресві́тлих ра́йських черто́зіх обита́ющий;","ра́дуйся, нетлі́нієм моще́й твої́х зарю́ о́бщаго воскресе́нія нам предпоказу́ющий.","Ра́дуйся, во виді́ніїх во бла́го ві́рующим явля́ющийся;","ра́дуйся, в со́ніях на моли́тву к твоєму́ хода́тайству призива́ющий.","Ра́дуйся, сле́зи і воздиха́нія скорб'я́щих с любо́вію утоля́ющий;","ра́дуйся, проше́нія тружда́ющихся і обремене́нних ско́ро ісполня́ющий.","Ра́дуйся, от внеза́пния сме́рті ві́рних ізбавля́ющий;","ра́дуйся, да́нния Бо́гу обі́ти ісполня́ти побужда́ющий.","Ра́дуйся, сліпи́м прозрі́ніє, глухи́м сли́шаніє подаю́щий;","ра́дуйся, о́тче чадолюби́вий, я́коже ко́кош под крилі́, духо́вная ча́да твоя́ у гро́ба твоєго́ собира́ющий.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 10","ps":["Спасе́ніє ві́чноє унаслі́довал єси́, святи́телю Феодо́сіє, і сві́тло ни́ні лику́єши со А́нгели і всі́ми святи́ми, при́сно созерца́я пресві́тлоє лице́ Христа́ Бо́га на́шего, Єго́же моли́ти не преста́й за ни грі́шния, да твої́м заступле́нієм сподо́бимся ку́пно с тобо́ю воспіва́ти Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ огражде́нія в Це́ркві Правосла́вній явля́єшися, святи́телю Бо́жий, мно́жеством ди́вних чуде́с твої́х ві́рния утвержда́ющая і явле́нієм си́ли Бо́жієй вся єрети́чеськая мудрова́нія отража́ющая; наста́вников бо раско́ла нетлі́нієм моще́й твої́х зіло́ удиви́л єси́ і іспові́дати і́стину правосла́вія возбуди́л єси́. Ті́мже со стра́хом і благогові́нієм вку́пі с ві́рними взива́ху ті си́це:","Ра́дуйся, прославле́нієм моще́й твої́х всіх нас ра́дости іспо́лнивий;","ра́дуйся, нетлі́нієм тілесе́ твоєго́ неві́ріє глаго́лемих старообря́дцев во ві́ру претвори́вий.","Ра́дуйся, є́ресь шту́нди чудеси́ пресла́вними посрами́вий;","ра́дуйся, жену́ от лю́торови є́ресі кре́стноє зна́меніє правосла́вні полага́ти научи́вий.","Ра́дуйся, младе́нцю сліпо́му у моще́й твої́х внеза́пу прозрі́ніє дарова́вий;","ра́дуйся, немотству́ющий язи́к пома́занієм єле́я от лампа́ди твоєя́ разріши́вий.","Ра́дуйся, тім же єле́єм стру́пи неісці́льния ісціля́яй;","ра́дуйся, близ сме́рти су́щих боля́щих к жи́зні возвраща́яй.","Ра́дуйся, я́ко лише́ннії ра́зума у моще́й твої́х благода́тію Христо́вою ісціля́ються;","ра́дуйся, я́ко і пелени́ от гро́ба твоєго́ чудоді́йствують.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 11","ps":["Пі́ніє моли́твенноє не умолка́ше у моще́й твої́х, святи́телю Феодо́сіє, от дне погребе́нія да́же до дне прославле́нія твоєго́ со святи́ми, єгда́ собо́р святи́телей Це́ркве Украї́нськия со сла́вою із пеще́ри мо́щі твоя́ ізнесе́ і в собо́рній це́ркві гра́да Черни́гова на о́бщеє поклоне́ніє че́стне положи́. Прийми́ у́бо і на́ше смире́нноє пі́ніє хвале́бноє і помози́ нам покая́нієм очи́ститися, да во ісполне́нії за́повідей Христо́вих преуспіва́юще і тобо́ю наставля́ємі, с тобо́ю благода́рственні вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льник благода́тний бив в житії́ твоє́м, святи́телю Феодо́сіє, ти́хим сві́том смире́нія і любве́ на сві́щниці Це́ркве Христо́ви сія́ющий, і по преставле́нії твоє́м возсія́л єси́, я́ко со́лнце, преди́вними чудеси́ мглу раско́ла і єресе́й разгоня́я і ві́рних сердця́ к Бо́гу обраща́я. Ті́мже, с любо́вію пра́зднующе святу́ю па́м'ять твою́, вопіє́м ті:","Ра́дуйся, звіздо́ лучеза́рная, над земле́ю черни́говською возсія́вшая;","ра́дуйся, і всю страну́ Украї́нськую сві́том свої́м озари́вшая.","Ра́дуйся, гра́да Черни́гова сла́во і огражде́ніє;","ра́дуйся, всея́ землі́ на́шея стра́же неуси́пний і те́плий моли́твенниче.","Ра́дуйся, у Престо́ла Царя́ ца́рствующих за царя́ на́шего предста́тельствующий;","ра́дуйся, я́ко і́м'я твоє́ по всей страні́ на́шей от конця́ в коне́ць прославля́ється.","Ра́дуйся, я́ко явле́нії твої́ми неві́рния во ві́ру правосла́вную обраща́єши;","ра́дуйся, я́ко чудеси́ твої́ми іносла́вния к правосла́вію наставля́єши.","Ра́дуйся, я́ко с небе́сними си́лами при́сно Бо́гу воспіва́єши;","ра́дуйся, я́ко на небесі́х ви́ну сла́ву Єго́ созерца́єши.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 12","ps":["Благода́ті Бо́жієй сосу́д ізбра́нний бил єси́, святи́телю Феодо́сіє; благода́ть Бо́жию і в по́мощ не́мощі на́шей іспроси́ у Го́спода, да се́ю благода́тію спаса́ємі, присноборю́щия ни стра́сті побіди́м, і то́ю укріпля́ємі, Пода́теля всіх благ Го́спода Ісу́са всегда́ с тобо́ю прославля́єм, зову́ще Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще мно́гая і пресла́вная чудеса́ твоя́ і прославля́юще вели́кия по́двиги твоя́, святи́телю о́тче наш Феодо́сіє, со умиле́нієм се́рдця сла́вим, хва́лим і велича́єм возвели́чившаго тя Го́спода, в тебі́ я́вльшаго нам но́воє зна́меніє Своєго́ благоволе́нія к Це́ркві Правосла́вній, я́ко ві́чному столпу́ і утвержде́нію і́стини; тебі́ же, я́ко те́плому предста́телю на́шему пред Бо́гом, возглаша́єм сицева́я:","Ра́дуйся, во вертогра́ді Госпо́дні от у́тра до ве́чера жи́зні твоєя́ до́брі потруди́вийся;","ра́дуйся, в ра́дость Го́спода своєго́, я́ко раб благи́й і ві́рний, вше́дий.","Ра́дуйся, житіє́м твої́м путь в оби́телі небе́сния нам показа́вий;","ра́дуйся, вінце́м безсме́ртія і сла́ви небе́сния увінча́нний.","Ра́дуйся, не́ба церко́внаго звіздо́ пресві́тлая;","ра́дуйся, землі́ Украї́нськия похвало́ пречу́дная.","Ра́дуйся, я́ко со всі́ми святи́ми в го́рніх обита́єши;","ра́дуйся, я́ко і нас грі́шних на землі́ любо́вію посіща́єши.","Ра́дуйся, і́мже Христо́с просла́вися;","ра́дуйся, і́мже сатана́ посрами́ся.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 13","ps":["Овели́кий уго́дниче Бо́жий і чудотво́рче, святи́телю о́тче наш Феодо́сіє! Прийми́ сіє́ ма́лоє моле́ніє на́ше, в похвалу́ тебі́, а́ще і недосто́йні, оба́че с любо́вію сино́внею приноси́моє, і умоли́ Го́спода Бо́га ізба́витися нам от вся́ких бід, скорбе́й і напа́стей, от междоусо́бния бра́ні і внеза́пния сме́рти, і от муче́ній ві́чних в бу́дущем ві́ці, і сподо́битися во ві́чній жи́зні с тобо́ю воспіва́ти Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті яви́лся єси́, богому́дре Феодо́сіє, а́нгельськими нра́ви ізмла́да себі́ украша́я; ті́мже і А́нгел це́ркве Черні́говськия досто́йні поста́влен бил єси́ от Бо́га, всіх наставля́я ко спасе́нію і всім явля́я в себі́ пра́вило ві́ри і о́браз кро́тости, воздержа́нія же і любве́. Сего́ ра́ди, ча́да твоя́ су́ще, любо́вію вопіє́м ті си́це:","Ра́дуйся, А́нгеле земни́й і челові́че небе́сний;","ра́дуйся, небе́сних сил собесі́дниче і сослужи́телю.","Ра́дуйся, в житії́ твоє́м безпло́тним поревнова́вий;","ра́дуйся, і по сме́рті с ни́ми водвори́вийся.","Ра́дуйся, от ю́ности Христа́ всім се́рдцем твої́м возлюби́вий;","ра́дуйся, от у́тра жи́зні твоєя́ Тому́ єди́ному порабо́тавий.","Ра́дуйся, вся за́повіді Госпо́дні ві́рно і непоро́чно сохрани́вий;","ра́дуйся, мног плод духо́вний о Христі́ сотвори́вий.","Ра́дуйся, усе́рдною моли́твою дух твой окрили́вий;","ра́дуйся, чту́щих любо́вію па́м'ять твою́ от бід покрива́ющий.","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Кондак 1","ps":["Ізбра́нний чудотво́рче, вели́кий уго́дниче Христо́в, святи́телю о́тче Феодо́сіє, нетлі́нієм моще́й твої́х і мно́жеством чуде́с от Бо́га просла́вленний, в пі́сніх ра́достних ублажа́єм тя, засту́пника на́шего. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свобожда́й, да зове́м ті:","Ра́дуйся, уго́дниче Бо́жий, святи́телю Феодо́сіє, чудотво́рче пресла́вний."]},{"h":"Молитва","ps":["О свяще́нная главо́, крі́пкий наш моли́твенниче і засту́пниче, святи́телю Феодо́сіє, усли́ши нас, с ві́рою призива́ющих тя і усе́рдно припа́дающих к ра́ці честни́х і многоціле́бних моще́й твої́х (іли́: іко́ні твоє́й). Помина́й нас у Престо́ла Вседержи́телева і не преста́й моли́тися за ни. Ві́ми, я́ко гріхи́ на́ші разлуча́ють нас между́ на́ми і тобо́ю, і недосто́йни єсьми́ толи́каго отця́ і хода́тая. Но ти, бив подража́тель человіколю́бія Бо́жия, не преста́ни вопія́ о нас ко Го́споду, іспроси́ предста́тельством твої́м у Всеми́лостивійшаго Бо́га на́шего мир Це́ркві Єго́, на землі́ во́їнствующей, па́стирем єя́ си́лу ре́вностно подвиза́тися о спасе́нії люде́й. Умоли́ Небе́снаго Отця́ всім нам пода́ти дар, коєму́ждо благопотре́бен, ві́ру і́стинную, наде́жду тве́рдую і любо́в неоскудіва́ющую, градо́в на́ших утвержде́ніє, ми́ра умире́ніє, от гла́да і па́губи ізбавле́ніє, от наше́ствія іноплеме́нников сохране́ніє, ю́ним і младе́нцем благо́є во ві́рі возраста́ніє, ста́рим і немощни́м утіше́ніє і подкріпле́ніє, боля́щим ісціле́ніє, сирота́м і вдови́цям ми́лость і заступле́ніє, заблу́ждшим ісправле́ніє, бе́дствующим благовре́менную по́мощ. Не посрами́ нас в упова́нії на́шем, споспі́шествуй, я́ко оте́ць чадолюби́вий, і нам понести́ і́го Христо́во во благоду́шії і терпі́нії, і всіх упра́ви в ми́рі і покая́нії непости́дно сконча́ти живо́т свой і Ца́рствія Бо́жия наслі́дником би́ти, іді́же ти ни́ні водворя́єшися со А́нгели і всі́ми святи́ми, прославля́я Бо́га, в Тро́йці сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Преудобре́н во архієре́єх, святи́телю Феодо́сіє, / бил єси́ світи́ло своєму́ ста́ду, / та́же преста́вился єси́ во ві́чния оби́телі, / умоли́ у Престо́ла Царя́ Сла́ви ізба́витися нам от находя́щих на ни зол, // і спасти́ся душа́м на́шим, свя́те, моли́твами твої́ми."]},{"h":"Кондак, глас 4","ps":["Па́стирей Нача́льнику Христу́ труди́лся єси́, / святи́телю Феодо́сіє, / на па́жити духо́вній слове́сния твоя́ о́вці пита́я, / і ціле́бен дар от Христа́ Спа́са прия́л єси́, / во є́же не́мощі душе́вния і тіле́сния ціли́ти всіх, / с ві́рою к тебі́ приходя́щих. / Ті́мже і ни́ні, свя́те, моли́ся, / всім і́м'я твоє́ призива́ющим, / от наві́тов вра́жиїх спасти́ся // і поми́ловатися душа́м на́шим."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Феодо́сіє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]}];
export default D;
